import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Молитва пророку Іоанну, Предтечі і Хрестителю Господньому","e":"Prayer to the Prophet John, the Forerunner and Baptist of the Lord","secs":[{"h":"Тропар собору і усікновенню, глас 2","ps":["Па́м'ять пра́веднаго с похвала́ми, / тебі́ же довлі́єть свиді́тельство Госпо́днє, Предте́че: / пока́зал бо ся єси́ воі́стину і проро́ков честні́йший, / я́ко і в струя́х крести́ти сподо́бился єси́ Пропові́даннаго. / Ті́мже за і́стину пострада́в ра́дуяся, / благовісти́л єси́ і су́щим во а́ді Бо́га я́вльшагося пло́тію, / взе́млющаго гріх ми́ра, // і подаю́щаго нам ве́лію ми́лость."]},{"h":"Тропар зачаттю, глас 4","ps":["Пе́рвіє неражда́ющая непло́ди, возвесели́ся, / се бо зачала́ єси́ Со́лнця світи́льника я́ві, / просвіща́ти іму́ща всю вселе́нную, сліпото́ю неду́гующую. / Лику́й, Заха́ріє, вопія́ со дерзнове́нієм: // проро́к Ви́шняго єсть хотя́й роди́тися."]},{"h":"Тропар різдву, глас 4","ps":["Проро́че і Предте́че прише́ствія Христо́ва, / досто́йно восхвали́ти тя недоумі́єм ми, любо́вію чту́щії тя: / непло́дство бо ро́ждшия і о́тчеє безгла́сіє разріши́ся / сла́вним і честни́м твої́м рождество́м, // і воплоще́ніє Си́на Бо́жия ми́рові пропові́дується."]},{"h":"Тропар першому і другому знайденню глави, глас 4","ps":["От землі́ возсія́вши Предте́чева глава́, / лучи́ іспуща́єть нетлі́нія, ві́рним ісціле́ній, / сви́ше собира́єть мно́жество А́нгел, / до́лі же созива́єть челові́чеський род, // єдиногла́сную возсила́ти сла́ву Христу́ Бо́гу."]},{"h":"Тропар третьому знайденню глави, глас 4","ps":["Я́ко Боже́ственноє сокро́вище сокрове́нноє в землі́, / Христо́с откри́ главу́ твою́ нам, проро́че і Предте́че. / Всі у́бо соше́дшеся в сея́ обрі́теніє, / пі́сньми богоглаго́ливими Спа́са воспої́м, // спаса́юща нас от тлі́нія моли́твами твої́ми."]},{"h":"Тропар на перенесення правиці, глас 4","ps":["От за́пада возсія́вши Предте́чева рука́, / лучи́ іспуща́єть нетлі́нія ві́рним ісціле́ній, / сви́ше собира́єть мно́жество А́нгел, / до́лі же созива́єть челові́чеський род, // єдиногла́сно возсила́ти сла́ву Христу́ Бо́гу."]},{"h":"Кондак собору, глас 6","ps":["Плотська́го Твоєго́ прише́ствія убоя́вся Іорда́н, / стра́хом возвраща́шеся, / проро́чеськоє же служе́ніє ісполня́я Іоа́нн, / тре́петом спря́ташеся, / А́нгельстії чи́ни ужаса́хуся, / зря́ще Тя во струя́х пло́тію креща́єма, / і всі су́щії во тьмі озаря́хуся, // воспіва́юще Тя, я́вльшагося і просвіти́вшаго вся."]},{"h":"Кондак зачаттю, глас 1","ps":["Весели́ться сві́тло Заха́рія вели́кий / со всесла́вною Єлисаве́тію сопру́жницею, / досто́йно зачина́юще Іоа́нна Предте́чу, / єго́же Арха́нгел благовісти́, ра́дуяся, / і челові́ци достодо́лжно почти́м, // я́ко таї́нника благода́ті."]},{"h":"Кондак різдву, глас 3","ps":["Пре́жде непло́ди, днесь Христо́ва Предте́чу ражда́єть, / і той єсть ісполне́ніє вся́каго проро́чества, / Єго́же бо проро́ци пропові́даша, / на Сего́ во Іорда́ні ру́ку положи́в, // яви́ся Бо́жия Сло́ва проро́к, пропові́дник вку́пі і Предте́ча."]},{"h":"Кондак усікновенню, глас 5","ps":["Предте́чево сла́вноє усікнове́ніє, / смотре́ніє бисть ні́коє Боже́ственноє; / да і су́щим во а́ді Спа́сово пропові́сть прише́ствіє. / Да рида́єть у́бо Іроді́я, / беззако́нноє уби́йство іспроси́вши: / не зако́н бо Бо́жий, ні живи́й вік возлюби́, // но притво́рний, привре́менний."]},{"h":"Інший кондак усікновенню, глас 4","ps":["І́род, Предте́че, беззако́нновав, / жені́ подаде́ главу́ твою́ честну́ю, / є́йже покланя́ющеся, веселі́мся; / Іроді́я же пла́четь і рида́єть, / і І́род, і пляса́вшая."]},{"h":"Кондак першому і другому знайденню глави, глас 2","ps":["Про́роче Бо́жий і Предте́че благода́ті, / главу́ твою́ я́ко ши́пок свяще́ннійший от землі́ обрі́тше, / ісціле́нія всегда́ приє́млем, / і́бо па́ки, я́коже пре́жде // в ми́рі пропові́дуєши покая́ніє."]},{"h":"Кондак третьому знайденню глави, глас 6","ps":["Світоявле́нний і Боже́ственний в ми́рі столп, / со́лнця світи́льник, / Предте́ча, главу́ світоно́сную і Боже́ственную свою́ показа́вий в конці́х, / освяща́єть той ві́рно покланя́ющихся і взива́ющих: // Христо́в прему́дрий Крести́телю, спаси́ всіх нас."]},{"h":"Кондак на перенесення правиці, глас 6","ps":["У́мнаго Со́лнця світи́льник Боже́ственний Предте́ча, / показа́вий в конці́х світоно́сную свою́ десни́цю, / ни́ні на сі́вері озаря́єть є́ю блаже́нноє Оте́чество на́ше, / просвіща́я і освяща́я ві́рно покланя́ющихся, і Христу́ вопію́щих: / спаси́ нас моли́твами проро́ка Твоєго́, Царю́ Ви́шній."]},{"h":"Молитва перша","ps":["Крести́телю Христо́в, пропові́дниче покая́нія, ка́ющагося не пре́зри мене́, но совокупля́яся с во́ї Небе́сними, моли́ся ко Влади́ці за мене́, недосто́йнаго, уни́лаго, немощна́го і печа́льнаго, во мно́гія бі́ди впа́дшаго, утружде́ннаго бу́рними по́мисли ума́ моєго́. Аз бо єсьм верте́п злих діл, отню́дь не імі́яй конця́ гріхо́вному оби́чаю, пригвожде́н бо єсть ум мой земни́м веще́м. Что сотворю́? Не вім. І ко кому́ прибі́гну, да спасе́на бу́деть ду́ша моя́? То́кмо к тебі́, святи́й Іоа́нне, благода́ті тезоімені́те, я́ко тя пред Го́сподем по Богоро́дице вім бо́льша би́ти рожде́нних всіх, ти бо сподо́бился єси́ косну́тися верху́ Царя́ Христа́, взе́млющаго гріхи́ ми́ра, А́гнця Бо́жия. Єго́же моли́ за грі́шную мою́ ду́шу, да поне́ отни́ні, в пе́рвий на́десять час, понесу́ тяготу́ благу́ю і прийму́ мзду с послі́дніми. Єй, Крести́телю Христо́в, честни́й Предте́че, кра́йній Проро́че, пе́рвий во благода́ті му́чениче, по́стников і пусти́нников наста́вниче, чистоти́ учи́телю і бли́жній дру́же Христо́в! Тя молю́, к тебі́ прибіга́ю: не отри́ни мене́ от твоєго́ заступле́нія, но возста́ви м'я, низве́рженнаго мно́гими гріхи́. Обнови́ ду́шу мою́ покая́нієм, я́ко втори́м креще́нієм, поне́же обоєго́ нача́льник єси́: креще́нієм омива́яй прароди́тельний гріх, покая́нієм же очища́яй коєго́ждо ді́ло скве́рно. Очи́сти м'я, гріха́ми оскверне́ннаго, і пону́ди вни́ти, а́може нічто́же скве́рно вхо́дить, в Ца́рствіє Небе́сноє. Амі́нь."]},{"h":"Молитва друга","ps":["Крести́телю Христо́в, честни́й Предте́че, кра́йній проро́че, пе́рвий му́чениче, по́стников і пусти́нников наста́вниче, чистоти́ учи́телю і бли́жній дру́же Христо́в! Тя молю́, і тебі́ прибіга́ю не отри́ни мене́ от твоєго́ заступле́нія, не оста́ви м'я па́дшего мно́гими гріхи́; обнови́ ду́шу мою́ покая́нієм, я́ко втори́м креще́нієм; очи́сти м'я, гріхи́ оскверне́ннаго, і пону́ди вни́ти, а́може нічто́же скве́рно вхо́дить, в Ца́рствіє Небе́сноє. Амі́нь."]},{"h":"Величання різдву","ps":["Велича́єм тя, Предте́че Спа́сов Іоа́нне, і чтим є́же от непло́дове пресла́вноє рождество́ твоє́."]},{"h":"Величання усікновенню","ps":["Велича́єм тя, / Крести́телю Спа́сов Іоа́нне, / і почита́єм всі / честни́я твоєя́ глави́ // усікнове́ніє."]},{"h":"Величання знайденню","ps":["Велича́єм тя, / Крести́телю Спа́сов Іоа́нне, / і почита́єм всі / честни́я твоєя́ глави́ // обрі́теніє."]}],"notes":[]},{"u":"Молитва апостолам Петру і Павлу, первоверховним","e":"Prayer to the Apostles Peter and Paul, the Chief Apostles","secs":[{"h":"Тропар, глас 4","ps":["Апо́столов первопресто́льници, / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Тве́рдия і боговіща́нния пропові́дателі, / верх апо́столов Твої́х, Го́споди, / прия́л єси́ в наслажде́ніє благи́х Твої́х і поко́й: / болі́зні бо о́ніх і смерть прия́л єси́ па́че вся́каго всепло́дія, // Єди́не, сві́дий серде́чная."]},{"h":"Молитва перша","ps":["О пресла́внії апо́столи Пе́тре і Па́вле, ду́ші за Христа́ преда́вшії і кро́вію ва́шею па́жить Єго́ удобри́вшії! Усли́шіте чад ва́ших моли́тви і воздиха́нія, се́рдцем сокруше́нним ни́ні приноси́мия. Се бо беззако́ньми омрачи́хомся і того́ ра́ди біда́ми, я́коже ту́чами, обложи́хомся, єлея́ же до́браго житія́ обнища́хом зіло́ і не возмо́жем проти́витися волко́м хи́щним, і́же расхища́ти наслі́діє Бо́жиє де́рзостно тща́ться. О си́льнії! Понесі́те не́мощі на́ша, не отлуча́йтеся ду́хом от нас, да не разлучи́мся в коне́ць от любве́ Бо́жия, но крі́пким заступле́нієм ва́шим нас защиті́те, да поми́луєть Госпо́дь всіх нас, моли́тв ва́ших ра́ди, да істреби́ть же рукописа́ніє безмі́рних гріхо́в на́ших і да сподо́бит со всі́ми святи́ми блаже́ннаго Ца́рствія і бра́ка А́гнця Своєго́, Єму́же честь і сла́ва, і благодаре́ніє і поклоне́ніє, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святі́ї апо́столи Пе́тре і Па́вле, не отлуча́йтеся ду́хом от нас, грі́шних раб Бо́жиїх (імена́), да не разлучи́мся вконе́ць от любве́ Бо́жия, но крі́пким заступле́нієм ва́шим нас защиті́те, да поми́луєть Госпо́дь всіх нас моли́тв ва́ших ра́ди, да істреби́ть же рукописа́ніє безмі́рних гріхо́в на́ших, і да сподо́бит со всі́ми святи́ми блаже́ннаго Ца́рствія і бра́ка А́гнця Своєго́, Єму́же честь і сла́ва, і благодаре́ніє і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О верхо́внії апо́столе: Пе́тре, ві́ри Христо́вой тве́рдий ізобрази́телю, і Па́вле, сладковіща́тельная ла́стовиця уче́нія Госпо́дня! Зрим вас, а́ки многотеку́щую реку́ сказа́ній Христо́вих слове́с, істека́ющую от і́стинних нідр Бо́жиїх і всю глубину́ кла́дезя і́стин богооткрове́нних пред на́ми, жа́ждущими їх, открива́ющую. Зрим вас, а́ки світи́ла, с небесе́ то́ки теплоти́ любве́ боже́ственния нам уясня́ющия: ублажа́єм вас, приє́мших труди́ і по́ти, во є́же всі́яти уче́ній боже́ственних сі́мена: цілу́єм стопи́ ва́ша, обтека́вшия вся конці́ землі́, і в тре́петі гріхо́внім зрим глави́ ва́ша, смире́нно преклоне́нния к пречи́стим стопа́м Госпо́днім: єди́наго кре́стним путе́м (пові́шенієм) і друга́го ме́чним усіче́нієм. Уми́льно про́сим вас, святі́ї апо́столи, сотворі́те і нас в бу́єсти гріхо́вній преклоне́нними пред Учи́телем на́шим Го́сподом, сотворі́те го́рдості на́шей глави́ усікнове́ніє уче́нієм богооткрове́нним: глад душе́вний наш да утоли́ть Госпо́дь бра́шном, указу́ємим с сама́го не́ба, я́коже Петру́: — ти же, Па́вле, богонаси́щенний Христо́вих слове́с, потщи́ся і нас до тре́тьяго небесе́ возвісти́ твої́ми непреста́нними о нас ко Го́споду моли́твами, да і ми та́мо просла́вим с ли́ки а́нгельськими і апо́стольськими ди́внаго во святи́х свої́х Отця́ вся́чеських і Єго́ же посла́л в мир спаса́яй і наставля́яй к жи́зні ві́чной, Го́спода Ісу́са Христа́, і єдиносу́щнаго Їм Свята́го Ду́ха. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / апо́столи Христо́ви Пе́тре і Па́вле, / весь мир уче́ньми свої́ми просвети́вшия / і вся конці́ ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Молитва святителю Василію Великому, архієпископу Кесарії Каппадокійської","e":"Prayer to St Basil the Great, Archbishop of Caesarea in Cappadocia","secs":[{"h":"Тропар, глас 1","ps":["Во всю зе́млю ізи́де віща́ніє твоє́, / я́ко приє́мшую сло́во твоє́, / і́мже боголі́пно научи́л єси́, / єстество́ су́щих уясни́л єси́, / челові́чеськія оби́чаї украси́л єси́, / ца́рськоє свя́щеніє, о́тче преподо́бне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ основа́ніє непоколеби́моє Це́ркве, / подая́ всім некра́домоє госпо́дьство челові́ком, / запечатлі́я твої́ми велі́ньми, // небоявле́нне Васи́ліє, преподо́бне."]},{"h":"Молитва перша","ps":["О вели́кий во ієра́рсіх, вселе́нния учи́телю богому́дрий, преблаже́нне о́тче Васи́ліє! Ве́лія по́двиги і труди́ твоя́, я́же во сла́ву святи́я Це́ркве соверши́л єси́: ти іспові́дник тве́рдий і світи́льник ві́ри Христо́ви на землі́ бил єси́, сві́том Богові́дінія ві́рния озаря́яй, ло́жная уче́нія попаля́яй, і всему́ ми́ру сло́во спаси́тельния і́стини возвіща́яй. Ни́ні же, ве́ліє на небесі́х імі́яй дерзнове́ніє ко Святі́й Тро́йці, помози́ нам, со смире́нієм к тебі́ припа́дающим, тве́рдо і неізмі́нно святу́ю правосла́вную ві́ру до конця́ житія́ на́шего сохрани́ти, от малові́рія же, сомні́ній і колеба́нія во ві́рі соблюди́, да не прельще́ни бу́дем богопроти́вних і душепа́губних уче́ній словеса́ми. Дух ре́вности святи́я, є́юже ти пламені́л єси́, о пресла́вний Це́ркве Христо́ви па́стирю, возгрі́й предста́тельством твої́м і в нас, ї́хже Христо́с поста́ви би́ти па́стирями, да всеусе́рдно просвіща́єм і утвержда́єм в пра́вій ві́рі слове́сноє ста́до Христо́во. Іспроси́, о милосе́рдий святи́телю, от Отця́ сві́тов і всім, вся́кий дар коєму́ждо благопотре́бен: младе́нцем благо́є в стра́сі Бо́жиєм возраста́ніє, ю́ним целому́дріє, ста́рим і немощни́м укріпле́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, заблу́ждшим вразумле́ніє і ісправле́ніє, оби́димим заступле́ніє, сирота́м і вдови́цям защище́ніє, іскуша́ємим благода́тноє поможе́ніє, отше́дшим от сего́ вре́меннаго житія́, отце́м і бра́тіям на́шим блаже́нноє упокоє́ніє. Єй, свя́тче Бо́жий, при́зри ми́лостиво от оби́телей го́рніх на нас смире́нних, мно́гими собла́знами і напа́стьми обурева́ємих, і с землі́ приве́рженних возведи́ к висоті́ небе́сній. Препода́ждь нам, преблаги́й о́тче, твоє́ архипа́стирськоє і свято́є благослове́ніє, да о́ним осіня́ємії, в сіє́ но́воє лі́то і во все про́чеє вре́м'я живота́ на́шего в ми́рі, покая́нії і послуша́нії Святі́й Правосла́вной Це́ркві поживе́м, за́повіді Христо́ви усе́рдно творя́ще, по́двигом до́брим ві́ри подвиза́ющеся, і та́ко Ца́рствія Небе́снаго дости́гнем, іді́же с тобо́ю і всі́ми святи́ми сподо́би Тро́йцю Святу́ю, Єдиносу́щную і Неразді́льную, пі́ти і сла́вити во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий і пресвяти́й святи́телю о́тче Васи́ліє, пресла́вний вселе́нськия Це́ркве учи́телю, сла́ви Пресвяти́я Тро́йці всеусе́рдний побо́рниче, Ма́тере Бо́жия і Єя́ пренепоро́чнаго ді́вства предизбра́нний іспові́дниче, пресві́тлий чистоти́, смире́нія і терпі́нія о́бразе. Се аз многогрі́шний і недосто́йний на висоту́ небе́сную взира́ти, смире́нно молю́ тя, о прему́дрий Це́ркве Христо́ви учи́телю, научи́ м'я та́ко богобоя́зненно житіє́ своє́ проводи́ти, да нікогда́ же на путь, Бо́жиїм повелі́нієм протії́вен, уклоню́ся іли́ совраще́н бу́ду. Соблюди́ і ізба́ви м'я твої́м многомо́щним предста́тельством от собла́знов ми́ра і ко́зней дия́вольських, я́коже ізба́вил єси́ от них ю́ношу, от Сладча́йшаго Спаси́теля на́шего отступи́вша і во власть сатани́ впа́дша. Да́руй мні си́лу душе́вную усе́рдним би́ти подража́телем доброді́телей твої́х висо́ких: соді́лай м'я во ві́рі пра́вій тве́рда і непоколеби́ма, укріпи́ м'я малоду́шнаго в терпі́нії і упова́нії на Го́спода, возгрі́й в се́рдці моє́м і́стинную Христо́ву любо́в, да небе́сних благ па́че всіх жела́ю і і́ми услажда́юся. Іспроси́ мні у Го́спода і́скреннєє о грісі́х сокруше́ніє, да про́чеє вре́м'я живота́ моєго́ в ми́рі, покая́нії і ісполне́нії за́повідей Христо́вих провожда́ти бу́ду. Єгда́ же час моєго́ сконча́нія прибли́зиться, ти, о преблаги́й о́тче, с Преблагослове́нною Ді́вою Марі́єю, тогда́ ускори́ на по́мощ, защити́ м'я от зло́бних наві́тов вра́жиїх, і сподо́би м'я наслі́дника би́ти ра́йських селе́ній, да ку́пно с тобо́ю і со всі́ми святи́ми непристу́пнаго Бо́жия вели́чества Престо́лу предста́ну і Живонача́льную, Єдиносу́щную же і Неразді́льную Тро́йцю прославля́ю і воспіва́ю, при́сно і в безконе́чния ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["О вели́кий і пресла́вний святи́телю Христо́в, всея́ вселе́нськия Це́ркве учи́телю богому́дрий, правосла́вія тве́рдий іспові́дниче і побо́рниче, всеблаже́нне о́тче Васи́ліє! При́зри от висо́т небе́сних на нас, смире́нно к тебі́ припа́дающих, і умоли́ Го́спода Вседержи́теля, Єго́же ві́рний на землі́ служи́тель бил єси́, да да́руєть нам ві́ри пра́вия тве́рдоє і неізмі́нноє сохране́ніє, Це́ркві святі́й послуша́ніє, житія́ на́шего ісправле́ніє, і во всіх ну́ждах, ско́рбіх і іскуше́ніїх ско́роє поможе́ніє, терпі́ніє же і укріпле́ніє. Пода́ждь нам твоє́ свято́є благослове́ніє, да о́ним осіня́ємії, сіє́ но́воє лі́то і во вся дні богоуго́дно в ми́рі і покая́нії поживе́м і во Ца́рствії Небе́снім сподо́бимся ку́пно с тобо́ю і со всі́ми святи́ми Живонача́льную Тро́йцю воспіва́ти і сла́вити, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["О вели́кий і пресвяти́й святи́телю, о́тче Васи́ліє! При́зри от висо́т небе́сних на нас, раб Бо́жиїх (імена́), і умоли́ Го́спода, Єго́же ві́рний на землі́ служи́тель бил єси́, да да́руєть нам ві́ри пра́вия тве́рдоє і неізмі́нноє сохране́ніє, Це́ркві Святі́й послуша́ніє, житія́ на́шего ісправле́ніє і во всіх ну́ждах, скорбі́х і іскуше́ніях ско́роє поможе́ніє, терпі́ніє же і укріпле́ніє. Пода́ждь нам твоє́ свято́є благослове́ніє, да о́ним осіня́ємії во вся дні богоуго́дно в ми́рі і покая́нії поживе́м і во Ца́рствії Небе́снім сподо́бимся ку́пно с тобо́ю і со всі́ми святи́ми Живонача́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, воспіва́ти і сла́вити во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю Христо́во Васи́ліє, // благоче́стно Це́рков Христо́ву сохра́ншаго."]}],"notes":[]},{"u":"Молитва апостолу Іоанну, Євангелисту, Богослову","e":"Prayer to the Apostle John, Evangelist and Theologian","secs":[{"h":"Тропар, глас 2","ps":["Апо́столе, Христу́ Бо́гу возлю́бленне, / ускори́ ізба́вити лю́ди безотві́тни, / приє́млеть тя, припа́дающа, / І́же па́дша на пе́рси приє́мий. / Єго́же моли́, Богосло́ве, / і належа́щий о́блак язи́ков разгна́ти, // прося́ нам ми́ра і ве́лія ми́лости."]},{"h":"Інший тропар на преставлення, глас 2","ps":["Апо́столе, Христу́ Бо́гу возлю́бленне, / ускори́ ізба́вити лю́ди безотві́тни, / приє́млеть тя, припа́дающа, / І́же па́дша на пе́рси приє́мий. / Єго́же моли́, Богосло́ве, / і належа́щую мглу язи́ков разгна́ти, // прося́ нам ми́ра і ве́лія ми́лости."]},{"h":"Кондак, глас 2","ps":["Вели́чія твоя́, ді́вственниче, кто пові́сть? / То́чиши бо чудеса́, і ізлива́єши ісціле́нія, / і мо́лишися о душа́х на́ших, // я́ко Богосло́в і друг Христо́в."]},{"h":"Молитва перша","ps":["О вели́кий апо́столе, євангели́сте громогла́сний, Богосло́ве ізя́щнійший, тайнови́дче неізрече́нних открове́ній, ді́вственниче і возлю́бленний напе́рсниче Христо́в Іоа́нне! Прийми́ нас, грі́шних, прибіга́ющих под твоє́ си́льноє заступле́ніє і покрови́тельство. Іспроси́ у Всеще́драго Человіколю́бця Христа́ Бо́га на́шего, І́же пред очеси́ твої́ми кров Свою́ за ни, непотре́бния раби́ Своя́, ізлія́л єсть, да не пом'яне́ть беззако́ній на́ших, но да поми́луєть нас і сотвори́ть с на́ми по ми́лості Своє́й: да да́руєть нам здра́віє душе́вноє і тіле́сноє, вся́коє благоде́нствіє і ізоби́ліє, наставля́я нас обраща́ти о́ная во сла́ву Єго́, Творця́, Спаси́теля і Бо́га на́шего, по кончи́ні же вре́менния жи́зні на́шея от немилосе́рдних істяза́телей на возду́шних мита́рствах да ізба́вить нас, і та́ко да дости́гнем, тобо́ю води́мії і покрива́ємії, Го́рняго о́наго Ієрусали́ма, єго́же сла́ву ти во открове́нії зрел єси́, ни́ні же несконча́ємия ра́дости наслажда́єшися. О вели́кий Іоа́нне! Сохрани́ вся гра́ди і страни́ христия́нськия і всіх, призива́ющих і́м'я твоє́, от гла́да, губи́тельства, тру́са і пото́па, огня́ і меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні; ізба́ви нас от вся́кия біди́ і напа́сти і моли́твами твої́ми отврати́ от нас пра́ведний гнів Бо́жий, і іспроси́ нам Єго́ милосе́рдіє. О вели́кий і непостижи́мий Бо́же! Се на умоле́ніє Тебі́ предлага́єм свята́го Іоа́нна, єго́же Ти сподо́бил єси́ неізрече́нних открове́ній, прийми́ о нас хода́тайство, да́руй нам ісполне́ніє проше́ній на́ших во сла́ву Твою́, па́че же соверши́ нас духо́вним соверше́нством к наслажде́нію, жи́зні несконча́ємия в Небе́сних Твої́х оби́телях! О Небе́сний О́тче, созда́вий вся Влади́ко, Всеси́льний Царю́! Косни́ся благода́тію серде́ць на́ших, да, раста́явше, я́ко воск, пролію́ться пред Тобо́ю і бре́нная твар духо́вна сотвори́ться в честь і сла́ву Твою́, і Си́на Твоєго́, і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий і всехва́льний апо́столе і євангели́сте Іоа́нне Богосло́ве, напе́рсниче Христо́в, те́плий наш засту́пниче і ско́рий в ско́рбіх помо́щниче! Умоли́ Го́спода Бо́га дарова́ти нам оставле́ніє всіх прегріше́ній на́ших, єли́ка согріши́хом от ю́ности на́шея во всем житії́ на́шем ді́лом, сло́вом, помишле́нієм і всі́ми на́шими чу́встви; во ісхо́ді же душ на́ших помози́ нам, грі́шним (імена́), ізба́витися от возду́шних мита́рств і ві́чнаго муче́нія, да твої́м ми́лостивним предста́тельством прославля́єм Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Григорію Богослову","e":"Prayer to St Gregory the Theologian","secs":[{"h":"Тропар, глас 1","ps":["Па́стирськая свирі́ль богосло́вія твоєго́ / ри́торов побіди́ труби́, / я́коже бо глубини́ ду́ха ізиска́вшу, / і добро́ти віща́нія приложи́шася тебі́. / Но моли́ Христа́ Бо́га, о́тче Григо́ріє, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Богосло́вним язи́ком твої́м сплете́нія ри́торськая разруши́вий, сла́вне, / Правосла́вія оде́ждею сви́ше істка́нною Це́рков украси́л єси́, / ю́же і нося́щи, с на́ми зове́ть твої́ми ча́ди: / ра́дуйся, о́тче, // богосло́вія у́ме кра́йнійший."]},{"h":"Молитва","ps":["О, пречестна́я і свяще́нная главо́ і благода́ті Свята́го Ду́ха іспо́лненная, Спа́сово со Отце́м обита́лище, вели́кий архієре́є, те́плий наш засту́пниче, святи́телю Григо́ріє! Предстоя́ у Престо́ла всіх Царя́ і наслажда́яся сві́та Єдиносу́щния Тро́йці і херуви́мськи со а́нгели возглаша́я піснь трисвяту́ю вели́коє і неізслі́дованноє дерзнове́ніє імі́я ко Всемилостивому́ Влади́ці, моли́ся па́стви Христо́ви спасти́ люде́й, благостоя́ніє святи́х церкве́й утверди́, архієре́ї благолі́пієм святи́тельства украси́, мона́шествующих к по́двигам до́браго тече́нія укріпи́, ца́рствующий град і вся гра́ди і страни́ до́брі сохрани́, і ві́ру святу́ю непоро́чну соблюсти́ умоли́, мир весь умири́, от гла́да і па́губи ізба́ви ни, і от нападе́нія іноплеме́нних сохрани́, ста́рия уті́ши, ю́ния наста́ви, безу́мния умудри́, вдови́ці поми́луй, сироти́ заступи́, младе́нці возрасти́, пліне́нния возврати́, немоществующия ісціли́, і везді́ те́плі призива́ющих тя і с ві́рою притека́ющих к тебі́ і усе́рдно припа́дающих і моля́щихся от вся́ких напа́стей і бід хода́тайством твої́м свободи́. Моли́ о нас Всеще́драго і Человіколюби́ваго Христа́ Бо́га на́шего, да і в день стра́шнаго прише́ствія Єго́ шу́їяго стоя́нія ізба́вить нас, і ра́дості святи́х прича́стники сотвори́ть со всі́ми святи́ми во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іоанну Золотоустому","e":"Prayer to St John Chrysostom","secs":[{"h":"Тропар, глас 8","ps":["Уст твої́х я́коже сві́тлость огня́ возсія́вши благода́ть, / вселе́нную просвіти́: / не сребролю́бія ми́рові сокро́вища сниска́, / висоту́ нам смиренному́дрія показа́. / Но твої́ми словеси́ наказу́я, о́тче Іоа́нне Златоу́сте, // моли́ Сло́ва Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["От небе́с прия́л єси́ Боже́ственную благода́ть / і твої́ми устна́ми вся учи́ши / покланя́тися в Тро́йці єди́ному Бо́гу, / Іоа́нне Златоу́сте, / всеблаже́нне преподо́бне, / досто́йно хва́лим тя: // єси́ бо наста́вник, я́ко Боже́ственная явля́я."]},{"h":"Кондак перенесенню мощей, глас 1","ps":["Возвесели́ся та́їнственно честна́я Це́рков / возвраще́нієм честни́х твої́х моще́й, / і, сія́ сокри́вши, я́ко зла́то многоці́нноє, / пою́щим тя неоску́дно подава́єть / моли́твами твої́ми ісціле́ній благода́ть, / Іоа́нне Златоу́сте."]},{"h":"Молитва перша","ps":["О святи́телю вели́кий Іоа́нне Златоу́сте! Мно́гая і разли́чная дарова́нія от Го́спода прия́л єси́ і, я́ко раб благи́й і ві́рний, вся да́нния тебі́ тала́нти до́брі умно́жил єси́: сего́ ра́ди воі́стину вселе́нський учи́тель бил єси́, я́ко всяк во́зраст і вся́ко зва́ніє от тебе́ поуча́ється. Ти єси́ отроко́м — послуша́нія о́браз, ю́ним — цілому́дрія світи́ло, муже́м — трудолю́бія наста́вник, ста́рим — незло́бія учи́тель, і́ноком — воздержа́нія пра́вило, моля́щимся — вождь от Бо́га вдохнове́нний, му́дрости і́щущим — ума́ просвіти́тель, виті́ям доброглаго́ливим — сло́ва жива́го істо́чник неісчерпа́ємий, благотворя́щим — милосе́рдія звізда́, нача́льствующим — правле́нія му́драго о́браз, пра́вди ревни́телем — дерзнове́нія вдохнови́тель, пра́вди ра́ди гони́мим — терпі́нія наста́вник: всім вся бил єси́, да вся́ко ні́кия спасе́ши. Над всі́ми же си́ми стяжа́л єси́ любо́в, я́же єсть сою́з соверше́нства, і то́ю, я́ко си́лою Боже́ственною, вся дарова́нія во єди́нім лице́ твоє́м во єди́но совокупи́л єси́, і ту́южде любо́в, разділе́нная примиря́ющую, в толкова́нії слове́с апо́стольських всім ві́рним пропові́дал єси́. Ми же грі́шнії, по єди́ному ки́йждо своє́ дарова́ніє іму́ще, єдине́нія ду́ха в сою́зі ми́ра не і́мами, бива́єм тщесла́вни, друг дру́га раздража́юще, друг дру́гу зави́дяще: сего́ ра́ди дарова́нія на́ша разділе́нная не в мир і спасе́ніє, но во вражду́ і осужде́ніє нам явля́ються. Ті́мже к тебі́, святи́телю Бо́жий, припа́даєм, раздо́ром обурева́ємі, і в сокруше́нії се́рдця про́сим: моли́твами твої́ми, отжени́ от серде́ць на́ших вся́ку го́рдость і за́висть, нас разділя́ющия, да во мно́зіх у́діх єди́но ті́ло церко́вноє бу́деть, да по словесі́ твоєму́ моли́твенному возлю́бим друг дру́га і єдиноми́слієм іспові́ми Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́телю вели́кий Іоа́нне Златоу́сте! Мно́гая і разли́чная дарова́нія от Го́спода прия́л єси́ і, я́ко раб благи́й і ві́рний, вся да́нния тебі́ тала́нти до́брі умно́жил єси́, сего́ ра́ди воі́стину вселе́нський учи́тель бил єси́, я́ко всяк во́зраст і вся́ко зва́ніє от тебе́ поуча́ється. Ми же, грі́шнії (імена́), по єди́ному ки́йждо своє́ дарова́ніє іму́ще, єдине́нія ду́ха в сою́зі ми́ра не і́мами, но бива́єм тщесла́вії, друг дру́га раздража́юще, друг дру́гу зави́дяще; сего́ ра́ди дарова́нія на́ша разділе́нная не в мир і спасе́ніє, но во вражду́ і осужде́ніє нам явля́ються. Ті́мже к тебі́, святи́телю Бо́жий, припа́даєм, раздо́ром обурева́ємі, і в сокруше́нії се́рдця про́сим: моли́твами твої́ми отжени́ от серде́ць на́ших вся́ку зло́бу, недоброжела́тельство, го́рдость і за́висть, нас разділя́ющия, да во мно́зіх у́діх єди́но ті́ло церко́вноє невозбра́нно пребу́дем, да по словесі́ твоєму́ моли́твенному возлю́бим друг дру́га і єдиноми́слієм іспові́ми Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобній Марії Єгипетській","e":"Prayer to St Mary of Egypt","secs":[{"h":"Тропар, глас 8","ps":["В тебі́, ма́ти, ізві́стно спасе́ся, є́же по о́бразу, / приї́мши бо крест, послі́довала єси́ Христу́ / і, ді́ющи учи́ла єси́ презира́ти у́бо плоть, прехо́дить бо, / приліжа́ти же о душі́ ве́щі безсме́ртній. // Ті́мже і со А́нгели сра́дується, преподо́бная Марі́є, дух твой."]},{"h":"Кондак, глас 4","ps":["Гріха́ мгли ізбіжа́вши, / покая́нія сві́том озари́вши твоє́ се́рдце, сла́вная, / пришла́ єси́ ко Христу́, / Сего́ Всенепоро́чную і святу́ю Ма́тер / Моли́твенницю ми́лостивную принесла́ єси́. / Отону́дуже і прегріше́ній обріла́ єси́ оставле́ніє, // і со А́нгели при́сно сра́дуєшися."]},{"h":"Інший кондак, глас 3","ps":["Блуда́ми пе́рвіє преіспо́лнена вся́чеськими, / Христо́ва неві́ста днесь покая́нієм яви́ся, / а́нгельськоє жи́тельство подража́ющи, / де́мона креста́ ору́жієм погубля́єть. // Сего́ ра́ди Ца́рствія неві́ста яви́лася єси́, Марі́є пресла́вная."]},{"h":"Молитва перша","ps":["О, вели́кая Христо́ва уго́днице, преподо́бная ма́ти Марі́є! На Небесі́ Престо́лу Бо́жию предстоя́щи, на землі́ же ду́хом любве́ с на́ми пребива́ющи, іму́щи дерзнове́ніє ко Го́споду, моли́ спасти́ раби́ Єго́, к тебі́ с любо́вію притека́ющия. Іспроси́ нам у Многоми́лостиваго Влади́ки і Го́спода на́шего ві́ри непоро́чноє соблюде́ніє, градо́в і ве́сей на́ших утвержде́ніє, от гла́да і па́губи ізбавле́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, па́дшим возста́ніє, заблу́ждшим вразумле́ніє, в ді́ліх благи́х преспі́яніє і благослове́ніє, сирота́м і вдови́цям заступле́ніє і отше́дшим от сего́ житія́ ві́чноє упокоє́ніє. Бу́ди крі́пкая хода́тайця, ди́вная ма́ти Марі́є, во є́же всім нам в день Стра́шнаго Суда́ десни́я страни́ о́бщники би́ти і блаже́нний глас Судії́ ми́ра усли́шати: прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кая Христо́ва уго́дниця, преподо́бная ма́ти Марі́є! Усли́ши недосто́йную моли́тву нас, грі́шних (імена́), ізба́ви нас, преподо́бная ма́ти, от страсте́й, вою́ющих на ду́ші на́ша, от вся́кия печа́лі і находя́шія напа́сти, от внеза́пния сме́рти і от вся́каго зла, в час же разлуче́нія душі́ от ті́ла отжени́, свята́я уго́дниця, вся́кую лука́вую мисль і лука́виє бі́си, я́ко да при́йметь ду́ші на́ша с ми́ром в мі́сто сві́тло Христо́с Госпо́дь Бог наш, я́ко от Него́ очище́ніє гріхо́в, і Той єсть спасе́ніє душ на́ших, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Сергію, ігумену Радонезькому","e":"Prayer to St Sergius, Abbot of Radonezh","secs":[{"h":"Тропар на преставлення, глас 4","ps":["І́же доброді́телей подви́жник, / я́ко і́стинний во́їн Христа́ Бо́га, / на стра́сті вельми́ подвиза́лся єси́ в жи́зні вре́менній, / в пі́ніїх, бді́ніїх же і поще́ніїх о́браз бив твої́м ученико́м; / ті́мже і всели́ся в тя Пресвяти́й Дух, / Єго́же ді́йствієм сві́тло укра́шен єси́. / Но я́ко імі́я дерзнове́ніє ко Святі́й Тро́йці, / помина́й ста́до, є́же собра́л єси́, му́дре, / і не забу́ди, я́коже обіща́лся єси́, / посіща́я чад твої́х, // Се́ргіє преподо́бне, о́тче наш."]},{"h":"Інший тропар на преставлення, глас 8","ps":["В чистоті́ житія́ істо́чник слез твої́х, іспові́данія трудо́вния по́ти совокупи́л єси́, і купі́ль духо́вную істочи́л єси́, свяще́нний Се́ргіє, преподо́бне, омива́вши сугу́бстве творя́щим любо́вію па́м'ять твою́ скве́рни обоя́ми душе́вния і тіле́сния. Сих ра́ди, ча́да твоя́ су́ще, вопіє́м ті: моли́, о́тче, Святу́ю Тро́йцю о душа́х на́ших."]},{"h":"Кондак на преставлення, глас 8","ps":["Христо́вою любо́вію уязви́вся, преподо́бне, / і Тому́ невозвра́тним жела́нієм послі́довав, / вся́коє наслажде́ніє плотсько́є возненави́діл єси́, / і я́ко со́лнце Отече́ству твоєму́ возсія́л єси́; / тім і Христо́с да́ром чуде́с обогати́ тя. / Помина́й нас чту́щих пресві́тлую па́м'ять твою́, да зове́м ті: // ра́дуйся, Се́ргіє Богому́дре."]},{"h":"Інший кондак на преставлення, глас 8","ps":["Я́ко безпло́тним равножи́тель всіх преподо́бних превозше́л єси́ по́стничеськими труди́ і бді́нії моли́твенними, му́дре Се́ргіє, тім восприя́л єси́ от Бо́га ісціли́ти неду́ги і прогони́ти бі́си і того́ ра́ди вопіє́м ті: ра́дуйся, о́тче преподо́бне Се́ргіє."]},{"h":"Тропар знайдення мощей, глас 8","ps":["От ю́ности восприя́л єси́ Христа́ в душі́ твоє́й, преподо́бне / і па́че всего́ вожделі́л єси́ мирська́го м'яте́жа уклони́тися, / му́жеськи в пусти́ню всели́лся єси́, / і ча́да послуша́нія в ней, плоди́ смире́нія возрасти́л єси́. / Тім бив Тро́йце вселе́ніє, / чудеси́ твої́ми всіх просвіти́л єси́ приходя́щих к тебі́ ві́рою, / і ісціле́нія всім подая́ оби́льно, // о́тче наш Се́ргіє, моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Інший тропар знайдення мощей, глас 4","ps":["Днесь пресві́тло красу́ється ца́рствующий град Київ, / я́ко світолу́чними заря́ми, мо́лніями чуде́с твої́х осія́єм, / всю вселе́нную созива́єть / похвали́ти тя, Богому́дре Се́ргіє; / пречестна́я же і сла́вная оби́тель твоя́, / ю́же во І́м'я Святи́я Тро́йці мно́гими труди́ твої́ми созда́л єси́, о́тче, / іму́щи в себі́ стада́ учени́к твої́х, / весе́лія і ра́дости ісполня́ється. / Ми же, пра́зднующе пресла́вноє обрі́теніє честни́х моще́й твої́х, в землі́ сокрове́нних, / я́ко цвіт благоуха́нен і кади́ло благово́нно, / любе́зно я лобиза́юще, разли́чная ісціле́нія приє́млем / і твої́ми моли́твами гріхо́в проще́нія сподобля́ємся, / о́тче преподо́бне Се́ргіє, / моли́ Святу́ю Тро́йцю / спасти́ ду́ші на́ша."]},{"h":"Кондак знайдення мощей, глас 8","ps":["Днесь я́ко со́лнце пресві́тло, возсія́вше от землі́, / честни́я мо́щі твоя́ нетлі́нни обріто́шася, / я́ко благоуха́нний цвіт, мно́жеством чуде́с сія́юще, / і всім ві́рним істоча́юще разли́чная ісціле́нія, / і веселя́ще ізбра́нноє твоє́ ста́до, / є́же му́дре собра́в, до́брі па́ствил єси́. / О ни́хже і ни́ні Тро́йце предстої́ши, моля́ся, / і во́їнству побіди́тельная на враги́ дарова́ти // да всі вопіє́м ті: ра́дуйся, Се́ргіє Богому́дре."]},{"h":"Інший кондак знайдення мощей, глас 8","ps":["Взира́юще на предлежа́щий честни́й твой гроб, / в не́мже скри́ся, я́ко многоці́нноє сокро́вище, свято́є трудолю́бноє твоє́ ті́ло чистоти́, / ми, ча́да твоя́ су́ще жа́лостная, / в удивле́нії єди́н со єди́нім віща́юще, вопіє́м: / о́тче наш Се́ргіє, моли́ Святу́ю Тро́йцю / і нам спасти́ся, твої́м ча́дом."]},{"h":"Молитва перша","ps":["О свяще́нная главо́, преподо́бне і Богоно́сне о́тче наш Се́ргіє, моли́твою твоє́ю, і ві́рою і любо́вію, я́же к Бо́гу, і чистото́ю се́рдця, єще́ на землі́ во оби́тель Пресвяти́я Тро́йці ду́шу твою́ устро́ївий, і а́нгельськаго обще́нія і Пресвяти́я Богоро́диці посіще́нія сподо́бивийся, і дар чудоді́йственния благода́ті приє́мий, по отше́ствії же твоє́м от земни́х найпа́че к Бо́гу прибли́живийся, і небе́сния си́ли приобщи́вийся, но і от нас ду́хом любве́ своєя́ не отступи́вий, і честни́я твоя́ мо́щі, я́ко сосу́д благода́ті по́лний і преізлива́ющийся, нам оста́вивий! Ве́лія імі́я дерзнове́ніє ко Всеми́лостивому Влади́ці, моли́ спасти́ раби́ Єго́, су́щей в тебі́ благода́ті Єго́ ве́рующия і к тебі́ с любо́вію притека́ющия. Іспроси́ нам от великодарови́таго Бо́га на́шего вся́кий дар, всім і коєму́ждо благопотре́бен, ві́ри непоро́чни соблюде́ніє, градо́в на́ших утвержде́ніє, ми́ра умире́ніє, от гла́да і па́губи ізбавле́ніє, от наше́ствія іноплеме́нних сохране́ніє, скорб'я́щим утіше́ніє, недугующим ісціле́ніє, па́дшим возставле́ніє, заблу́дшим на путь і́стини і спасе́нія возвраще́ніє, подвиза́ющимся укріпле́ніє, благоде́лающим в діла́х благи́х преспі́яніє і благослове́ніє, младе́нцем воспита́ніє, ю́ним наставле́ніє, неві́дущим вразумле́ніє, сирота́м і вдови́цям заступле́ніє, отходя́щим от сего́ вре́менного житія́ к ві́чному благо́є уготовле́ніє і напу́тствіє, отше́дшим блаже́нноє упокоє́ніє, і вся ни споспішеству́ющими твої́ми моли́твами сподо́би в день Стра́шнаго суда́ шу́їя ча́сти ізба́витися, десни́я же страни́ о́бщники би́ти і блаже́нний о́ний глас Влади́ки Христа́ усли́шати: прийді́те, благослове́ннії Отця́ Моєго́, наслі́дуйте угото́ванноє вам Ца́рствіє от сложе́нія ми́ра. Амі́нь."]},{"h":"Молитва друга","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Се́ргіє вели́кий! Не забу́ди убо́гих свої́х до конця́, но помина́й нас во святи́х свої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до своє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад свої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти своя́ духо́вния, я́ко імі́я дерзнове́ніє к Небе́сному Царю́, не премолчи́ за ни ко Го́споду і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних у престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо і ті́лом преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий; а́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ со а́нгельськими во́їнстви, со безпло́тними ли́ки, с Небе́сними си́лами, у престо́ла Вседержи́теля предстоя́щи, досто́йно весели́ться. Ві́дуще бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся, є́же моли́тися о нас Всеми́лостивому Бо́гу о по́льзі душ на́ших, і іспроси́ти вре́м'я на покая́ніє, і о невозбра́нном преі́тії от землі́ на не́бо, мита́рств же го́рких, бісо́в, возду́шних князе́й і ві́чния му́ки ізба́витися, і Небе́сному Ца́рствію наслі́дником би́ти со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Серафиму Саровському, чудотворцю","e":"Prayer to St Seraphim of Sarov, the Wonderworker","secs":[{"h":"Тропар на преставлення, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, блаже́нне, / і Тому́ Єди́ному рабо́тати пла́менні вожделі́в, / непреста́нною моли́твою і трудо́м в пусти́ні подвиза́лся єси́, / умиле́нним же се́рдцем любо́в Христо́ву стя́жав, / ізбра́нник возлю́блен Бо́жия Ма́тере яви́лся єси́. / Сего́ ра́ди вопіє́м ті: // спаса́й нас моли́твами твої́ми, Серафи́ме, преподо́бне о́тче наш."]},{"h":"Інший тропар на прославлення, глас 4","ps":["От ю́ности Христа́ возлюби́л єси́, преподо́бне, / і Тому́ Єди́ному порабо́тати пла́менні вожделі́л єси́, / в пу́стиннім житії́ твоє́м непреста́нною моли́твою і трудо́м подвиза́лся єси́, / умиле́нним се́рдцем любо́в Христо́ву стяжа́в, / Небе́сним Серафи́мом в пісносло́вії спобо́рниче, / в любві́ притека́ющим к тебі́ Христу́ подража́телю, / ті́мже ізбра́нник возлю́блен Бо́жия Ма́тере яви́лся єси́, / сего́ ра́ди вопіє́м ті: / спаса́й нас моли́твами твої́ми, ра́досте на́ша, / те́плий пред Бо́гом засту́пниче, // Серафи́ме блаже́нне."]},{"h":"Кондак, глас 2","ps":["Ми́ра красоту́ і я́же в нем тлі́нная оста́вив, преподо́бне, / в Саро́вськую оби́тель всели́лся єси́, / і та́мо а́нгельськи пожи́в, / мно́гим путь бил єси́ ко спасе́нію, / сего́ ра́ди і Христо́с тебі́, о́тче Серафи́ме, просла́ви / і да́ром ісціле́ній і чуде́с обогати́. / Ті́мже вопіє́м ті: // ра́дуйся, Серафи́ме, преподо́бне о́тче наш."]},{"h":"Молитва перша","ps":["О пречу́дний о́тче Серафи́ме, вели́кий Саро́вський чудотво́рче, всім прибега́ющим к тебі́ скоропослу́шний помо́щниче! Во дні земна́го житія́ твоєго́ нікто́же от тебе́ тощ і неуті́шен оти́де, но всім в сла́дость бисть виді́ніє ли́ка твоєго́ і благоуві́тливий глас слове́с твої́х. К сим же і дар ісціле́ній, дар прозрі́нія, дар немощни́х душ врачева́нія оби́лен в тебі́ яви́ся. Єгда́ же призва́ тя Бог от земни́х трудо́в к небе́сному упокоє́нію, ніколи́же любо́в твоя́ преста́ от нас, і невозмо́жно єсть ісчи́слити чудеса́ твоя́, умно́жившаяся, я́ко зві́зди небе́сния: се бо по всім конце́м землі́ на́шея лю́дем Бо́жиїм явля́єшися і да́руєши їм ісціле́нія. Ті́мже і ми вопіє́м ті: о прети́хий і кро́ткий уго́дниче Бо́жий, дерзнове́нний к Нему́ моли́твенниче, ніколи́же призива́ющия тя отріва́яй, вознеси́ о нас благомо́щную твою́ моли́тву ко Го́споду Сил, да да́руєть нам вся благопотре́бная в жи́зні сей і вся к душе́вному спасе́нію поле́зная, да огради́ть нас от паде́ній гріхо́вних і і́стинному покая́нію научи́ть нас, во є́же безпреткнове́нно вни́ти нам во ві́чноє Небе́сноє Ца́рство, іді́же ти ни́ні в незаходи́мій сія́єши сла́ві, і та́мо воспіва́ти со всі́ми святи́ми Живонача́льную Тро́йцю во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий уго́дниче Бо́жий, преподо́бне і Богоно́сне о́тче наш Серафи́ме! При́зри от Го́рнія сла́ви на нас, смире́нних і немощни́х, обремене́нних гріхми́ мно́гими, твоєя́ по́мощі і утіше́нія прося́щих. Прини́кни к нам благосе́рдієм твої́м і помози́ нам за́повіді Госпо́дні непоро́чно сохраня́ти, ві́ру правосла́вную крі́пко содержа́ти, покая́ніє во грісі́х на́ших усе́рдно Бо́гу приноси́ти, во благоче́стії христия́нстім благода́тно преуспіва́ти і досто́йни би́ти твоєго́ о нас моли́твеннаго к Бо́гу предста́тельства. Єй, свя́тче Бо́жий, усли́ши нас, моля́щихся тебі́ с ві́рою і любо́вію, і не пре́зри нас, тре́бующих твоєго́ заступле́нія: ни́ні і в час кончи́ни на́шея помози́ нам і заступи́ нас моли́твами твої́ми от зло́бних наві́тов дия́вольських, да не облада́єть на́ми тіх си́ла, но да сподо́бимся по́мощію твоє́ю наслі́довати блаже́нство оби́телі ра́йськия. На тя бо упова́ніє на́ше ни́ні возлага́єм, о́тче благосе́рдий: бу́ди нам воі́стину ко спасе́нію путево́ждь і приведи́ нас к невече́рнему сві́ту Жи́зні Ві́чния богоприя́тним предста́тельством твої́м у Престо́ла Пресвяти́я Тро́йці, да сла́вим і поє́м со всі́ми святи́ми достопокланя́ємоє і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Іоанну Кронштадтському, чудотворцю","e":"Prayer to St John of Kronstadt, the Wonderworker","secs":[{"h":"Тропар, глас 1","ps":["Правосла́вния ві́ри побо́рниче. / Землі́ Українськия печа́льниче, / па́стирем пра́вило і о́бразе ві́рним, / покая́нія і жи́зні во Христі́ пропові́дниче. / Боже́ственних та́їн благогові́йний служи́телю / і дерзнове́нний о лю́діх моли́твенниче, / о́тче пра́ведний Іоа́нне, / ціли́телю і преди́вний чудотво́рче, / гра́ду Кроншта́дту похвало́ / і це́ркві на́шея украше́ніє, / моли́ всеблага́го Бо́га / умири́ти мир і спасти́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Українськия землі́ па́стир до́брий показа́лся єси́, / в служе́нії пресви́терстім жизнь во Христі́ стяжа́в, богому́дре о́тче Іоа́нне. / Благода́ть ізоби́льную от Влади́ки Христа́ прия́л єси́: / неду́ги отгоня́ти, / малоду́шния утіша́ти, / в Та́йні Пречи́стаго Ті́ла і Кро́ве ві́рния со Христо́м соєдиня́ти. / Сего́ ра́ди восхваля́єм тя, // я́ко моли́твенника о душа́х на́ших."]},{"h":"Інший тропар, глас 4","ps":["Со апо́столи ізи́де віща́ніє твоє́ в конці́ вселе́нния, / с іспові́дники стра́данія за Христа́ претерпі́л єси́, / святи́телем уподо́бился єси́ Сло́ва пропові́данієм, / с преподо́бними во благода́ті Бо́жієй просія́л єси́. / Сего́ ра́ди вознесе́ Госпо́дь бе́здну смире́нія твоєго́ преви́ше небе́с, / і дарова́ нам і́м'я твоє́ во істо́чник преди́вних чуде́с. / Ті́мже во Христі́ во ві́ки живи́й, чудотво́рче, / любо́вію ми́луй су́щия в біда́х, / сли́ши ча́да твоя́, ві́рою тя призива́ющия, / Іоа́нне пра́ведне, // возлю́бленний па́стирю наш."]},{"h":"Кондак, глас 3","ps":["Днесь па́стир Кроншта́дтський / предстої́ть Престо́лу Бо́жию / і усе́рдно мо́лить о ві́рних / Христа́ Пастиренача́льника, / обітова́ніє да́вшаго: / сози́жду Це́рков Мою́ / і врата́ а́дова / не одолі́ють єй."]},{"h":"Інший кондак, глас 6","ps":["Пропові́дником і́стини, богоно́сним отце́м подра́жая, / всего́ себе́ на служе́ніє Бо́гу і бли́жнім вдал єси́, / і сан свяще́нства нося́, поко́я не ві́дал єси́, / слу́жби Бо́жія в хра́мі при́сно соверша́я, / і в домі́х ві́рних моле́бния пі́нія воспіва́я, / нужда́ющимся ще́дро благотворя́, / та́ко найменова́ніє благотво́рця і безсре́бренника стяжа́л єси́, Іоа́нне. / Ті́мже і по успе́нії твоє́м українськия лю́діє прославля́ють і́м'я твоє́, / і ві́чную па́м'ять тебі́ возглаша́юще, // пою́ть Бо́гу: аллилу́я."]},{"h":"Молитва перша","ps":["О вели́кий уго́дниче Христо́в, святи́й пра́ведний о́тче Іоа́нне Кроншта́дтський, па́стирю ди́вний, ско́рий помо́щниче і ми́лостивий предста́телю! Вознося́ славосло́віє Трієди́ному Бо́гу, ти моли́твенно взива́л: І́м'я Тебі́ — Любо́в: не отве́ргни м'я, заблужда́ющагося. І́м'я Тебі́ — Си́ла: укріпи́ м'я, ізнемога́ющего і па́дающаго. І́м'я Тебі́ — Світ: просвяти́ ду́шу мою́, омраче́нную жите́йськими страстя́ми. І́м'я Тебі́ — Мир: умири́ м'яту́щуюся ду́шу мою́. І́м'я Тебі́ — Ми́лость: не переставай миловать м'я. Ни́ні благода́рная твоєму́ предста́тельству всеукраїнськая па́ства мо́литься тебі́: Христоімени́тий і пра́ведний уго́дниче Бо́жий! Любо́вію твоє́ю озари́ нас, грі́шних і немощни́х, сподо́би нас принести́ досто́йниє плоди́ покая́нія і не осужде́нно причаща́тися Христо́вих Та́їн. Си́лою твоє́ю ві́ру в нас укріпи́, в моли́тві поддержи́, неду́ги і болі́зні ісціли́, от напа́стей, враго́в, ви́димих і неви́димих, ізба́ви. Сві́том ли́ка твоєго́ служи́телей і предстоя́телей Алтаря́ Христо́ва на святи́є по́двиги па́стирського ді́ланія подви́гни, младе́нцем воспита́ніє да́руй, ю́ноє наста́ви, ста́рость поддержи́, святи́ні хра́мов і святи́є оби́телі озари́! Умири́, чудотво́рче і прови́дче преізря́днійший, наро́ди страни́ на́шея, благода́тію і да́ром Свята́го Ду́ха ізба́ви от междуусо́бния бра́ні, расточе́нная собери́, прельще́нния обрати́ і совокупи́ Святі́й Собо́рній і Апо́стольськой Це́ркві. Ми́лостію твоє́ю супру́жества в ми́рі і єдиноми́слії соблюди́, мона́шествующим в діла́х благи́х преуспія́ніє і благослове́ніє да́руй, малоду́шния уті́ши, стра́ждущих от духо́в нечи́стих свободи́, в ну́ждах і обстоя́ніїх су́щих поми́луй і нас на путь спасе́нія наста́ви. Во Христі́ живи́й, о́тче наш Іоа́нне, приведи́ нас к Невече́рнему Сві́ту жи́зні ві́чния, да сподо́бимся с тобо́ю ві́чнаго блаже́нства, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий чудотво́рче і преди́вний уго́дниче Бо́жий, богоно́сне о́тче Іоа́нне! При́зри на нас і внемли́ благосе́рдно моле́нію на́шему, я́ко вели́ких дарова́ній сподо́би тя Госпо́дь, да хода́таєм і при́сним моли́твенником за нас бу́деши. Се бо страстьми́ гріхо́вними обурева́ємі і зло́бою сніда́єми, за́повіді Бо́жия пренебрего́хом, покая́нія серде́чнаго і слез воздиха́нія не принесо́хом, сего́ ра́ди мно́гим ско́рбем і печа́лем досто́йні яви́хомся. Ти же, о́тче пра́ведний, ве́ліє дерзнове́ніє ко Го́споду і сострада́ніє к бли́жнім свої́м імі́я, умоли́ Всеще́драго Влади́ку ми́ра, да проба́вить ми́лость Свою́ на нас і потерпи́ть непра́вдам на́шим, не погуби́ть нас гріх ра́ди на́ших, но вре́м'я на покая́ніє ми́лостивно нам да́руєть. О свя́тче Бо́жий, помози́ нам ві́ру правосла́вную непоро́чно соблюсти́ і за́повіді Бо́жії благоче́стно сохрани́ти, да не облада́єть на́ми вся́коє беззако́ніє, ніже́ посра́миться Пра́вда Бо́жія в непра́вдах на́ших, но да сподо́бимся дости́гнути кончи́ни христия́нськия, безболе́зненния, непости́дния, ми́рния і Тайн Бо́жиїх прича́стния. Єще́ мо́лим тя, о́тче пра́ведне, о є́же Це́ркві на́шей Святі́й до сконча́нія ві́ка утвержде́нней би́ти, Оте́честву же на́шему мир і пребива́ніє іспроси́ і от всіх зол сохрани́, да та́ко наро́ди на́ші, Бо́гом храни́мі, в єдиноми́слії ві́ри і во вся́ком благоче́стії і чистоті́, в лі́поті духо́внаго бра́тства, трезве́нії і согла́сії свиді́тельствують: я́ко с на́ми Бог! В Нем же живе́м і дви́жемся, і єсьми́, і прибу́дем во ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["О́тче Іоа́нне досточу́дне! Ти доброді́тельми мно́гими к Бо́гу прибли́зился єси́ і дарова́ній духо́вних от Него́ сподо́бился єси́: неду́ги врачева́ти, стра́сті прогоня́ти і ско́рби утоля́ти. Ті́мже смире́нно мо́лим тя: пода́ждь неду́гом на́шим ісціле́ніє і страсте́м врачева́ніє, находя́щия же на нас ско́рби утоли́ і ра́дость духо́вную в сердця́ на́ша всели́. І помози́ нам подража́тельми би́ти свята́го твоєго́ житія́ і всіх благи́х твої́х дія́ній, я́ко да сподо́бимся с тобо́ю наслі́дія Ца́рствія Небе́снаго. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Феофану, Затворнику, Вишенському","e":"Prayer to St Theophan the Recluse of Vyshen","secs":[{"h":"Тропар, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / Ви́шинський подви́жниче святи́телю Феофа́не Богому́дре, / писа́ньми твої́ми сло́во Бо́жиє із'ясни́л єси́ / і всім ві́рним путь ко спасе́нію указа́л єси́, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Богоявле́нію тезоимени́тий, / святи́телю Феофа́не, / уче́ньми твої́ми мно́гия лю́ди просвіти́л єси́, / со а́нгели ни́ні предстоя́ Престо́лу Святи́я Тро́йці, // моли́ непреста́нно о всіх нас."]},{"h":"Молитва","ps":["О святи́телю о́тче Феофа́не, архієреє́ю пресла́вний і преди́вний затво́рниче, Бо́жий ізбра́ниче і Та́їн Христо́вих служи́телю, богому́дрий учи́телю і апо́стольських слове́с ізря́дний із'ясни́телю, оте́чеських добротолю́бних сказа́ній списа́телю, христия́нськаго благоче́стія ізя́щний пропові́дниче і жи́зні духо́вния іску́сний наста́вниче, по́двигов мона́шеських усе́рдний ревни́телю і всім лю́дем благода́ті хода́таю! Ни́ні к тебі́, на Небесі́х Бо́гу предстоя́щему і о нас моля́щемуся, припа́даєм і си́це взива́єм: іспроси́ у всеще́драго Бо́га Це́ркві Українській і страні́ на́шей мир і благостоя́ніє, святи́телем Христо́вим – і́стини Боже́ственния досто́йноє охране́ніє, па́стви до́броє окормле́ніє, лжеучи́телей і єретико́в ізря́дноє посрамле́ніє; подвиза́ющимся – смире́ніє, страх Бо́жий і чистоту́ душе́вную і тіле́сную; учи́телем – богові́дініє і му́дрость, уча́щимся – ре́вность і по́мощ Бо́жию; і всім правосла́вним – утвержде́ніє на путі́ ко спасе́нію, да вку́пі с тобо́ю просла́вим Бо́жию Си́лу і Прему́дрость, Го́спода на́шего Ісу́са Христа́, со Безнача́льним Єго́ Отце́м, с Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомученику Пантелеймону, цілителю","e":"Prayer to the Great Martyr Panteleimon the Healer","secs":[{"h":"Тропар, глас 3","ps":["Страстоте́рпче святи́й і ціле́бниче Пантелеї́моне, / моли́ ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє // пода́сть душа́м на́шим."]},{"h":"Кондак, глас 5","ps":["Подража́тель сий Ми́лостиваго, / і ісціле́ній благода́ть от Него́ приє́м, / страстоте́рпче і му́чениче Христа́ Бо́га, / моли́твами твої́ми душе́вния на́ша неду́ги ісціли́, / отгоня́ при́сно борця́ собла́зни от вопію́щих ві́рно: // спаси́ ни, Го́споди."]},{"h":"Молитва","ps":["О вели́кий Христо́в уго́дниче і пресла́вний ціле́бниче, великому́чениче Пантелеї́моне! Душе́ю на Небесі́ Престо́лу Бо́жию предстоя́й і Трийпоста́сния Єго́ сла́ви наслажда́яйся, ті́лом же і ли́ком святи́м на землі́ в Боже́ственних хра́мах почива́яй і да́нною ті сви́ше благода́тію разли́чниє чудеса́ істоча́яй. При́зри ми́лостивим твої́м о́ком на предстоя́щия лю́ди і честні́й іко́ні уми́льно моля́щієся і прося́щия от тя ціле́бния по́мощі і заступле́нія. Простри́ ко Го́споду Бо́гу на́шему те́плиє моли́тви свої́ і іспроси́ душа́м на́шим оставле́ніє согріше́ній на́ших. С ві́рою призива́єм і́м'я твоє́, святи́й пра́ведний Пантелеї́моне. Я́ко ти прия́л єси́ благода́ть от Го́спода Бо́га – неду́ги отгоня́ти і стра́сті ісціля́ти. Тя у́бо про́сим: не пре́зри нас, недосто́йних, моля́щихся тебі́ і твоєя́ по́мощі тре́бующих. Бу́ди нам в печа́ліх уті́шитель, в неду́зіх лю́тих стра́ждущих врач. Напа́ствуємим – ско́рий покрови́тель. Оча́м неду́гующим – прозрі́нія да́тель. В ско́рб'ях пребива́ющим – гото́війший предста́тель і ісціли́тель. Ісхода́тайствуй всім вся, я́же ко спасе́нію поле́зная. Я́ко да твої́ми ко Го́споду Бо́гу моли́твами получи́вше благода́ть і ми́лость, просла́вим всіх благи́х Істо́чника і Даропода́теля, Бо́га Єди́ного, в Тро́йці Свято́й сла́вимого, Отця́ і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О пресла́вний му́чениче і до́блій во́їне Небе́снаго Царя́, Пантелеї́моне всеблаже́нне, ми́лостиваго Бо́га преізря́дний подража́телю, і́же Христа́ на землі́ дерзнове́нно іспові́дав, і многообра́зния за Него́ му́ки претерпі́в, неув'яда́ємий прия́л єси́ віне́ць на Небесі́, іді́же ві́чнаго наслажда́єшися блаже́нства, і со дерзнове́нієм Престо́лу трисо́лнечнаго Божества́ предстої́ши! К твоєму́ христоподража́тельному сострада́нію по Бо́зі прибіга́єм всі ми грі́шнії, і всеусе́рдно мо́лим тя, те́плаго засту́пника і предста́теля на́шего: не преста́й призира́ти на нас, су́щих в ну́ждах і ско́рбних обстоя́ніях, і твоє́ю моли́твенною по́мощію і цільбопода́тельною си́лою ізбавля́й нас при́сно от лю́тих зол, всегуби́тельства і вся́кия іни́є біди́ і болі́зні. Ти бо прия́л єси́, свя́те, неоску́дную благода́ть ісціле́ній от Спа́са на́шего Ісу́са Христа́ за тве́рдую твою́ к Нему́ ві́ру, при чи́стом і непоро́чном житії́, запечатлі́нную му́ченичеством і многопобі́дною твоє́ю кончи́ною, в не́йже по да́нній ті благода́ті і найменова́н от Христа́ Пантелеї́моном, ми́лости тезоімени́тим, ми́лующим всіх притека́ющих к тебі́ в ско́рбіх і болі́зніх. Сего́ ра́ди ві́дуще тя ми́лостиваго во всем помо́щника і ціли́теля, с ві́рою взива́єм к тебі́: усли́ши нас і богоприя́тним хода́тайством твої́м подава́й нам вся благопотре́бная в житії́ сем і ну́жная к ві́чному спасе́нію. Му́ченичеським же дерзнове́нієм твої́м умоли́ ми́лостиваго Бо́га, да поми́луєть нас грі́шних і недосто́йних по вели́цій ми́лості Своє́й, да ізба́вить от тру́са, пото́па, огня́, меча́ і вся́каго пра́веднаго гні́ва і преще́нія, благовре́менні подвиза́я нас к очисти́тельному і умилостиви́тельному во грісі́х на́ших покая́нію, ра́ди мно́жества щедро́т Свої́х, да пода́сть всім нам безбі́дноє, ти́хоє і богоуго́дноє житіє́, правосла́вним же на вся враги́ побі́ду і одолі́ніє, і всіх нас от враг ви́димих і неви́димих да сохрани́ть благода́тію Своє́ю і непобіди́мим ополче́нієм А́нгел Свої́х, і́миже огражда́єми і наставля́ємі да поживе́м во ві́ці сем в покая́нії, чистоті́ і в творе́нії богоуго́дних діл; да сподо́бимся твої́м те́плим предста́тельством христия́нськую кончи́ну улучи́ти безболі́зненну, ми́рну, непости́дну, ізба́витися от ко́зней возду́шних князе́й тьми і от ві́чния му́ки, і би́ти наслі́дниками безконе́чнаго, всеблаже́ннаго Ца́рствія. Єй, уго́дниче Бо́жий! Не преста́й моли́тися за ни грі́шния, да твої́м хода́тайством вре́менних і ві́чних бід ізба́влени, велича́єм тебі́, засту́пника на́шего і моли́твенника, і ві́чно прославля́єм о́бщаго Влади́ку і Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя преосвященного Єремії (Відлюдника)","ps":["Святи́й великому́чениче і ціле́бниче Пантелеї́моне! Моли́ Бо́га о нас і не допусти́ до́леє остава́ться в нас тім боле́зням, ко́їми боли́м душе́ю і ті́лом! Ісціли́ те я́зви і стру́пи ко́ї причине́ни нам страстя́ми на́шими. Боли́м ми лі́ностію і расслабле́нієм — ісціли́ ни. Боли́м влече́нієм і пристра́стієм к земни́м предме́там — ісціли́ ни. Боли́м, о святи́й Пантелеї́моне! Боли́м заби́вчивостію: о ді́лі спасе́нія, о на́ших греха́х і не́мощах, о на́ших об'я́занностях — ісціли́ ни. Боли́м злопомні́нієм, гневли́востію, ненави́стничеством — ісціли́, о ціле́бниче Свя́то-Афо́нський і всеми́рний. Боли́м за́вистью, го́рдостью, надме́нностью, превозноше́нієм, при всей ску́дости і непотре́бстві — ісціли́ ни. Боли́м мно́гими і ра́зними припа́дками плотоуго́дія: чревоїзли́шеством, невозде́ржностію, многояде́нієм, сластолю́бієм — ісціли́ ни. Боли́м сонли́востью, многосло́вієм, праздносло́вієм, осу́дливостью — ісціли́ ни, о святи́й Пантелеї́моне! Боля́ть на́ші о́чі гріхо́вними воззре́ніями, боля́ть на́ші у́ші слу́шанієм пустосло́вія, злорі́чія, наві́тов — ісціли́ ни. Боля́ть ру́ки нерасположе́нієм к моли́твенному воздія́нію і к подая́нію ми́лостині — ісціли́ ни. Боля́ть на́ші но́ги нежела́нієм поспі́шно ідти́ в храм Госпо́день і стремле́нієм ко хожде́ніям по сто́гнам і к посеще́ніям домо́в мирськи́х — ісціли́ ни. Боли́ть, зіло́ боли́ть язи́к наш, уста́ на́ші: пустосло́вієм, праздносло́вієм, злоре́чієм, отвраща́ясь от молитвосло́вій і славосло́вій, іли́ проізнося́ їх небре́жно, рассе́янно, без внима́нія, без поня́тія — ісціли́ ни, о ми́лостиве! От глави́ до ног боли́м ми: боли́ть в нас ра́зум непоня́тливостію, неразу́мностію і безу́мієм; боли́ть в нас во́ля, отвраща́ясь от святи́х заня́тій і стрем'я́сь к діла́м вре́дним і богопроти́вним; боли́ть в нас па́м'ять, забива́я на́ші прегріше́нія і содержа́ в себі́ неутра́тно согріше́нія і оскорбле́нія бли́жніх на́ших; боли́ть в нас воображе́ніє, не умі́я і не жела́я жи́во предста́вить нам нашу́ смерть, ві́чную му́ку грі́шних, блага́ Ца́рствія Небе́сного, Бо́жий гнів, кре́стниє страда́нія Христо́ви, Єго́ расп'я́тіє — ісціли́ ни, о святи́й Пантелеї́моне! Все в нас боли́ть. Немощству́єть і душа́ на́ша вся со всі́ми єє си́лами і спосо́бностями. Немощству́єть і ті́ло на́ше все со всі́ми єго́ чле́нами. Ісціли́ ни, о святи́й Пантелеї́моне, Ціле́бниче безме́здний і любвеоби́льний Врачева́тель, слуга́ Пресвяти́я Богоро́диці, і не оста́в на́ше окая́нство в толи́ціх неду́гах і в толи́цій не́мощі: да ісцеля́сь твоє́ю благода́тію, просла́влю Пресвяту́ю Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха і Пресвяту́ю Богоро́дицю, тебі́ на служе́ніє боля́щим посила́ющую, і возблагодарю́ твою́, о святи́й Пантелеї́моне, цільбоно́сную святи́ню во ві́ки. Амі́нь."]},{"h":"Молитва четверта","ps":["О вели́кий уго́дниче Христо́в, страстоте́рпче і врачу́ многоми́лостивий, Пантелеї́моне! Умилосе́рдися надо́ мно́ю, грі́шним рабо́м, усли́ши стена́ніє і вопль мой, уми́лостиви небе́снаго, верхо́внаго Врача́ душ і тіле́с на́ших, Христа́ Бо́га на́шего, да да́руєть мі ісціле́ніє от гнету́щаго м'я неду́га. Прийми́ недосто́йноє моле́ніє грі́шнійшаго па́че всіх челові́к. Посіти́ м'я благода́тним посіще́нієм. Не возгнуша́йся гріхо́вних язв мої́х, пома́жи єле́єм ми́лости твоєя́ і ісціли́ м'я: да, здрав сий душе́ю і ті́лом, оста́ток дній мої́х, благода́тію Бо́жиєю, возмогу́ провести́ в покая́нії і угожде́нії Бо́гу і сподо́блюся восприя́ти благи́й коне́ць живота́ моєго́. Єй, уго́дниче Бо́жий! Умоли́ Христа́ Бо́га, да предста́тельством твої́м да́руєть мі здра́віє ті́лу і спасе́ніє душі́ моє́й. Амі́нь."]},{"h":"Молитва п’ята (подячна, після зцілення від хвороби)","ps":["Святи́й великому́чениче, ціли́телю і чудотво́рче Пантелеї́моне, всеїзря́дний уго́дниче Бо́жий і моли́твенниче при́сний христия́н правосла́вних! Досто́йно нарече́н єси́ Пантелеї́моном, є́же єсть всеми́лостивий, я́ко, прия́в от Бо́га благода́ть моли́тися за ни і болі́зні ціли́ти, ти бога́тно подає́ши всім, к тебі́ притека́ющим, разли́чная ісціле́нія і вся к жи́зні вре́менній і ко спасе́нію потре́бная: сего́ ра́ди і ми недосто́йнії, сподо́бившеся твоєя́ ми́лости, па́ки пред свято́ю твоє́ю іко́ною прибіга́єм к тебі́, і прославля́юще тя, я́ко і́скренняго уго́дника Бо́жия, на́шего же ві́рнаго моли́твенника і ісціли́теля, усе́рдні благодари́м тя і пода́теля всіх благ Го́спода Бо́га на́шего о вели́ких благодія́ніїх, от Него́ тобо́ю нам би́вших. Прийми́ у́бо ми́лостивно ма́лоє сіє́ моли́твенноє благодаре́ніє на́ше, зане́ не і́мами і́но что по достоя́нію возда́ти тебі́, і про́чеє вре́м'я живота́ на́шего не лиши́ нас, немощни́х і грі́шних, твоєя́ по́мощі і моли́твеннаго хода́тайства у Го́спода Бо́га на́шего, Єму́же подоба́єть вся́кая сла́ва, благодаре́ніє і поклоне́ніє, Отцю́ і Си́ну і Свято́му ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва шоста","ps":["Святи́й великому́чениче і ціли́телю Пантелеї́моне, Бо́га ми́лостиваго подража́телю! При́зри благосе́рдієм і усли́ши нас, грі́шних, пред свято́ю твоє́й іко́ною усе́рдні моля́щихся. Іспроси́ нам у Го́спода Бо́га, Єму́ же со А́нгели предстої́ши на Небесі́, оставле́ніє гріхо́в і прегріше́ній на́ших. Ісціли́ болі́зні душе́вния же і тіле́сния рабо́в Бо́жиїх, ни́ні помина́ємих, зді предстоя́щих і всіх христия́н правосла́вних, к твоєму́ заступле́нію притека́ющих. Се бо ми, по гріхо́м на́шим лю́ті одержи́ми єсьми́ мно́гими неду́ги і не і́мами по́мощі і утіше́нія, к тебі́ же прибіга́єм, я́ко даде́ся ті благода́ть моли́тися за ни і ціли́ти всяк неду́г і вся́ку болі́знь. Да́руй у́бо всім нам святи́ми моли́твами твої́ми здра́віє і благомо́щіє душі́ і ті́ла, преспі́яніє ві́ри і благоче́стія і вся к житію́ вре́менному і ко спасе́нію потре́бная. Я́ко да, сподо́бившися тобо́ю вели́ких і бога́тих ми́лостей, просла́вим тя і пода́теля всіх благ, ди́внаго во святи́х, Бо́га на́шего, Отця́, і Си́на, і Свята́го Ду́ха. Амі́нь."]},{"h":"Великомученику Пантелеймону, святим Косьмі й Даміану, мученикам Киру й Іоанну, священномученику Єрмолаю, мученику Діомиду, мученикам Фотію й Аникиті","ps":["О, великіє Христо́ви уго́дниці і чудотво́рці Пантелеймоне, Космо́ і Дамія́не, Ки́ре і Іоа́нне, Ермола́є, Діоми́де, Фо́тіє і Аники́то! Усли́шіте нас, вам моля́щихся (імена́). Ви ві́сте на́ші ско́рби і неду́ги, сли́шіте воздиха́нія мно́жества к вам притека́ющих. Сего́ ра́ди к вам я́ко ско́рим помощникам і те́плим молитвенникам на́шим зове́м: не оставля́йте нас ва́шим у Бо́га хода́тайством. Ми при́сно заблужда́єм от путі́ спасе́нія, руководі́те нас, милостивиє наста́вници. Ми не́мощни єсьми́ во ві́рі, утверді́те нас, правові́рія учи́тели. Ми зіло́ убо́зі сотвори́хомся до́брих діл, обогаті́те нас, благосердія сокро́вища. Ми при́сно наві́туємі єсьми́ от враг ви́димих і неви́димих і озлобля́ємі, помогите нам, безпомо́щних засту́пниці. Гнів пра́ведний, дви́жимий на ни за беззако́нія на́ша, отвраті́те от нас ва́шим хода́тайством у престо́ла Судії́ Бо́га, Єму́же ви предстоїте́ на небесі́, святи́є пра́ведници. Усли́шіте, мо́лим вас, вели́ції Христо́ви уго́дниці, вас с ві́рою призивающия і іспросі́те моли́твами ва́шими у Отця́ Небе́снаго всім нам проще́ніє гріхо́в на́ших і от бід ізбавле́ніє. Ви бо помо́щници, засту́пниці і моли́твенниці, і о вас сла́ву возсила́єм Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпче святи́й, великому́чениче і ціле́бниче Пантелеї́моне, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ // претерпі́л єси́."]}],"notes":[]},{"u":"Молитва преподобному Антонію Великому, Єгипетському","e":"Prayer to St Anthony the Great of Egypt","secs":[{"h":"Тропар, глас 4","ps":["Ревни́теля Ілію́ нра́ви подра́жая, / Крести́телю пра́вими стезя́ми послі́дуя, / о́тче Анто́ніє, / пусти́ні бил єси́ жи́тель, / і вселе́нную утверди́л єси́ моли́твами твої́ми. / Ті́мже моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Жите́йськія молви́ отри́нув, / безмо́лвно житіє́ сконча́л єси́, / Крести́теля подража́яй вся́ким о́бразом преподо́бнійший, / с ним у́бо тя почита́єм, // отце́в нача́льниче Анто́ніє."]},{"h":"Молитва","ps":["О преподо́бне і богоно́сне о́тче наш Анто́ніє! Ві́руєм, я́ко ти, предстоя́ престо́лу Пресвяти́я Тро́йці, ве́ліє і́маши дерзнове́ніє в моли́твах ко Всемилостивому́ Го́споду Бо́гу, І́же всегда́ послу́шаєть тебі́, ві́рнаго раба́ і уго́дника Своєго́. Сего́ ра́ди со умиле́нієм смире́нно припа́даєм к тебі́, свя́тче Бо́жий: не премолчи́ о нас моли́тися ко Го́споду Бо́гу, в Тро́йці покланя́ємому і сла́вимому, да, ми́лостивно призрі́в на ни, не попу́стить нам поги́бнути во грісі́х на́ших, но да возста́вить па́дших, да пода́сть ісправле́ніє зло́му і окая́нному на́шему житію́, от гряду́щих гріхопаде́ній восхища́я, і да прости́ть нам вся, єли́ка согріши́хом ми́слію, сло́вом і ді́лом, от рожде́нія до сего́ часа́. Ти, подви́жниче доброді́телі, ві́си не́мощ і скорб време́н настоя́щих, моли́ у́бо ви́ну Христа́ Бо́га, да ніколи́же нас оставля́єть Єго́ неізрече́нноє милосе́рдіє, но да храни́ть нас от мирськи́х іскуше́ній, от дия́вольських сіте́й і от плотськи́х по́хотей, да при́ймем от Него́ тобо́ю і вся потре́бная к жи́зні вре́менній, освобожде́ніє от бід і напа́стей, і неосла́бноє терпі́ніє до конця́. Іспроси́ нам в ми́рі і покая́нії сконча́ти живо́т наш і невозбра́нно прейти́ от землі́ на не́бо, мита́рств же, і бісо́во возду́шних, і ві́чния муки́ ізба́витися, і сподо́битися Ца́рства Небе́снаго с тобо́ю і со всі́ми святи́ми, угоди́вшими Го́споду Бо́гу і Спаси́телю на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О, преподо́бне о́тче Анто́ніє! Мо́лим тя ми, недосто́йнії, іспроси́ предста́тельством твої́м у Всеми́лостиваго Бо́га на́шего нам здра́віє душе́вноє і тіле́сноє, ти́хоє і Богоуго́дноє житіє́ і до́брий отві́т на стра́шнім суді́ Христо́ві. Угаси́ моли́твами твої́ми разжже́нния на ни стрі́ли дия́вольськия, да не прико́снеться нам зло́ба гріхо́вная, да благоче́стно сконча́вше вре́менноє житіє́, сподо́бимся наслі́довати Ца́рствіє Небе́сноє і ку́пно с тобо́ю сла́вити Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва рівноапостольним Кирилу і Мефодію, учителям Словенським","e":"Prayer to the Equals-to-the-Apostles Cyril and Methodius, Teachers of the Slavs","secs":[{"h":"Тропар, глас 4","ps":["Я́ко апо́столом єдинонра́внії / і слове́нських стран учи́теліє, / Кири́лле і Мефо́діє Богому́дрії, / Влади́ку всіх молі́те, / вся язи́ки слове́нськия утверди́ти в Правосла́вії і єдиноми́слії, / умири́ти мир // і спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 3","ps":["Свяще́нную дво́їцю просвіти́телей на́ших почті́м, / Боже́ственних писа́ній преложе́нієм істо́чник Богопозна́нія нам істочи́вших, / із него́же да́же додне́сь неоску́дно почерпа́юще, / ублажа́єм вас, Кири́лле і Мефо́діє, / Престо́лу Ви́шняго предстоя́щих // і те́плі моля́щихся о душа́х на́ших."]},{"h":"Молитва перша","ps":["О пресла́внії просвіти́теліє слове́нських язи́к, святі́ї равноапо́стольнії Мефо́діє і Кири́лле, ва́ших письме́н і уче́ній сві́том просвіти́вшеся і во ві́рі Христо́вой наста́вльшеся, я́ко ча́да ко отце́м, усе́рдно ни́ні прибіга́єм і сокруше́нієм серде́чним мо́лимся: а́ще і заві́т ва́ших не соблюдо́хом, о угожде́нії бо Бо́гу небрего́хом і от бра́тняго єдиноми́слія во ві́рі отпадо́хом, оба́че я́коже дре́вле в земно́м житії́ ва́шем, си́це і ни́ні грі́шних і недосто́йних не отвраті́те тщи, но, я́ко іму́ще ве́ліє ко Го́споду дерзнове́ніє, прилі́жно Того́ молі́те, да обрати́ть нас в путь спасе́нія, да умири́ть раздо́ри єдинові́рних, да приведе́ть к єдиноми́слію отпа́вших і всіх нас ду́хом любве́ да соєдини́ть Єди́ній Святі́й, Собо́рній і Апо́стольстій Це́ркві! Ві́ми бо, я́ко мно́го мо́жеть моли́тва пра́ведних по благосе́рдію Влади́ки. Не оста́віте у́бо нас, уни́лих і недосто́йних, чад ва́ших, ї́хже ра́ди гріхо́в па́ства ва́ша, враждо́ю разділя́єма і собла́знами іносла́вних прельща́єма, ума́лися, о́вці же слове́сния, разрива́єми, восхища́ються во́лки губи́тельними. Пода́ждьте у́бо нам моли́твами ва́шими ре́вность Правосла́вія, я́ко да оте́чеськая преда́нія до́брі сохрани́м, кано́ни церко́вниє ві́рно соблюде́м, вся́ких лжеуче́ній стра́нних отбіжи́м і, та́ко в житії́ богоуго́дном преспіва́юще, жи́зні ра́йськия на Небесі́ сподо́бимся, іді́же ку́пно с ва́ми просла́вим в Тро́йці Єди́наго Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всехва́льнії равноапо́стольнії Мефо́діє і Кири́лле, припа́дающе пред честно́ю іко́ною ва́шею, усе́рдно мо́лим ви: воззрі́те ми́лостивно на нас, ї́хже трудо́м ва́шим просвіти́ли єсте́, і огради́те нас неуси́пним предста́тельством ва́шим от злих ко́зней вра́жиїх! При́зріте у́бо на виногра́д сей, єго́же насади́ли єсте́, і не преда́йте ди́веєму ве́прю озоба́ти єго́. Сохрані́те, святі́ї уго́дниці Бо́жії, Це́рков на́шу Правосла́вную, ю́же ви назда́ли єсте́ на краєуго́льном Ка́мені, Христе́, я́ко да бу́деть недви́жима, но да разси́п'яться о Ка́мень сей во́лни вся́каго малові́рія. Укріпі́те па́стирей на́ших во всіх доброді́теліх і в по́двизі пропові́данія, вразумі́те же пасо́мих, во є́же послу́шати гла́са їх. Сохрані́те вся страни́ слове́нськия от вся́каго оскуді́нія, от огня́ і меча́, от смертоно́сния я́зви і от вся́кого зла. Усли́шіте і вся́каго челові́ка; с ві́рою к вам приходя́щаго і благода́тния по́мощі ва́шея тре́бующаго. В стра́шний же час сме́ртний предста́ніте всім нам блазі́ї хода́таї і те́мних зра́ков де́монських прогони́теліє, да в ми́рі і покая́нії сконча́вше земно́є по́прище, дости́гнем ві́чних благ наслажде́нія і ку́пно с ва́ми просла́вим Пресвяту́ю Тро́йцю — Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / святі́ї равноапо́стольнії Мефо́діє і Кири́лле, / вся слове́нськия страни́ уче́ньми свої́ми просвети́вшия // і ко Христу́ приве́дшия."]}],"notes":[]},{"u":"Молитва преподобним Зосимі й Савватію Соловецьким","e":"Prayer to Sts Zosima and Savvaty of Solovki","secs":[{"h":"Тропар, глас 8","ps":["Я́ко світи́льници яви́стеся всесві́тлії / во ото́ці окія́на мо́ря, / преподо́бнії отці́ Зоси́мо і Савва́тіє / ви бо крест Христо́в на ра́мо взе́мше, / усе́рдно Тому́ послі́довасте / і, чистото́ю Бо́гові прибли́жившеся, / отону́ду си́лами чуде́с обогати́стеся. / Ті́мже і ми любе́зно притека́єм к ра́кам честни́х моще́й ва́ших / і уми́льно глаго́лем: // о преподо́бнії, молі́те Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["По́стничеськоє і равноа́нгельськоє житіє́ ва́ше, / преподо́бнії отці́ Зоси́мо і Савва́тіє, / вселе́нній позна́ни сотвори́ вас; / чудодія́нії разли́чними, Богоно́снії, просвіща́єте // ві́рою призива́ющия ви і чту́щия честну́ю па́м'ять ва́шу."]},{"h":"Кондак, глас 2","ps":["Христо́вою любо́вію уязви́вшеся, преподо́бнії, / і Того́ крест, на ра́мо взе́мше, понесли́ єсте́, / боже́ственне вооружи́вшеся на неви́димия враги́ / і непреста́нния моли́тви, я́ко копіє́ в рука́х, іму́ще, / крі́пко побіди́ли єсте́ бісо́вськая ополче́нія; / благода́ть Госпо́дню приє́мше ціли́ти неду́ги душ і тіле́с / притека́ющих к ра́кам честни́х моще́й ва́ших, / чуде́с лучи́ іспуща́єте всю́ду. / Тім зове́м вам: / ра́дуйтеся, преподо́бнії отці́ Зоси́мо і Савва́тіє, // мона́хов удобре́ніє."]},{"h":"Молитва перша","ps":["О преподо́бнії і Богоно́снії отці́ на́ші Зоси́мо і Савва́тіє, земні́ї а́нгели і Небе́снії челові́ци, бли́жнії дру́зі Христо́ви і уго́дниці Бо́жії, оби́телі ва́шея сла́во і украше́ніє, всея́ же сі́верния страни́, па́че і всего́ Правосла́внаго оте́чества на́шего необори́мая стіно́ і вели́коє заступле́ніє! Се ми, недосто́йнії і многогрі́шнії, с благогові́йною любо́вію ко святи́м моще́м ва́шим припа́дающе, ду́хом сокруше́нним і смире́нним прилі́жно мо́лим вас: молі́те непреста́нно благосе́рдаго Влади́ку і Го́спода на́шего Ісу́са Христа́, я́ко дерзнове́ніє ве́ліє к Тому́ іму́щії, да не отсту́пить от нас Єго́ вседі́йствующая благода́ть, покро́в же і заступле́ніє Пресвяти́я Влади́чиці на́шея Богоро́диці на мі́сті сем да пребу́деть, і да не оскуді́ють нікогда́же і́стиннії ревни́тели а́нгельськаго житія́ во святі́й оби́телі сей, іді́же ви, богоно́снії отці́ і нача́льниці, безмі́рними труди́ і поще́ньми, то́ки же сле́зними і всено́щними бді́нії, непреста́нними моли́твами і моле́ньми нача́ло і́ночеському житію́ положи́сте. Єй, уго́дниці святі́ї, моли́твенниці к Бо́гу благоприя́тнійшії, те́плими ва́шими к Нему́ мольба́ми огради́те і сохрані́те ни і свято́є селе́ніє сіє́ ва́ше от тру́са, пото́па, огня́ і меча́, наше́ствія іноплеме́нних і смертоно́сния я́зви, от вражди́ і вся́ких нестроє́ній, от вся́кия біди́ і ско́рби і от вся́каго зла: да непреста́нно на мі́сті сем, в ми́рі і безмо́лвії, благоче́стно сла́виться пресвято́є І́м'я Го́спода і Бо́га, і обріта́ють ві́чноє спасе́ніє і́щущиє Єго́. О преблаже́ннії отці́ на́ші, Зоси́мо і Савва́тіє! Усли́шіте ни грі́шния, во святі́й оби́телі ва́шей і под кро́вом ва́шего защище́нія недосто́йно жи́тельствующия, і благомо́щними ва́шими к Бо́гу хода́тайстви іспросі́те душа́м на́шим гріхо́в оставле́ніє, житія́ ісправле́ніє і ві́чних благ восприя́тіє в Небе́снім Ца́рствії: всім же ві́рующим, і́же на вся́ком мі́сті і во вся́кой нужді́ призива́ють вас в по́мощ і заступле́ніє, і і́же с благогові́йною любо́вію во оби́тель ва́шу притека́ють, не преста́ніте ізлива́ти вся́кую благода́ть і ми́лость, сохраня́юще їх от вся́кия сопроти́вния си́ли, от вся́кия напа́сти і от вся́каго зла́го обстоя́нія, і подаю́ще їм вся потре́бная к душе́вній і тіле́сній по́льзі. Найпа́че же молі́те премилосе́рдаго Бо́га, да утверди́ть і укріпи́ть Це́рков Свою́ святу́ю і все на́ше Правосла́вноє оте́чество в ми́рі і тишині́, в любві́ і єдиноми́слії, в правові́рії і благоче́стії да сохрани́ть і соблюде́ть во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бнії отці́, вели́ції засту́пниці в ско́рбі і усли́шателіє моли́тв, уго́дниці Бо́жії і чудотво́рці Зоси́мо і Савва́тіє! Не забу́діте, я́коже обіща́стеся, посіща́ти ча́да ва́ша. А́ще бо і отидо́сте от нас ті́лом, но ду́хом при́сно с на́ми пребива́єте. Мо́лим у́бо вас, о преподо́бнії, ізба́віте ни от огня́ і меча́, от наше́ствія іноплеме́нников і междоусо́бния бра́ні, от тлітво́рних ві́тров і от внеза́пния сме́рти і от всіх прило́г бісо́вських, находя́щих на ни. Усли́шіте нас, грі́шних, і приймі́те моли́тву сію́ і моле́ніє на́ше, я́ко кади́ло благово́нноє, я́ко же́ртву благоуго́дную, і ду́ші на́ша, зли́ми ді́ли і сові́ти і по́мисли умерщвле́нния, оживі́те. І я́коже уме́ршую отрокови́цю возста́висте, і неісці́льния ра́ни мно́гих ісціли́сте, і от духо́в нечи́стих злі му́чимия ізба́висте; та́ко і нас, содержи́мих во у́зах вра́жиїх, ізьмі́те, і от сіте́й дия́вола ізба́віте, із глубини́ прегріше́ній ізведі́те, і ми́лостивим ва́шим посіще́нієм і хода́тайством от враг ви́димих і неви́димих огради́те ни, благода́тію і си́лою Пресвяти́я Тро́йці, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Ігнатію Брянчанінову, єпископу Кавказькому і Чорноморському","e":"Prayer to St Ignatius Brianchaninov, Bishop of the Caucasus and the Black Sea","secs":[{"h":"Тропар, глас 8","ps":["Правосла́вія побо́рниче, / покая́нія і моли́тви ді́лателю і учи́телю ізря́дний, / архієре́єв богодухнове́нноє украше́ніє, / мона́шествующих сла́во і похвало́: / писа́нії твої́ми вся ни уцілому́дрил єси́. / Цівни́це духо́вная, Ігна́тіє богому́дре, / моли́ Сло́ва Христа́ Бо́га, / Єго́же носи́л єси́ в се́рдці твоє́м, // дарова́ти нам пре́жде конця́ покая́ніє."]},{"h":"Інший тропар, глас 8","ps":["Ізбра́нник возлю́блен Христо́ві яви́лся єси́, / Тому́ скорбми́ мно́гими і моли́твою непреста́нною приліпи́вся, / благода́ть Ду́ха Свята́го стяжа́в, / учи́тель ізря́ден лю́дем бил єси́. / Помина́й нас, святи́телю Ігна́тіє, богоно́се Український, / да уче́нії і моли́твами твої́ми покая́ніє спаси́тельноє обря́щем / і любо́вію серде́чною Христу́ усво́їмся."]},{"h":"Кондак, глас 8","ps":["А́ще і соверша́л єси́ стезю́ житія́ земна́го, святи́телю Ігна́тіє, / оба́че непреста́нно зрел єси́ зако́ни битія́ ві́чнаго, / сему́ поуча́я ученики́ словеси́ мно́гими, // і́мже послі́довати і нам, свя́тче, помоли́ся."]},{"h":"Молитва","ps":["О вели́кий і пречу́дний уго́дниче Христо́в, святи́телю о́тче Ігна́тіє! Ми́лостиво прийми́ моли́тви на́ша, с любо́вію і благодаре́нієм тебі́ приноси́мия! Усли́ши нас си́рих і безпо́мощних, к тебі́ с ві́рою і любо́вію припа́дающих і твоєго́ те́плаго предста́тельства о нас пред Престо́лом Го́спода Сла́ви прося́щих. Ві́ми, я́ко мно́го мо́жеть моли́тва пра́ведника, Влади́ку умилостивля́ющая. Ти от літ младе́нчеських Го́спода пла́менно возлюби́л єси́ і Єму́ Єди́ному служи́ти восхоті́в, вся кра́сная ми́ра сего́ ні во что́же вміни́л єси́. Ти отве́ргся себе́ і взем крест твой, Христу́ послі́довал єси́. Ти путь у́зький і приско́рбний житія́ і́ночеськаго во́лею себі́ ізбра́л єси́ і на сем путі́ доброді́телі вели́кия стяжа́л єси́. Ти писа́ньми твої́ми сердца́ челові́ков глубоча́йшаго благогові́нія і поко́рности пред Всемогу́щим Творцо́м ісполня́л єси́, грі́шников же па́дших му́дрими словеси́ твої́ми в созна́нії своєго́ нічто́жества і своєя́ грехо́вности, в покая́нії і смире́нії прибіга́ти к Бо́гу наставля́л єси́, ободря́я їх упова́нієм на Єго́ милосе́рдіє. Ти ніколи́же притека́вших к тебі́ отверга́л єси́, но всім оте́ць чадолюби́вий і па́стир до́брий бил єси́. І ни́ні не оста́ви нас, усе́рдно тебі́ моля́щихся і твоєя́ по́мощі і предста́тельства прося́щих. Іспроси́ нам у человіколюби́ваго Го́спода на́шего здра́віє душе́вноє і тіле́сноє, утверди́ ві́ру на́шу, укріпи́ си́ли на́ша, ізнемога́ющия во іскуше́ніїх і скорбі́х ві́ка сего́, согрі́й огне́м моли́тви охладе́вшая сердця́ на́ша, помози́ нам, покая́нієм очи́стившимся, христия́нськую кончи́ну живота́ сего́ получи́ти і в черто́г Спа́сов преукраше́нний вни́ти со всі́ми ізбра́нними і та́мо ку́пно с тобо́ю покланя́тися Отцю́ і Си́ну і Свято́му Ду́ху во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Феодосію, ігумену Києво-Печерському","e":"Prayer to St Theodosius, Abbot of the Kyiv Caves","secs":[{"h":"Тропар, глас 8","ps":["Возви́сився на доброді́тель, / ізмла́да возлюби́в мона́шеськоє житіє́, / к жела́нію до́блественне дости́г, всели́лся єси́ в пеще́ру, / і, украси́в житіє́ твоє́ поще́нієм і сві́тлостію, / в моли́твах, я́ко безпло́тен, пребива́л єси́, / в Українській землі́, я́ко сві́тлоє світи́ло, просі́яв, о́тче Феодо́сіє, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Інший тропар перенесенню мощей, глас 8","ps":["Правосла́вія наста́вниче, / благоче́стія учи́телю і чистоти́, / вселе́нния світи́льниче, / архієре́єв богодухнове́нноє удобре́ніє, / Феодо́сіє прему́дре, / уче́ньми твої́ми вся просвіти́л єси́, цівни́це духо́вная, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 3","ps":["Звізду́ Українськую днесь почті́м, / от восто́ка возсія́вшую і на за́пад прише́дшую, / всю бо страну́ сію́ чудеси́ і добро́тою обогати́вшу і вся ни / соді́янієм і благода́тію мона́шеськаго уста́ва, // блаже́ннаго Феодо́сія."]},{"h":"Інший кондак перенесенню мощей, глас 8","ps":["Наслі́дник отце́в бил єси́, преподо́бне, / тіх послі́дуя житію́ і уче́нію, / оби́чаю і воздержа́нію, / моли́тві же і предстоя́нію. / С ни́миже, імі́я дерзнове́ніє ко Го́споду, / проще́ніє согріше́ній і спасе́ніє іспроси́ вопію́щим ті: // ра́дуйся, о́тче Феодо́сіє."]},{"h":"Молитва","ps":["О свяще́нная главо́, А́нгеле земни́й і челові́че Небе́сний, преподо́бне і Богоно́сне о́тче наш Феодо́сіє, ізря́дний слуго́ Пресвяти́я Богоро́диці, во і́м'я Єя́ свято́є оби́тель пречу́дну на гора́х Пече́рських сооруди́вий, і в ней чуде́с мно́жеством просія́вий! Мо́лим тя со усе́рдієм мно́гим, моли́ся за нас ко Го́споду Бо́гу, і іспроси́ от Него́ вели́кия і бога́тия ми́лости: ві́ру пра́ву, наде́жду спасе́нія несомні́нну, любо́в ко всім нелицемі́рну, благоче́стіє непоколеби́моє, душ і тіле́с здра́віє, жите́йських потре́б дово́льство, і да не во зло обрати́м блага́я, да́руємая нам от щедрода́тельния Єго́ десни́ці, но в сла́ву І́мені Єго́ свята́го, і во спасе́ніє на́ше. Сохрани́, уго́дниче Бо́жий, предста́тельством твої́м святи́м страну́ на́шу, Це́рков Православноукраїнськую, град твой, і Ла́вру твою́ невреди́мими от вся́каго зла, і вся лю́ди притека́ющия на поклоне́ніє к честно́му твоєму́ гро́бу і пребива́ющия во святі́й оби́телі твоє́й, осіни́ Небе́сним твої́м благослове́нієм і от вся́ких зол і бід ми́лостивно ізба́ви. Найпа́че же в час кончи́ни на́шея покажи́ нам многомо́щноє твоє́ покрови́тельство: да ізба́вимся моли́твами твої́ми ко Го́споду вла́сті лю́таго мироде́ржця і сподо́бимся наслі́дити Ца́рство Небе́сноє. Яви́ нам, о́тче, благосе́рдіє твоє́ і не оста́ви нас си́рих і безпо́мощних, да ви́ну славосло́вим ди́внаго во святи́х Свої́х Бо́га, Отця́, і Си́на, і Свята́го Ду́ха, і твоє́ свято́є заступле́ніє, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва апостолу Симону Зилоту","e":"Prayer to the Apostle Simon the Zealot","secs":[{"h":"Тропар, глас 3","ps":["Апо́столе святи́й Си́моне, / моли́ ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє / пода́сть душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Ізві́стно прему́дрости уче́нія в душа́х благоче́ствующих поло́жшаго / во хвале́нії ублажі́м, я́ко Богоглаго́ливаго всі Си́мона: / престо́лу бо сла́ви ни́ні предстої́ть і со Безпло́тними весели́ться, / моля́ся непреста́нно о всіх нас."]},{"h":"Молитва","ps":["Святи́й сла́вний і всехва́льний апо́столе Христо́в Си́моне, сподо́бивийся прия́ти в дом твой в Ка́ні Галиле́йстій Го́спода на́шего Ісу́са Христа́ і Єго́ Пречи́стую Ма́тер, Влади́чицю на́шу Богоро́дицю, і очеви́дцем би́ти пресла́внаго чудесе́ Христо́ва, на бра́ці твоє́м явле́ннаго, претворе́нія води́ во вино́! Мо́лим тя с ві́рою і любо́вію: умоли́ Христа́ Го́спода претвори́ти ду́ші на́ша із гріхолюби́вих в боголюби́вия; сохрани́ і соблюди́ нас моли́твами твої́ми от іскуше́ній дия́вольських і паде́ній гріхо́вних, і іспроси́ нам сви́ше по́мощ во вре́м'я уни́нія і беспомо́щія на́шего; да не преткне́мся о ка́мень собла́зна, но неукло́нно ше́ствуєм спаси́тельним путе́м за́повідей Христо́вих, до́ндеже дости́гнем о́них блаже́нних оби́телей ра́йських, іді́же ти ни́ні водворя́єшися і весели́шися. Єй, апо́столе Спа́сов! Не посрами́ нас, крі́пці на тя упова́ющих, но бу́ди нам помо́щник і покрови́тель во всем житії́ на́шем і помози́ нам благоче́стно і богоуго́дно житіє́ сіє́ вре́менноє сконча́ти, благу́ю і ми́рную христия́нськую кончи́ну получи́ти і до́браго отві́та сподо́битися на Стра́шнім Суді́ Христо́ві; да избіжа́вше мита́рств возду́шних і вла́сті лю́таго мироде́ржця, унаслі́дуєм Ца́рство Небе́сноє і просла́вим великолі́поє І́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва князю Димитрію Донському","e":"Prayer to Prince Dimitry Donskoy","secs":[{"h":"Тропар, глас 3","ps":["Вели́ка обрі́те в біда́х тя побо́рника земля́ Українськая, / язи́ки побіжда́юща. / Я́коже на Дону́ Мама́єву низложи́л єси́ горди́ню, / на по́двиг сей прия́в благослове́ніє преподо́бнаго Се́ргия, / та́ко, кня́же Дими́тріє, / Христу́ Бо́гу моли́ся, // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["По́двиги твої́ми, свя́те Дими́тріє, / страну́ на́шу Бог сохрани́, / да́вий тебі́ си́лу непобіди́мую. / І ни́ні, предста́телю крі́пкий, / соблюда́й моли́твами святи́ми / град твой Київ невреди́м // от всіх наві́т вра́жиїх."]},{"h":"Молитва перша","ps":["О святи́й благові́рний вели́кий кня́же Дими́тріє! А́ще і не мно́зі би́ша дні́є земна́го житія́ твоєго́, оба́че вели́к жре́бій прия́л єси́ от Соді́теля всіх Го́спода, є́же просла́витися в землі́ Українській і блаже́нство ві́чноє на Небесі́х получи́ти.","Усли́ши нас, моли́твенниче те́плий, предста́телю наш пред Го́сподем неуси́пний! Во дні ми́ра і в годи́ну нестроє́ній не оста́ви нас попече́нієм твої́м, научи́ ни поко́рни би́ти Боже́ственному Промишле́нію, вся в житії́ на́шем ко бла́гу направля́ющему, оте́чество на́ше моли́твами твої́ми от наше́ствій вра́жиїх, раздо́ров і нестроє́ній защити́ і укріпи́ те́плим твої́м предста́тельством.","О свя́тче Бо́жий! Моли́, ку́пно со свято́ю супру́жницею і сподви́жницею твоє́ю благові́рною княги́нею Євдоки́єю, да зна́менається на нас світ лиця́ Бо́жия, і, тім наставля́ємі, дости́гнем Ца́рства Пра́вди Христо́ви, несконча́ємаго і ві́чнаго. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́й уго́дниче Бо́жий, пра́ведне Дими́тріє! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всеми́лостивому Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і по́мощі нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й благові́рний вели́кий кня́же Дими́тріє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва рівноапостольним Костянтину царю і матері його цариці Олені","e":"Prayer to the Equals-to-the-Apostles Emperor Constantine and his mother Empress Helena","secs":[{"h":"Тропар, глас 8","ps":["Креста́ Твоєго́ о́браз на Небесі́ ви́дів / і, я́коже Па́вел, зва́ніє не от челові́к приє́м, / в царі́х апо́стол Твой, Го́споди, / Ца́рствующий град в руці́ Твоє́й положи́, / єго́же спаса́й всегда́ в ми́рі моли́твами Богоро́диці, // Єди́не Человіколю́бче."]},{"h":"Кондак, глас 3","ps":["Константи́н днесь с ма́терію Єле́ною / Крест явля́ють, всечестно́є дре́во, / всіх у́бо іуде́єв посрамле́ніє су́ще, / ору́жіє же на проти́вния ві́рних люде́й: / нас бо ра́ди яви́ся зна́меніє ве́ліє // і во брані́х гро́зноє."]},{"h":"Молитва перша","ps":["О преди́внії і всехва́льнії ца́ріє, святі́ї равноапо́стольнії Константи́не і Єле́но! К вам, те́плим засту́пником, возно́сим на́ші недосто́йния моли́тви, я́ко ве́ліє і́мате дерзнове́ніє ко Го́споду. Іспросі́те у Него́ мир Це́ркві і всему́ ми́ру благоде́нствіє. Нача́льником му́дрость, па́стирем попече́ніє о па́стві, пасо́мим смире́ніє, ста́рцем жела́нноє упокоє́ніє, муже́м крі́пость, жена́м благолі́піє, ді́вственником чистоту́, ді́тем послуша́ніє, младе́нцем христия́нськоє воспита́ніє, больни́м ісціле́ніє, вражду́ющим примире́ніє, оби́димим терпі́ніє, оби́дящим страх Бо́жий. Приходя́щим в храм сей і моля́щимся в нем свято́є благослове́ніє і всім вся по коєго́ждо проше́нію поле́зная, да хва́лим і поє́м Благоді́теля всіх Бо́га в Тро́йці сла́вимаго Отця́ і Си́на і Свята́го Ду́ха ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святі́ї равноапо́стольнії Константи́не і Єле́но! Ізба́віте прихо́д сей і храм наш от вся́каго наві́та вра́жия і не оста́віте заступле́нієм ва́шим нас, немощни́х (імена́), умолі́те бла́гость Христа́ Бо́га на́шего дарова́ти нам по́мислов мир, от па́губних страсте́й і вся́кой скве́рни воздержа́ніє, благоче́стіє же нелицемі́рноє. Іспросі́те нам, уго́дниці Бо́жії, сви́ше дух кро́тости і смиренному́дрія, дух терпі́нія і покая́нія, да про́чеє вре́м'я житія́ на́шего во ві́рі і сокруше́нії серде́чнім поживе́м, і та́ко в час сконча́нія на́шего благода́рно восхва́лим просла́вльшаго вас Го́спода, Безнача́льнаго Отця́, Єдиноро́днаго Єго́ Си́на і Єдиносу́щнаго Всеблага́го Ду́ха, Тро́йцю Неразді́льную, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / святі́ї благові́рнії і равноапо́стольнії ца́ріє Константи́не і Єле́но, / і чтим святу́ю па́м'ять ва́шу, / ви бо святи́м Кресто́м // всю вселе́нную просвіти́ли єсте́."]}],"notes":[]},{"u":"Молитва преподобному Мефодію, ігумену Пешношському","e":"Prayer to St Methodius, Abbot of Peshnosha","secs":[{"h":"Тропар, глас 8","ps":["Боже́ственною любо́вію от ю́ности распала́єм, / вся, я́же в ми́рі кра́сная, возненави́дів, / Христа́ Єди́наго возлюби́л єси́, / і, сего́ ра́ди в пусти́ню всели́вся, / в ней оби́тель сотвори́л єси́, / і, собра́в і́нок мно́жество, / прия́л єси́ от Бо́га чуде́с дар, о́тче Мефо́діє, / і бил єси́ о Христі́ собесі́дник і спо́стник преподо́бному Се́ргію, / с ни́мже у Христа́ Бо́га іспроси́ правосла́вним Христия́ном здра́віє, і спасе́ніє, // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Послуша́нія до́брий рачи́тель бив, / безпло́тния враги́ сле́зними моли́твами твої́ми крі́пко посрами́л єси́ / і яви́лся єси́ Пресвяти́я Тро́йці жили́ще, / Ю́же зря, блаже́нне, я́сно, / Богому́дре Мефо́діє преподо́бне, / чуде́с дар от Нея́ прия́л єси́. / Ті́мже ісціля́єши с ві́рою приходя́щих неду́ги, / утоля́єши ско́рби // і мо́лишися непреста́нно о всіх нас."]},{"h":"Молитва перша","ps":["О свяще́нная главо́, земни́й А́нгеле і Небе́сний челові́че, преподо́бне і Богоно́сне о́тче наш Мефо́діє! Припа́даєм к тебі́ с ві́рою і любо́вію, і мо́лимся прилі́жно: яви́ нам, смире́нним і грі́шним, свято́є оте́чеськоє твоє́ заступле́ніє: се бо гріх ра́ди на́ших не і́мами свобо́ди чад Бо́жиїх, проси́ти о потре́бах на́ших Го́спода і Влади́ку на́шего, но тебі́, моли́твенника благоприя́тнаго к Нему́ предлага́єм, і про́сим тя со усе́рдієм мно́гим, іспроси́ нам у бла́гости Єго́ благопотре́бния да́ри душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду спасе́нія несомні́нну, любо́в ко всім нелицемі́рну, в іскуше́ніїх му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, душе́ і тілесе́ здра́віє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, жите́йських потре́б дово́льство, ми́рноє і безм'яте́жноє житіє́, благу́ю христия́нськую кончи́ну і до́брий отві́т на Стра́шном Суді́ Христо́ві. Іспроси́, уго́дниче Бо́жий, у Царя́ ца́рствующих і Го́спода госпо́дствующих правосла́вним христия́ном спасе́ніє і на враги́ одолі́ніє і всему́ оте́честву на́шему мир, тишину́ і благостроє́ніє. Не лиши́ нас по́мощі твоєя́ Небе́сния, но моли́твами твої́ми всіх нас приведи́ в приста́нище спасе́нія і наслі́дники яви́ нас би́ти всесві́тлаго Ца́рствія Христо́ва, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха і твоє́ свято́є оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий уго́дниче Христо́в і пресла́вний чудотво́рче, преподо́бне о́тче наш Мефо́діє! При́зри на ни грі́шния, обурева́ємия треволне́нієм жите́йських страсте́й і к тебі́ вопію́щия: ми бо, ча́да твоя́ духо́вная і огра́ди твоєя́ слове́сния о́вці, на тя, по Бо́зі і Богоро́дице, упова́ніє на́ше возлага́єм, і тя со умиле́нієм про́сим: хода́тайством ко Го́споду Бо́гу іспроси́ нам мир, здра́віє, долгоде́нствіє, возду́ха благорастворе́ніє, землі́ плодоно́сіє, дожди́ благовре́менни, і вся ни ізба́ви от вся́ких бід: гра́да, гла́да, пото́па, огня́, меча́, вредоно́снаго че́рвія сніда́ющаго плоди́ земни́я, тлітво́рних вітро́в, смертоно́сния я́зви і напра́сния сме́рти, і во всіх ско́рбіх і печа́ліх на́ших бу́ди нам уті́шитель благи́й і помо́щник ско́рий, сохраня́я нас моли́твами твої́ми от паде́ній гріхо́вних і сподобля́я наслі́дники би́ти Ца́рствія Небе́снаго: да прославля́єм вку́пі с тобо́ю всіх благ пода́теля, в Тро́йці сла́вимаго і покланя́ємаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іоанну (Максимовичу), архієпископу Шанхайському і Сан-Франциському","e":"Prayer to St John (Maximovitch), Archbishop of Shanghai and San Francisco","secs":[{"h":"Тропар, глас 5","ps":["Попече́ніє твоє́ о па́стві в стра́нствії єя́, / се проо́браз і моли́тв твої́х, за мир весь при́сно возноси́мих. / Та́ко ві́руєм, позна́вше любо́в твою́, / святи́телю і чудотво́рче Іоа́нне! / Весь от Бо́га освяще́н священноді́йствієм пречи́стих Та́їн, / ї́миже сам при́сно укріпля́єм, поспіша́л єси́ ко стра́ждущим, ціли́телю отра́днійшій. / Поспіши́ і ни́ні в по́мощ нам всім се́рдцем чту́щим тя."]},{"h":"Кондак, глас 4","ps":["Се́рдце твоє́ обє́млеть всіх любо́вію / моля́щих ті ся, Іоа́нне святи́телю, / і помина́ющих по́двиг житія́ твоєго́. / Безболі́зненно же ле́гкоє преставле́ніє твоє́ бисть, / Одиги́трії Пречи́стия ві́рний служи́телю."]},{"h":"Твір Закордонної Церкви","ps":[]},{"h":"Тропар, глас 6","ps":["Сла́вний апо́столом Христо́вим наслі́дниче, / яви́лся єси́ нас малове́рних і хла́дних се́рдцем спасти́. / Дре́вніх святи́х благода́тію і по́двигами обле́клся єси́, / сего́ ра́ди от Бо́га небе́сния та́йни приє́мше. / О, сиропита́телю предо́брий, / подаю́щий наде́жду ми́ром отве́рженним, / о, світи́льниче Христо́в, / Боже́ственним пла́менем на за́рі Стра́шнаго Суда́ возже́нний. / Моли́ о нас, святи́телю о́тче Іоа́нне, / да возгоря́ться і на́ша сердця́ пла́менем спаси́тельной любві́ ко Христу́, // і спасти́ся душа́м на́шим во времена́ послі́дняя."]},{"h":"Інший тропар, глас 5","ps":["Попече́ніє твоє́ о па́стві в стра́нствії єя́, / се проо́браз і моли́тв твої́х, за мир весь при́сно возноси́мих; / та́ко ві́руєм, позна́в любо́в твою́, святи́телю і чудотво́рче Іоа́нне. / Весь от Бо́га освяще́н священноді́йствієм Пречи́стих Та́їн, / ї́миже сам при́сно укріпля́єм, / поспіша́л єси́ ко стра́ждущим, ціли́телю отра́днійшій. // Поспіши́ і ни́ні в по́мощ нам, всім се́рдцем чту́щим тя."]},{"h":"Кондак, глас 4","ps":["Се́рдце твоє́ распространи́ся ко всім, / любо́вію моля́щим тя, Іоа́нне святи́телю, / помина́ющим по́двиг всего́ многотру́дного житія́ твоєго́, / безболі́зненно же ле́гкоє преставле́ніє твоє́, // Одиги́трії Пречи́стия ві́рний служи́телю."]},{"h":"Молитва","ps":["О, святи́телю о́тче наш Іоа́нне, па́стирю до́брий і тайнови́дець душ челові́чеських. Ни́ні у Престо́ла Бо́жия за нас мо́лишися, я́ко же і сам посме́ртне ізре́к: “Хотя́ я і у́мер — но я жив”. Умоли́ Всеще́драго Бо́га проще́ніє нам во грісі́х дарова́ти, да смі́ло воспря́нем ду́хом і уни́ніє сего́ ми́ра отряхне́м і Бо́гу возопії́м о дарова́нії нам смире́нія і Богодухнове́нія, Богосозна́нія і ду́ха благоче́стія на вся́ких путя́х жи́зні на́шея. Я́ко ми́лостивий сиропита́тель і о́питний путеводи́тель на землі́ би́вший, ни́ні бу́ди нам вожде́м Мойсе́євим і в сму́тах церко́вних всеоб'є́млющеє Христо́во вразумле́ніє. Усли́ши стена́ніє смуще́нних ю́ношей на́шего лихолі́тія, обурева́ємих біснова́нієм вселука́вим і отряхни́ лень уни́нія ізнемога́ющих па́стирей от на́тисков ду́ха ми́ра сего́ і том'я́щихся в оцепе́ненії пра́здном. Да сле́зно вопіє́м ті, о те́плий моли́твенниче, посіти́ нас си́рих, во тьмі страсте́й утопа́ющих, жду́щих твоєго́ оте́чеськаго наставле́нія, да озарі́мся сві́том невече́рнім, іді́же ти пребива́єши і мо́лишися за чад твої́х, по лицю́ вселе́нния рассе́янних, но любо́вію сла́бою к сві́ту все же тяну́щихся, іді́же світ Христо́с Госпо́дь наш пребива́єть, Єму́ же честь і держа́ва ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобним Сергію і Герману, Валаамським чудотворцям","e":"Prayer to Sts Sergius and Herman, the Wonderworkers of Valaam","secs":[{"h":"Тропар, глас 4","ps":["Єва́нгелія Христо́ва і́стиннії послу́шници / яви́стеся, преподо́бнії, / мир і вся я́же в нем, я́ко не су́щая, / преоби́дівше любве́ ра́ди Христо́ви / і в морськи́й о́стров всели́стеся, / і трудолю́бно в нем проти́ву ко́зней неви́димих враго́в подвиза́стеся, / посто́м, бді́нієм же і всено́щним стоя́нієм / пло́ті своя́ ду́ху му́дру повину́ли єсте́. / Сего́ ра́ди от Вседержи́тельния десни́ці досто́йния вінці́ прия́ли єсте́. / І ни́ні Пресвяті́й Тро́йце предстоя́ще, / молі́теся, всеблаже́ннії отці́, Се́ргіє і Ге́рмане, / сохрани́тися в ми́рі оте́честву на́шему // і спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 1","ps":["От мирськи́я молви́ бі́гающе, / безмо́лвія і благоче́стія рачи́тели, / в ти́хоє приста́нище Валаа́ма / от восто́ка прийдо́сте / і в нем, єва́нгельськи Христу́ доброді́тельми послі́довавше, / на верх соверше́нства востекли́ єсте́. / І ни́ні в торжестві́ преми́рнім богозрі́нієм наслажда́ющеся, / всеблаже́ннії отці́ Се́ргіє і Ге́рмане, / Человіколю́бця Бо́га молі́те, // є́же спасти́ всіх нас, благоче́стно вас почита́ющих."]},{"h":"Кондак, глас 4","ps":["От мирська́го житія́ ізше́дше, / отверже́нієм ми́ра Христу́ послі́довасте, / і достиго́сте вели́каго Не́ва є́зера, / і, в нем на о́строві Валаа́мі все́льшеся, / равноа́нгельноє житіє́ пожи́ли єсте́, / отону́дуже, веселя́щеся, прешли́ єсте́ к Небе́сним черто́гом. / І ни́ні со А́нгели Влади́чню Престо́лу предстоя́ще, / помина́йте нас, чад свої́х, / я́же собра́ли єсте́, богому́дрії, / да ра́достно от душі́ вопіє́м: // ра́дуйтеся, Се́ргіє і Ге́рмане, отці́ преблаже́ннії."]},{"h":"Молитва перша","ps":["О вели́ції отці́ на́ші, Христо́ви уго́дниці і те́плії предста́телі ко Спа́су о душа́х на́ших, Се́ргіє і Ге́рмане! Ви бо в неду́зіх ціли́телі яви́стеся, по мо́рю пла́вающим ко́рмчії, і утопа́ющим благонаде́жноє ізбавле́ніє, і от вся́каго смертоно́снаго наше́ствія храни́тели, па́че же от духо́в нечи́стих свобожде́ніє і вся́ких наві́тов, проти́ву нас содержи́мих, очище́ніє і по́мощ. О преблаже́ннії отці́ і чудотво́рці пресла́внії, Се́ргіє і Ге́рмане, молі́теся ко Влади́ці Христу́ о нас, грі́шних, я́ко да ва́шими моли́твами сподо́бимся в день Су́дний десна́го предстоя́нія і наслажде́нія во Ца́рствії Бо́жії во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бнії і Богоно́снії отці́ на́ші Се́ргіє і Ге́рмане! С ві́рою і любо́вію припа́дающе к святі́й іко́ні ва́шей, умиле́нно мо́лим вас: не забу́діте нас, недосто́йних і грі́шних (імена́), но предста́тельством ва́шим огради́те нас от злих ко́зней вра́жиїх: утолі́те возста́ніє страсте́й: укріпі́те не́мощ на́шу в духо́вних бра́ніх і по́двизіх, предлежа́щих нам: отжені́те вся́коє уни́ніє і печа́ль гріхо́вную от серде́ць на́ших, і небе́сноє утіше́ніє низпослі́те нам во труді́х і ско́рбіх на́ших. В стра́шний же час сме́ртний предста́ніте всім нам, я́ко же блазі́ї хода́таї і те́мних зра́ков де́монських прогони́теліє: да в ми́рі і покая́нії сконча́вше земно́є по́прище на́ше, дости́гнем і ві́чних благ наслажде́нія, і ку́пно с ва́ми да воспоє́м і просла́вим всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Андрію Рубльову, іконописцю","e":"Prayer to St Andrei Rublev, the Iconographer","secs":[{"h":"Тропар, глас 3","ps":["Боже́ственнаго сві́та луча́ми облиста́ємий, / преподо́бне Андре́є, / Христа́ позна́л єси́ Бо́жию Прему́дрость і Си́лу, / і іко́ною Святи́я Тро́йці всему́ ми́ру пропові́дал єси́ / Єди́нство во Святі́й Тро́йці. / Ми же со удивле́нієм і ра́достію вопіє́м ті: / імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце // моли́ просвіти́ти ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["От ю́ности к Боже́ственній красоті́ устремля́яся, / чу́дний іконопи́сець в землі́ Українській бил єси́, / і, богоно́сним твої́м учи́телем поревнова́в, / сія́нієм доброді́телей украси́лся єси́, преподо́бне Андре́є, // ті́мже і яви́ся Це́ркве на́шея похвала́ і ра́дованіє."]},{"h":"Молитва","ps":["О преподо́бне о́тче Андре́є, зіло́ облагода́тствованний пресві́тлим да́ром виді́нія первоо́бразов красоти́ Боже́ственних! О ди́вний пло́де Це́ркве Українськия, о́трасле блага́я Се́ргиєм вели́ким насажде́нного дре́ва! В гро́зноє бо вре́м'я поста́ви тя Госпо́дь свиді́теля своєго́ і землі́ на́шея моли́твенника вели́ка тя соді́ла. Кто іспові́сть безчи́сленния труди́ і по́двиги твоя́, ра́зум земни́й превосходя́щия і єди́ному то́кмо ві́домих Го́споду, і́миже благода́ть писа́нія чудотворя́щих іко́н стяжа́л єси́! Ти благоуха́нієм святи́х твої́х іко́н весь мир іспо́лнил єси́, найпа́че о́бразом Пресвяти́я Тро́йці, да воззрі́нієм нань побіжда́ється вся́кий гріх і ненави́стная рознь ми́ра сего́. О преподо́бне і пречу́дне о́тче, при́зри с висоти́, іді́же в Боже́ственнім сві́те пребива́єши, і усли́ши моли́тви нас, грі́шних, і, я́ко імі́яй дерзнове́ніє ко Пресвяті́й Тро́йце, со преподо́бним Се́ргиєм і всі́ми святи́ми моли́ Влади́ку всіх, о є́же Це́рков єго́ укріпи́ти, разобще́нних соєдини́ти, расточе́нних собра́ти і в разумі́ніє і́стини всім прийти́, отврати́ти от нас пра́ведний гнів Свой і іспо́лнити даро́в Ду́ха Свята́го, любве́, ра́дости, ми́ра, долготерпі́нія, бла́гости, милосе́рдія, ві́ри, кро́тости, воздержа́нія, земно́є же стра́нствіє прейти́ нам, грі́шним, безбі́дно, в бу́дущем же ві́ці сподо́биться с тобо́ю і всі́ми святи́ми прославля́ти Пресвяту́ю Тро́йцю, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, преподо́бне о́тче наш Андре́є, о́браз Пресвяти́я Тро́йці нам дарова́вий, і тім луча́ми Триіпоста́снаго Божества́ всіх нас просвіти́вий."]}],"notes":[]},{"u":"Молитва Царственним Страстотерпцям","e":"Prayer to the Royal Passion-Bearers","secs":[{"h":"Тропар, глас 4","ps":["Днесь, благові́рнії лю́діє, сві́тло почти́м / седьмери́цю честну́ю ца́рственних страстоте́рпець, / Христо́ву єди́ну дома́шнюю Це́рков: / Никола́я і Алекса́ндру, / Алексі́я, О́льгу, Татія́ну, Марі́ю і Анастасі́ю. / Ті́ї бо, уз і страда́ній многоразли́чних не убоя́вшеся, / от богобо́рних смерть і поруга́ніє тіле́с прия́ша / і дерзнове́ніє ко Го́споду в моли́тві улучи́ша. / Сего́ ра́ди к ним с любо́вію возопії́м: / о святі́ї страстоте́рпці, / гла́су покая́нія і стена́нію наро́да на́шего воньмі́те, / зе́млю Українськую в любві́ к Правосла́вію утверді́те, / от междоусо́бния бра́ні сохрані́те, / мир ми́рові у Бо́га іспросі́те / і душа́м на́шим ве́лію ми́лость."]},{"h":"Інший тропар, глас 5","ps":["Ца́рства земна́го лише́ніє, / у́зи і страда́нія многоразли́чния / кро́тко претерпі́л єси́, / свиді́тельствовав о Христі́ да́же до сме́рти от богобо́рцев, / страстоте́рпче вели́кий Боговінча́нний царю́ Никола́ї, / сего́ ра́ди му́ченичеським вінце́м на Небесі́х, / вінча́ тя с цари́цею і ча́ди і слуги́ твої́ми Христо́с Бог, / Єго́же моли́ поми́ловати страну́ Українськую / і спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Ізбра́ннії Царе́м ца́рствующих і Го́сподем госпо́дствующих / от ро́да царе́й Українських, / благові́рнії му́ченици, / му́ки душе́вния і смерть тіле́сную за Христа́ приі́мшії / і вінці́ Небе́сними увінча́вшіїся, / к вам, я́ко покрови́телем на́шим ми́лостивим, / с любо́вію благода́рні вопіє́м: / ра́дуйтеся, ца́рственнії страстоте́рпці, / за Україну Святую пред Бо́гом усе́рднії моли́твенниці."]},{"h":"Інший кондак, глас 6","ps":["Наде́жда царя́ му́ченика / с цари́цею і ча́ди і слуги́ укріпи́, / і к Твоє́й любві́ окрили́, бу́дущий їм поко́й предвозвести́вши, / тіх моли́твами, Го́споди, поми́луй нас."]},{"h":"Молитва","ps":["О святи́й страстоте́рпче, царю́ му́чениче Нико́лає! Госпо́дь тя ізбра́ пома́занника Своєго́, во є́же ми́лостивно і пра́во суди́ти лю́дем твої́м і храни́телем Це́ркве Правосла́вния би́ти. Сего́ ра́ди со стра́хом Бо́жиїм ца́рськоє служе́ніє і о душа́х попече́ніє соверша́л єси́. Госпо́дь же, іспиту́я тя, я́ко І́ова Многострада́льнаго, попусти́ ті поноше́нія, ско́рби го́ркия, ізмі́ну, преда́тельство, бли́жніх отчужде́ніє і в душе́вних му́ках земна́го ца́рства оставле́ніє. Вся сія́ ра́ди бла́га України, я́ко ві́рний син єя́, претерпі́в і, я́ко і́стинний раб Христо́в, му́ченичеськую кончи́ну приє́м, Небе́снаго Ца́рства дости́гл єси́, іді́же наслажда́єшися Ви́шнія сла́ви у Престо́ла всіх Царя́, ку́пно со свято́ю супру́жницею твоє́ю, цари́цею Алекса́ндрою, і ца́рственними ча́ди Алексі́єм, О́льгою, Татія́ною, Марі́єю і Анастасі́єю. Ни́ні, імі́я дерзнове́ніє ве́ліє у Христа́ Царя́, моли́, да прости́ть Госпо́дь гріх отступле́нія наро́да на́шего, і пода́сть гріхо́в проще́ніє, і на вся́кую доброді́тель наста́вить нас, да стяжи́м смире́ніє, кро́тость і любо́в і сподо́бимся Небе́сного Ца́рствія, іді́же ку́пно с тобо́ю і всі́ми святи́ми новому́ченики і іспові́дники Українськими просла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм вас, / святі́ї ца́рственнії страстоте́рпці, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Молитва преподобному Афанасію Афонському","e":"Prayer to St Athanasius of Athos","secs":[{"h":"Тропар, глас 3","ps":["Є́же во пло́ті житію́ твоєму́ / удиви́шася а́нгельстії чи́ни, / ка́ко с ті́лом к неви́димим спле́тенієм / ізше́л єси́, присносла́вне, / і уязви́л єси́ де́монськия полки́. / Отону́дуже, Афана́сіє, / Христо́с тебі́ воздаде́ бога́тими дарова́ньми: // сего́ ра́ди, о́тче, моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко невеще́ственних суще́ств зри́теля ізря́дна, / і ді́ятельна сказа́теля всеї́стинна, взива́єть тя ста́до твоє́, Богоглаго́льниче: / не оскуді́й моля́ о рабі́х твої́х, / ізба́витися напа́стей і обхожде́ній, вопію́щим ті: // ра́дуйся, о́тче Афана́сіє."]},{"h":"Молитва","ps":["Преподо́бне о́тче Афана́сіє, ізря́дний уго́дниче Христо́в і вели́кий Афо́нський чудотво́рче! Во дні земна́го житія́ твоєго́ мно́гія на путь пра́вий наста́вивий і в Ца́рствіє Небе́сноє му́дре руководи́вий, ско́рбния уті́шивий, па́дающим пода́вий ру́ку по́мощі і всім любе́зен, ми́лостив і сострада́телен оте́ць би́вий, ти ни́ні, в Небе́сній пребива́я сві́тлости, найпа́че умно́жавши любо́в твою́ к нам, немощни́м, в мо́рі жите́йстім разли́чіє бе́дствующим, іскуша́ємим ду́хом зло́би і страстьми́ свої́ми, вою́ющими на дух. Сего́ ра́ди смире́нно мо́лим тя, святи́й о́тче: по да́нній тебі́ от Бо́га благода́ті помози́ нам твори́ти во́лю Госпо́дню в простоті́ се́рдця і смире́нії, іскуше́нія же вра́жия побіди́ти і свирі́поє страсте́й мо́ре ізсуши́ти, да та́ко немо́кренно пре́йдем жите́йськую пучи́ну і предста́тельством твої́м ко Го́споду сподо́бимся дости́гнути обітова́ннаго нам Ца́рствія Небе́снаго, сла́в'яще Безнача́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Антонію, ігумену Києво-Печерському","e":"Prayer to St Anthony, Abbot of the Kyiv Caves","secs":[{"h":"Тропар, глас 4","ps":["От мирська́го м'яте́жа ісше́д, / отверже́нієм же ми́ра єва́нгельськи Христу́ послі́довал єси́ / і равноа́нгельноє житіє́ пожи́в, / в ти́хоє приста́нище Святи́я Гори́ Афо́на дости́гл єси́. / Отону́дуже благослове́нієм отце́во в го́ру Ки́єва прише́д, / і та́мо трудолю́бно жизнь соверши́в, / оте́чество твоє́ просвіти́л єси́, / і мно́жеству мона́шествующих стезю́ веду́щую к Небе́сному Ца́рствію показа́в, / Христу́ сія́ приве́л єси́: / Єго́же моли́, Анто́ніє преподо́бне, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Возложи́в себе́ Бо́гу, па́че всіх возлю́бленному от ю́ности, преподо́бне, / Тому́ от всея́ душі́ любо́вію послі́довал єси́; / ми́ра же тлі́нная нівочто́же вміни́в, в землі́ пеще́ру соді́лал єси́, / і в ней до́брі проти́ву неви́димаго врага́ ко́зней подвиза́вся, / я́ко світоза́рноє со́лнце во вся конці́ землі́ возсія́л єси́, / отону́дуже веселя́ся преше́л єси́ к Небе́сним Черто́гом. / І ни́ні со А́нгели Влади́чню Престо́лу предстоя́, / помина́й нас, чту́щих па́м'ять твою́, да зове́м ті: // ра́дуйся, Анто́ніє, о́тче наш."]},{"h":"Інший кондак, глас 8","ps":["В ми́рі я́ко А́нгел, о́тче, пожи́л єси́, / в землі́ пеще́ру себі́ соді́лав, / в не́йже до́брі подвиза́вся проти́ву неви́димаго врага́ ко́зней, / і отту́ду, веселя́ся, преше́л єси́ к Небе́сним черто́гом. / Помина́й нас, чту́щих па́м'ять твою́, да зове́м ті: / ра́дуйся, Анто́ніє, о́тче наш."]},{"h":"Молитва","ps":["О до́брий наш па́стирю наста́вниче, приснопомина́ємий і́ноков українських первонача́льниче, преподо́бне і богоно́сне о́тче наш Анто́ніє! Ти го́ре на Небесі́ пребива́єши, ми ни́зу на землі́, удале́ни су́ще от тебе́ не толи́ко мі́стом, коли́ко гріхо́вною нечистото́ю на́шею; оба́че па́м'ятующе оте́чеськую любо́в твою́ к лю́дем, ті сро́дним, припа́даєм і мо́лимтися с умиле́нієм і ві́рою: помози́ нам, грі́шним, покая́нієм очи́ститися і досто́йним би́ти поми́лованія і проще́нія от Го́спода і Созда́теля на́шего. Умоли́ Єго́ бла́гость дарова́ти нам вели́кия і бога́тия ми́лости: землі́ плодоно́сіє, возду́ха благорастворе́ніє, мир глубо́к, братолю́біє і́скреннєє, благоче́стіє нелицемі́рноє, жите́йських потре́б дово́льство, і да не во зло обрати́м блага́я, да́руємая нам от щедротода́тельния Єго́ десни́ці, но во сла́ву І́мене Єго́ свята́го і во спасе́ніє на́ше. Соблюди́, чудотво́рче святи́й, благомо́щними твої́ми моли́твами українськия гра́ди, оби́тель твою́ і всю страну́ Правосла́вно Українськую невреди́ми от вся́каго зла, і вся лю́ди, жи́тельствующия в оби́телі твоє́й і на поклоне́ніє в ню приходя́щия, осіни́ Небе́сним твої́м благослове́нієм, і в ско́рбіх, біда́х і болі́зніх утіше́ніє, ізбавле́ніє і ісціле́ніє їм пода́ждь, да благода́рно сла́вим, хва́лим і велича́єм просла́вльшаго тя Го́спода, чрез тебі́ ди́вно благоді́тельствующаго нам, Безнача́льного Отця́, Єдиноро́днаго Єго́ Си́на і Єдиносу́щнаго Єго́ Ду́ха, Тро́йцю Живонача́льную і Неразді́льную, і твоє́ свято́є заступле́ніє во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва рівноапостольному Володимиру, великому князю, у святому хрещенні Василію","e":"Prayer to the Equal-to-the-Apostles Volodymyr, Grand Prince, in Holy Baptism Basil","secs":[{"h":"Тропар, глас 4","ps":["Уподо́бился єси́ купцю́, і́щущему до́браго би́сера, / славнодержа́вний Влади́мире, / на висоті́ стола́ сідя́ ма́тере градо́в, богоспаса́ємаго Ки́єва: / іспиту́я же і посила́я к Ца́рскому гра́ду / уві́діти правосла́вную ві́ру, / обрі́л єси́ бесці́нний би́сер - Христа́, / ізбра́вшаго тя я́ко втора́го Па́вла, / і оттря́сшаго сліпоту́ во святі́й купі́лі, / душе́вную вку́пі і тіле́сную. / Ті́мже пра́зднуєм твоє́ успе́ніє, / лю́діє твої́ су́ще: // моли́ спасти́ся держа́ви твоєя́ Українськия нача́льником і мно́жеству владо́мих."]},{"h":"Інший тропар, глас 1","ps":["Я́ко нача́льнику Креще́нія / і ко́реню ві́ри Боже́ственния, / і́долов разруши́телю, / блаже́нне кня́же Васи́ліє равноапо́стольне, вопіє́м ті: / сла́ва вразу́мльшему тя Христу́ Бо́гу, / сла́ва освяти́вшему тя Креще́нієм Свої́м, // сла́ва просвіти́вшему тобо́ю всю страну́ Українськую."]},{"h":"Інший тропар, глас 8","ps":["Правові́рія наста́вниче / і всієї України просвіти́телю, / благочести́вий вели́кий кня́же Влади́мире, / святи́м Креще́нієм всіх просвіти́л єси́ / і це́ркві мно́гі сла́вни украси́л єси́, / о прему́дрі Васи́ліє, // Христа́ Бо́га моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Подо́бствовав вели́кому апо́столу Па́влу в сіди́нах, всесла́вне Влади́мире, / вся я́ко младе́нчеськая мудрова́нія, я́же о і́доліх тща́нія оста́вль, / я́ко муж соверше́нний украси́лся єси́ Боже́ственнаго Креще́нія багряни́цею. / І ни́ні Спа́су Христу́ во весе́лії предстоя́, // моли́ спасти́ся держа́ви Українськия нача́льником і мно́жеству владо́мих."]},{"h":"Інший кондак, глас 8","ps":["Ізря́дному воєво́ді і правові́рному, / благода́рственная воспису́єть ті вся Україна, Васи́ліє, іму́щи тя нача́льника і засту́пника, / я́ко ізба́вил єси́ нас от вся́кия скве́рни і ле́сти, ті́мже ті вопіє́м: // ра́дуйся, вели́кий кня́же Влади́мире преблаже́нне."]},{"h":"Інший кондак, глас 4","ps":["Оте́чеську пре́лесть, і́доли, я́ко су́єтни, отве́рг, / Христа́, всіх і́стиннаго Бо́га, Царя́ і Благода́теля, позна́л єси́. / Ті́мже і лю́ди, ізря́дни Тому́, святи́м Креще́нієм просвіти́л єси́, / пресла́вне Влади́мире. / Сего́ ра́ди почита́єм тя, / я́ко Тро́йце служи́теля, // Христа́ моли́ дарова́ти нам ве́лію ми́лость."]},{"h":"Молитва перша","ps":["О вели́кий і пресла́вний уго́дниче Бо́жий, богоізбра́нний і богопросла́вленний, равноапостольний кня́же Влади́мире, свято́є і великоде́йственноє ору́діє всеблага́го Про́мисла о спасе́нії наро́да Українськаго! Ти отри́нул єси́ злові́ріє і нече́стіє язи́чеськоє, уві́ровал єси́ во Єди́наго І́стиннаго Триіпоста́снаго Бо́га і, восприя́в свято́є Креще́ніє, просвіти́л єси́ сві́том Боже́ственной ві́ри і благоче́стія страну́ Українськую. Сла́в'яще у́бо благодаря́ще Премилосе́рдаго Творця́ і Спаси́теля на́шего, сла́вим і благодари́м тя, вели́кий па́стирю і о́тче наш, я́ко тобо́ю позна́хом спаси́тельную ві́ру Христо́ву і крести́хомся во І́м'я Пресвяти́я і Пребоже́ственния Тро́йці, то́ю же ві́рою ізба́вихомся от пра́веднаго осужде́нія Бо́жия, ві́чнаго ра́бства дия́воля і а́дова мучи́тельства, то́ю ві́рою восприя́хом благода́ть всиновле́нія Бо́гу і наде́жду наслі́дованія Небе́снаго блаже́нства. Ти єси́ пе́рвійший наш вождь к Нача́льнику і Соверши́телю на́шего ве́чного спасе́нія, Го́споду Ісу́су Христу́, ти єси́ ближа́йший предста́тель пред Престо́лом Царя́ ца́рствующих і те́плий моли́твенник і хода́тай о страні́ на́шей і о всіх лю́діх, ти єси́ пе́рвійший вино́вник благослове́ній і ми́лостей Бо́жиїх, почива́ющих на нас. І что єще́ рече́м? Не мо́жеть язи́к наш ізобрази́ти вели́чіє і висоту́ благодія́ній твої́х, ізлія́нних на нас недосто́йних. Но, о неразу́мія і осліпле́нія на́шего! Приє́мше толи́кая благодія́нія, ні во что же вміни́хом я і отщети́хом'я спаси́тельних плодо́в твої́х. Оми́вшеся бо от гріха́ в купі́лі Креще́нія і обле́кшеся в оде́жду чистоти́ і неви́нности, оскверни́хом сію́ благода́тную оде́жду сту́деними дія́нії і помишле́нії на́шими. Отре́кшеся сатани́ і а́нгелов єго́, па́ки порабоща́ємся єму́, служа́ще і́долом страсте́й на́ших, ми́ру, пло́ті і злим оби́чаєм ві́ка. Сочета́вшеся Христу́, ви́ну оскорбля́єм Єго́ беззако́нії на́шими, многообра́зними я́звами го́рдості, за́висти, зло́би, злосло́вія, невоздержа́нія і презо́рства ко Святі́й Це́ркві. Приліпи́хомся всеці́ло к су́єтним бла́гом, а́ки мня́ще во ві́ки пребива́ти на землі́, не помишля́єм о Не́бі, о душе́, о сме́рті, о суді́, о несконча́ємій ві́чності. Сего́ ра́ди воздвиза́єм на ся пра́ведний гнів і осужде́ніє Бо́жиє, ку́пно же оскорбля́єм і преогорчева́єм твою́ о́тчую любо́в і попече́ніє о нас, ти бо просвіти́л єси́ нас святи́м Креще́нієм, во є́же спосо́бствовати нам к получе́нію Небе́снаго блаже́нства і земна́го благоде́нствія, ми же неразу́мнії злим проізволе́нієм на́шим са́мі себе́ подверга́єм а́довим му́кам і вре́менним бе́дствієм! Но, о всеблаги́й о́тче і просвіти́телю наш, ми́лостив бу́ди к на́шим не́мощем, долготерпіли́в ко гріхо́м і непра́вдам на́шим, умоли́ Премилосе́рдаго Царя́ Небе́снаго, да не прогні́вається на ни зіло́ і не погуби́ть нас со беззако́ньми на́шими, но да поми́луєть і спасе́ть нас, і́миже вість судьба́ми. Да всади́ть в сердця́ на́ша спаси́тельний страх Свой, да просвіти́ть Своє́ю благода́тію ум наш, во є́же узрі́ти нам бе́здну поги́белі, в ню́же стремі́мся, оста́вити стезі́ нече́стія і заблужде́ній, обрати́тися же на путь спасе́нія і і́стини, неукло́нно ісполня́ти за́повіді Бо́жії і уста́ви Святи́я Це́ркве. Моли́, благосе́рде, Человіколю́бця Бо́га, да яви́ть нам вели́кую ми́лость Свою́, да ізба́вить нас от наше́ствія іноплеме́нников, от вну́тренних нестроє́ній, м'яте́жей і раздо́ров, от гла́да, смертоно́сних болі́зней, і от вся́каго зла, да пода́сть нам благорастворе́ніє возду́ха і плодоно́сіє землі́, да сохрани́ть в су́дящих і нача́льствующих пра́вду і ми́лость, да дасть духо́вним па́стирем непоро́чность житія́ і ре́вность о спасе́нії пасо́мих, всім же лю́дем усе́рдіє в ісполне́нії свої́х об'я́занностей, взаї́мную любо́в і єдиноми́сліє, стремле́ніє ко бла́гу оте́чества і Святи́я Це́ркве. Да распространи́ть світ спаси́тельния ві́ри в страні́ на́шей, во всіх конці́х єя́, да обрати́ть к правові́рію неві́рующих, да упраздни́ть вся є́ресі і раско́ли, да, та́ко пожи́вше в ми́рі на землі́, сподо́бимся с тобо́ю ві́чнаго блаже́нства, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Ка́ко похва́лим тебі́, в земни́х влади́ках прему́жественний, Влади́мире? Ка́ко ті благодаре́ніє воздади́м, я́ко тобо́ю позна́хом Го́спода і ле́сти і́дольськия ізби́хом, я́ко твої́м повелі́нієм по всей землі́ Христо́с сла́виться? Ка́ко ві́ровал єси́? Ка́ко взиска́л єси́ Христа́? Пові́ждь нам, рабо́м твої́м, отку́ду ті припахну́ воня́ Свята́го Ду́ха? Не ви́діл єси́ Христа́, ні ходи́л єси́ по Нем, ка́ко учени́к Єго́ обрі́теся? Не ви́діл єси́ апо́стола, прише́дша в зе́млю твою́, не ви́діл бі́си ізгоня́юща І́менем Христо́вим, боля́щих ісціля́юща, ме́ртвих воскреша́юща. Ди́вноє чу́до! Іні́ї ца́ріє і власти́теліє, ви́дяще вся сія́, бива́юща от святи́х муж, не ві́роваша, но па́че на стра́сті і му́ки преда́ша їх, ти же, о блаже́нне, не ви́дя і не сли́ша всіх сих, прите́кл єси́ ко Христу́, разумі́в, я́ко Єди́н єсть Творе́ць неви́димим і ви́димим, Небе́сним і земни́м, і я́ко посла́ в мир, на́шего ра́ди спасе́нія, Возлю́бленнаго Своєго́ Си́на. І сія́ поми́слив, вшел єси́ во святу́ю купі́ль.","І ни́ні, проте́кшим ти́сящи лі́том от Креще́нія Русі́, при́зри на зе́млю твою́ виждь ча́да твоя́. Виждь лю́ди твоя́, ка́ко живу́ть, ка́ко храни́мі суть Го́сподем, ка́ко благові́ріє храня́ть по преда́нію твоєму́, ка́ко сла́в'ять Христа́, ка́ко покланя́ються І́мені Єго́. Виждь і гра́ди, вели́чеством сія́ющия, виждь це́ркві цвіту́щия, виждь христия́нство расту́щеє, виждь і град твой Ки́єв, толи́кими уго́дники Бо́жиїми, во нетлі́нії почива́ющими, блиста́ющийся, і фимія́мом облагоуха́єм, і хвала́ми і боже́ственними пі́нії святи́ми оглаша́єм. І сія́ вся ви́дів, возра́дуйся і возвесели́ся і похвали́ Блага́го Бо́га, всім сим Строї́теля.","Ви́дя, я́ко твоє́ ві́рноє сі́яніє твої́м хода́тайством і заступле́нієм не ізсуше́но бисть зно́єм неві́рія, но дожде́м Бо́жия поспіше́нія располо́жено бисть многопло́дне, ра́дуйся ду́хом, во влади́ках апо́столе, не ме́ртвая тілеса́ воскреси́вий, но душе́ю ни, ме́ртвия, воскреси́в! Ра́дуйся, уті́шителю наш і наста́вниче благові́рія! Ти бі, о честна́я главо́, наги́м одія́ніє, а́лчним корми́тель, жа́ждущим утро́б охлажде́ніє, вдови́цям помо́щник, стра́нним поко́їще, оби́димим засту́пник, убо́гим обогаще́ніє.","Сим благи́м діло́м на Небесі́х возме́здіє приє́мля і зрі́нія сла́дкаго лиця́ Бо́жия насища́яся, не преста́й моля́ся о землі́ твоє́й і о ча́діх, в них же благові́рно влади́чествова, да сла́виться в землі́ на́шей ви́ну правові́ріє і да не оста́вить нас Госпо́дь, а́ще і єще́ блужда́єм, толи́ким віко́м проте́кшим, а́ще і єще́ согріша́єм Го́споду і Влади́ці на́шему, а́ки новоку́пленнії раби́, во всем неугодя́ще господи́ну своєму́. К тебі́ ру́ки на́ша воздіва́єм і мо́лим тя: помоли́ся Влади́ці всіх, да продли́ть, доне́ліже стої́ть мир, ми́лость Свою́ на оте́чествії на́шем і лю́діх Свої́х, ра́тния прогоня́я, мир утвержда́я, глад угобза́я, гра́ди разселя́я, Це́рков Свою́ возраща́я, достоя́ніє Своє́ соблюда́я, му́жи, і жени́, і младе́нці спаса́я, да ми́лостію Єго́ носи́ми, в єдине́нії ві́ри вку́пі ве́село і ра́достно сла́вим Го́спода на́шего Ісу́са Христа́, со Отце́м і со Пресвяти́м Ду́хом, Тро́йцю Неразді́льну Єдинобоже́ственну, ца́рствующу на Небесі́х і на землі́, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь"]},{"h":"Молитва третя","ps":["О вели́кий уго́дниче Бо́жий, равноапостольний кня́же Влади́мире! При́зри на не́мощі на́ші і умоли́ Премилосе́рдаго Царя́ Небе́снаго, да не прогні́вається на ни зіло́ і да не погуби́ть нас со беззако́ньми на́шими, но да поми́луєть і спасе́ть нас по ми́лості Своє́й, да всади́ть в сердця́ на́ша покая́ніє і спаси́тельний страх Бо́жий, да просвіти́ть Своє́ю благода́тію ум наш, во є́же оста́вити нам стезі́ нече́стія і на путь спасе́нія обрати́тися, неукло́нно же за́повіді Бо́жия твори́ти і уста́ви Святи́я Це́ркве соблюда́ти. Моли́, благосе́рде, Человіколю́бця Бо́га, да яви́ть нам вели́кую ми́лость Свою́: да ізба́вить нас от смертоно́сних болі́зней і от вся́каго зла, да сохрани́ть і спасе́ть рабо́в Бо́жиїх (імена́) от всіх ко́зней і наві́тов вра́жиїх і да все ми сподо́бимся с тобо́ю ві́чнаго блаже́нства, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й равноапостольний кня́же Влади́мире, / і чтим святу́ю па́м'ять твою́, / і́доли попра́вшаго // і всю Українськую зе́млю святи́м Креще́нієм просвіти́вшаго."]}],"notes":[]},{"u":"Молитва пророку Іллі","e":"Prayer to the Prophet Elijah","secs":[{"h":"Тропар, глас 4","ps":["Во пло́ті А́нгел, / проро́ков основа́ніє, / втори́й Предте́ча прише́ствія Христо́ва Ілия́ сла́вний, / сви́ше посла́вий Єлисе́єві благода́ть, / неду́ги отгоня́ти / і прокаже́нния очища́ти, // ті́мже і почита́ющим єго́ то́чить ісціле́нія."]},{"h":"Кондак, глас 2","ps":["Проро́че і прови́дче вели́ких діл Бо́га на́шего, / Іліє́ великоімени́те, / віща́нієм твої́м уста́вивий водото́чния о́блаки, // моли́ о нас єди́наго Человіколю́бця."]},{"h":"Молитва перша","ps":["О прехва́льний і пречу́дний проро́че Бо́жий Іліє́, просія́вий на землі́ равноа́нгельським житіє́м твої́м, пла́меннейшею ре́вностію по Го́споду Бо́гу Вседержи́телю, єще́ же зна́менії і чудеси́ пресла́вними, та́же по кра́йнему благоволе́нію к тебі́ Бо́жию преєсте́ственно восхище́нний на о́гненній колесни́це с пло́тію твоє́ю на не́бо, сподо́бльшійся бесі́довати с преобрази́вшимся на Фаво́рі Спаси́телем ми́ра, і ни́ні в ра́йських селе́ніїх непреста́нно пребива́яй і предстоя́й Престо́лу Небе́сного Царя́! Усли́ши нас, грі́шних і непотре́бних, в час сей предстоя́щих пред свято́ю твоє́ю іко́ною і усе́рдно прибіга́ющих ко хода́тайству твоєму́. Моли́ о нас Человіколю́бця Бо́га, да пода́сть нам дух покая́нія і сокруше́нія о грісі́х на́ших і всеси́льною Своє́ю благода́тію да помо́жеть нам оста́вити путі́ нече́стія, преспіва́ти же во вся́ком ді́лі бла́зі, да укріпи́ть нас в борбі́ со страстьми́ і похотьми́ на́шими, да всади́ть в сердця́ на́ша дух смире́нія і кро́тости, дух братолю́бія і незло́бія, дух терпі́нія і цілому́дрія, дух ре́вности к сла́ві Бо́жієй і о спасе́нії своє́м і бли́жніх до́броє попече́ніє. Упраздни́ моли́твами твої́ми, проро́че, зли́я оби́чаї ми́ра, па́че же поги́бельний і тлетво́рний дух ві́ка сего́, заража́ющий христия́нський род неуваже́нієм к Боже́ственній Правосла́вній ві́рі, к уста́вом Святи́я Це́ркве і к за́повідем Госпо́днім, непочте́нієм к роди́телем і власте́м предержа́щим, і низверга́ющий люде́й в бе́здну нече́стія, развраще́нія і поги́белі. Отврати́ от нас, пречу́дне проро́че, предста́тельством твої́м пра́ведний гнів Бо́жий і ізба́ви вся гра́ди і ве́сі оте́чества на́шего от бездо́ждія і гла́да, от стра́шних бур і землетрясе́ній, от смертоно́сних язв і болі́зней, от наше́ствія враго́в і междоусо́бной бра́ні. Укріпи́ твої́ми моли́твами, пресла́вне, предержа́щия вла́сті на́ша во вели́цім і многотру́днем по́двизі народоправле́нія, благопоспі́шествуй їм во всіх благи́х дія́ніїх і начина́ніїх к водворе́нію ми́ра і пра́вди в страні́ на́шей. Посо́бствуй христолюби́вому во́їнству во бранеіх со врага́ми на́шими. Іспроси́, проро́че Бо́жий, от Го́спода па́стирем на́шим святу́ю ре́вность по Бо́гу, серде́чноє попече́ніє о спасе́нії пасо́мих, му́дрость во уче́нії і управле́нії, благоче́стіє і крі́пость во іскуше́ніїх, судія́м іспроси́ нелицеприя́тіє і безкори́стіє, правоту́ і сострада́ніє к оби́димим, всім нача́льствующим попече́ніє о подчине́нних, ми́лость і правосу́діє, подчине́нним же поко́рность і о послуша́нії своє́м раче́ніє. Да та́ко в ми́рі і благоче́стії пожи́вше в сем ві́ці, сподо́бимся прича́стія ві́чних благ в Ца́рствії Го́спода і Спа́са на́шего Ісу́са Христа́, Єму́же подоба́єть честь і поклоне́ніє со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий і пресла́вний проро́че Бо́жий Іліє́, ре́вности ра́ди твоєя́ по сла́ві Го́спода Бо́га Вседержи́теля не терпі́вий зрі́ти ідолослуже́нія і нече́стія сино́в Ізра́їлевих, облича́вий законопресту́пного царя́ Аха́ва, і в наказа́ніє тіх триле́тній глад на зе́млю Ізра́їлеву моли́твою твоє́ю от Го́спода іспроси́вий, да, отве́ргше ме́рзькия і́доли і отсту́пльше от непра́вд і беззако́ній, обрати́ться ко Єди́ному І́стинному Бо́гу і ісполне́нію святи́х Єго́ за́повідей, вдови́цю Саре́птськую в гла́ді пречу́дно препита́вий і си́на єя́ уме́рша моли́твою твоє́ю воскреси́вий, по проше́ствії же пронарече́ннаго вре́мене гла́да, собра́нний на го́ру Карми́льськую наро́д ізра́їльський в богоотсту́пстві і нече́стії укори́вий, та́же огнь моли́твою на же́ртву твою́ с небесе́ іспроси́вий, і чу́дом сам Ізра́їля ко Го́споду обрати́вий, сту́дния же проро́ки Ваа́лови посрами́вий і умертви́вий, по сих же моли́твою па́ки не́бо разріши́вши і оби́льний дождь на зе́млю іспроси́вий, і лю́ди Ізра́їлеви возвесели́вий! К тебі́, преди́вний уго́дниче Бо́жий, усе́рдно прибіга́єм, грі́шнії і смире́нії, томи́ми бездо́ждієм і зно́єм; іспові́дуєм, я́ко недосто́йни єсьми́ ми́лості і благодія́ній Бо́жиїх, досто́йні же па́че лю́тих преще́ній гні́ва Єго́, ско́рби же і ну́жди, і вся́ких зол і болі́зней. Не бо ходи́хом в стра́сі Бо́жії і в путеіх за́повідей Єго́, но в по́хотіх развраще́нних серде́ць на́ших і вся́кий вид гріха́ безчи́сленно сотвори́хом; беззако́нія на́ша превзидо́ша главу́ на́шу, і ні́сми досто́йні яви́тися пред лице́ Бо́жиє і зрі́ти на не́бо. Іспові́дуєм, я́ко і ми, я́коже дре́вній Ізра́їль, отступи́хом от Го́спода Бо́га на́шего, а́ще не ві́рою, то беззако́ньми на́шими, і а́ще не поклоня́ємся Ваа́лу і други́м ме́рзьким і́долом, то раболе́пствуєм страсте́м і по́хотем на́шим, слу́жаще і́долу чревоуго́дія і сластолю́бія, і́долу користолю́бія і честолю́бія, і́долу го́рдості і тщесла́вія, і вслід хо́дим богопроти́вним іноплеме́нним оби́чаєм і поги́бельному ду́ху вре́мене. Іспові́дуєм, я́ко сего́ ра́ди заключи́ся не́бо і сотвори́ся а́ки мі́дяно, я́ко заключи́ся се́рдце на́ше от милосе́рдія і і́стинния любве́ ко бли́жнему; сего́ ра́ди отверді́ земля́ і соді́лася безпло́дна, я́ко не прино́сим Го́споду на́шему плодо́в до́брих діл; сего́ ра́ди ність дождя́ і роси́, я́ко не і́мами слез умиле́нія і животво́рния роси́ Богоми́слія; сего́ ра́ди ув'яде́ всяк злак і трава́ се́льная, я́ко і́зсеше в нас вся́коє благо́є чу́вство; сего́ ра́ди омрачи́ся возду́х, я́ко ум наш омрачи́ся сту́дними помишле́ньми і се́рдце на́ше оскверни́ся беззако́нними похоті́ньми. Іспові́дуєм, я́ко і тебі́, проро́че Бо́жий, проси́ти ми недосто́йни єсьми́. Ти бо, подобостра́стен бив нам челові́к, А́нгелом в житії́ твоє́м уподо́бился єси́ і, а́ки безпло́тний, на не́бо восхище́н єси́; ми же сту́дними по́мисли і дія́ньми на́шими безслове́сним ското́м уподо́бихомся, і ду́шу на́шу я́ко плоть сотвори́хом. Ти посто́м і бді́нієм удиви́л єси́ А́нгелов і челові́ков, ми же, предаю́щеся невоздержа́нію і сластолю́бію, ското́м несми́сленним уподобля́ємся. Ти презі́льною ре́вностію о сла́ві Бо́жієй ви́ну горі́л єси́, ми же небреже́м о сла́ві на́шего Творця́ і Го́спода, і стиді́мся іспові́довати достопокланя́ємоє І́м'я Єго́. Ти нече́стіє і зли́я оби́чаї іскореня́л єси́, ми же ра́бствуєм ду́ху ві́ка сего́, поставля́юще богопроти́вния оби́чаї ми́ра па́че за́повідей Бо́жиїх і уста́вов святи́я Це́ркве. І кий гріх і непра́вду не сотвори́хом ми окая́нії? Істощи́хом беззако́ньми на́шими долготерпі́ніє Бо́жиє. Ті́мже правосу́дний Госпо́дь прогні́вася на нас, і во гні́ві Своє́м наказа́ нас. Оба́че ві́дуще ве́ліє дерзнове́ніє твоє́ пред Го́сподем і наді́ющеся на любо́в твою́ к ро́ду челові́чеському, дерза́єм моли́ти тя, прехва́льне проро́че: ми́лостив бу́ди к нам, недосто́йним і непотре́бним, умоли́ Великодарови́таго і Всеще́драго Бо́га, да не до конця́ прогні́вається на ни і не погуби́ть нас со беззако́ньми на́шими, но да ниспосле́ть на жа́ждущую і ізсо́хшую зе́млю дождь оби́льний і ми́рний, да да́руєть єй плодоно́сіє і благорастворе́ніє возду́ха; преклони́ ді́йственним твої́м хода́тайством на ми́лость Царя́ Небе́снаго, а́ще не ра́ди нас грі́шних і скве́рних, но ра́ди ізбра́нних рабо́в Єго́, не преклони́вших колі́на своя́ пред Ваа́лом ми́ра сего́, ра́ди незло́бивих і несми́сленних младе́нцев, ра́ди безслове́сних ското́в і птиць небе́сних, стра́ждущих за на́ша беззако́нія і істаєва́ющих от гла́да, зно́я і жа́жди. Іспроси́ нам твої́ми благоприя́тними моли́твами от Го́спода дух покая́нія і серде́чнаго умиле́нія, дух кро́тости і воздержа́нія, дух любве́ і терпі́нія, дух стра́ха Бо́жия і благоче́стія, да та́ко, возврати́вшеся от стезе́й нече́стія на пра́вий путь доброді́телі, хо́дим во сві́ті за́повідей Бо́жиїх і дости́гнем обітова́нних нам благи́х, благоволе́нієм Безнача́льного Бо́га Отця́, человіколю́бієм Єдиноро́днаго Си́на Єго́ і благода́тію Всесвята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О святи́й проро́че Бо́жий Іліє́, моли́ о нас Человіколю́бця Бо́га, да пода́сть нам, раба́м Бо́жиїм (імена́), дух покая́нія і сокруше́нія о грісі́х на́ших, і всеси́льною Своє́ю благода́тію да помо́жеть нам путі́ нече́стія оста́вити, преспіва́ти же во вся́ком ді́лі бла́зі, і в борбі́ со страстьми́ і похотьми́ на́шими да укріпи́ть нас; да всади́ть в сердця́ на́ша дух смире́нія і кро́тости, дух братолю́бія і незло́бія, дух терпі́нія і цілому́дрія, дух ре́вности ко сла́ві Бо́жієй і о спасе́нії своє́м і бли́жніх до́броє попече́ніє. Отврати́ от нас предста́тельством твої́м пра́ведний гнів Бо́жий, да та́ко в ми́рі і благоче́стії пожи́вше в сем ві́ці, сподо́бимся прича́стія ві́чних благ во Ца́рствії Го́спода і Спа́са на́шего Ісу́са Христа́, Єму́же подоба́єть честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і Пресвяти́м Ду́хом, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й сла́вний проро́че Бо́жий Іліє́, / і чтим, є́же на Небеса́ / на колесни́ці о́гненній, // пресла́вноє восхожде́ніє твоє́."]},{"h":"Інше величання","ps":["Велича́єм тя, / проро́че Іліє́ сла́вне, / і почита́єм, є́же на Небеса́ с пло́тію, // о́гненноє восхожде́ніє твоє́."]},{"h":"Інше величання","ps":["Велича́єм тя, / проро́че і предте́че прише́ствія Госпо́дня, Іліє́ сла́вний, / і чтим, є́же на Небеса́ с пло́тію, // о́гненноє восхожде́ніє твоє́."]}],"notes":[]},{"u":"Молитва святителю Тихону, єпископу Воронезькому, Задонському чудотворцю","e":"Prayer to St Tikhon, Bishop of Voronezh, Wonderworker of Zadonsk","secs":[{"h":"Тропар, глас 8","ps":["От ю́ности возлюби́л єси́ Христа́, блаже́нне, / о́браз всім бил єси́ сло́вом, житіє́м, любо́вію, / ду́хом, ві́рою, чистото́ю і смире́нієм. / Ті́мже і всели́лся єси́ в небе́сния оби́телі, / іді́же предстоя́ Престо́лу Пресвяти́я Тро́йці, // моли́, святи́телю Ти́хоне, спасти́ся душа́м на́шим."]},{"h":"Інший тропар, глас 4","ps":["Правосла́вія наста́вниче, благоче́стія учи́телю, / покая́нія пропові́дниче, Златоу́стаго ревни́телю, / па́стирю предо́брий, / но́вий України світи́льниче і чудотво́рче, / па́ству твою́ до́брі упа́сл єси́ / і писа́ньми твої́ми вся ни наста́вил єси́, / ті́мже вінце́м нетлі́нія / укра́шен от Пастиренача́льника, / моли́ Єго́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Апо́столов преє́мниче, / святи́телей украше́ніє, / Правосла́вния Це́ркве учи́телю, / Влади́ці всіх моли́ся, / мир вселе́нной дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Молитва перша","ps":["О вели́кий святи́телю Христо́в і чудотво́рче Ти́хоне! Усли́ши нас, многогрі́шних, прибіга́ющих к тебі́ с те́плою ві́рою і умиле́нною мольбо́ю. Зане́ ві́ми ангелоподо́бноє благо́є житіє́ твоє́ на землі́, прославля́єм во всем твою́ ми́лость, благогове́єм пред висото́ю твої́х христия́нських доброді́телей, і́миже во благовре́менії преуспіва́л єси́ к сла́ві ди́вно просла́вившаго тя Го́спода. Ти воі́стину бил єси́ до́брий па́стир слове́снаго ста́да Христо́ва, та́їн Бо́жиїх до́бльственний строї́тель, сто́лпе і украше́ніє Це́ркве Правосла́вния, Український Златоу́сте, язи́чеських оби́чаєв крі́пкий іскорени́телю, преіску́сний істолкова́телю Єва́нгельськаго уче́нія, ре́вностний блюсти́телю свяще́нних оте́чеських преда́ній, люби́телю мона́шеськаго безмо́лвія, богодухнове́нний собира́телю сокро́вища духо́вния му́дрости от ви́димаго ми́ра сего́, прему́дро Бо́гом сотворе́ннаго. Ти, я́ко ізбра́нний сосу́д благода́ті, нелі́ностно поуча́л єси́ всіх жа́ждавших спасе́нія сло́вом, житіє́м, любо́вію, ду́хом, ві́рою, чистото́ю і смире́нієм. Ти бил єси́ ми́лостивий защи́тник си́рих, призрі́ніє вдови́ць, убо́гих і всім су́щим в біда́х і напа́стіх ско́рий уті́шитель, і ни́ні ві́ми, я́ко предстої́ши пред лице́м Го́спода сла́ви і імі́єши ве́ліє к Нему́ дерзнове́ніє; сего́ ра́ди к тебі́, о́тче, прибіга́єм і усе́рдно мо́лим тя: бу́ди о всіх нас хода́тай у Престо́ла Всеви́шняго. Да прости́ть Он беззако́нія і непра́вди на́ша; да просвіти́ть омраче́нний суєто́ю ум наш і напра́вить к і́стинному сві́ту богопозна́нія; да сохрани́ть сла́бия сердця́ на́ша от любостра́стних гріхо́вних увлече́ній і тлетво́рнаго мудрова́нія ві́ка сего́; да пода́сть землі́ благовре́менноє ороше́ніє дожде́й і плодоноше́ніє і вся нам поле́зная, я́же к животу́ вре́менному і ві́чному, да всі притека́ющиє к ра́ці нетлі́нних моще́й твої́х обрету́ть мир, любо́в і безм'яте́жіє. Це́ркві на́шей іспроси́ у Небе́снаго Царя́ ми́лость, благоде́нствіє, спасе́ніє, на враги́ же побі́ду і одолі́ніє. Оте́чество на́ше огради́ споко́йствієм і тишино́ю. Сохрани́ оби́тель твою́ святу́ю от вся́ких собла́знов і научи́ всіх нас благогові́йно і богобоя́зненно ше́ствовати по стезя́м за́повідей Бо́жиїх, да сподо́бимся і ми ку́пно с тобо́ю і со всі́ми святи́ми ста́ти одесну́ю Го́спода сил в день стра́шнаго всеми́рнаго суда́ Єго́. Пом'яни́, уго́дниче Христо́в, святи́телю о́тче Ти́хоне, во святи́х свої́х моли́твах і ду́ші отше́дших оте́ць і бра́тій на́ших, да упоко́їть їх Госпо́дь в Небе́сних селе́ніїх; не пре́зри і на́ше воздиха́ніє, да ви́ну прославля́єм Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всехва́льний святи́телю і уго́дниче Христо́в, о́тче наш Ти́хоне! А́нгельськи пожи́в на землі́, ти я́ко А́нгел благи́й яви́лся єси́ і в ди́внім твоє́м прославле́нії. Ві́руєм от всея́ душі́ і помишле́нія, я́ко ти, благосе́рдий наш помо́щниче і моли́твенниче, твої́ми нело́жними хода́тайстви і благода́тію, оби́льно дарова́нною тебі́ от Го́спода, при́сно спосо́бствуєщі на́шему спасе́нію. Прийми́ у́бо, ублажа́ємий уго́дниче Христо́в, і в час сей на́ша недосто́йная моле́нія: свободи́ ни твої́м заступле́нієм от облега́ющаго нас суєсло́вія і суєму́дрія, неправові́рія і злові́рія челові́чеськаго. Потщи́ся, ско́рий о нас предста́телю, благоприя́тним твої́м хода́тайством умоли́ти Го́спода, да приба́вить Своя́ вели́кия і бога́тия ми́лости на нас грі́шних і недосто́йних рабі́х Свої́х, да уврачу́єть Своє́ю благода́тію неісці́льния я́зви і стру́пи растлі́нних душ і тіле́с на́ших, да раствори́ть окамені́лая сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніїх на́ших і да ізба́вить ни ві́чних мук і огня́ геє́нськаго; всім же ві́рним лю́дем Свої́м да да́руєть в ни́нішнем ві́ці мир і тишину́, здра́віє і спасе́ніє і во всем благо́є поспіше́ніє, да та́ко, ти́хоє і безмо́лвноє житіє́ пожи́вше во вся́ком благоче́стії і чистоті́, сподо́бимся со А́нгели і со всі́ми Святи́ми сла́вити і воспіва́ти всесвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва третя","ps":["О, вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче, святи́телю о́тче наш Ти́хоне! Со умиле́нієм прекло́нше колі́на і припа́дая к ра́ці честни́х і многоціле́бних моще́й твої́х, хва́лим, сла́вим і велича́єм просла́вльшаго тя Бо́га, і нам недосто́йним показа́вшаго в тебі́ ве́лію ми́лость, і всеусе́рдно, ві́рою і любо́вію чту́щий святу́ю па́м'ять твою́, мо́лим тя: принеси́ моли́тву на́шу к вся содержа́щему і спаса́ющему человіколю́бцю Го́споду, Єму́же ти ни́ні с ли́ки А́нгел і со всі́ми Святи́ми предстої́ши, да утверди́ть во святі́й Своє́й Правосла́вной Це́ркві живи́й дух пра́вия ві́ри і благоче́стія, да всі чле́ни єя́, чи́стії от суєму́дрія і суєві́рія, ду́хом і і́стиною покланя́ються Єму́ і усе́рдно пеку́ться о соблюде́нії Єго́ за́повідей, па́стирем єя́ да дасть святу́ю ре́вность попече́нія о спасе́нії вві́ренних їм люде́й — пра́во ве́рующия соблюда́ти, сла́бия і немощни́я во ві́рі укріпля́ти, неве́дущия наставля́ти, проти́вния облича́ти. І па́ки припа́дающе, с упова́нієм, я́коже ча́да отця́ нам су́ща, мо́лим тя, святи́телю Ти́хоне, ві́руєм бо, я́ко ти, на Небесі́х живи́й, лю́биши ни то́ю же любо́вію, є́юже вся бли́жняя твоя́ возлюби́л єси́, внегда́ пребива́ти тебі́ на землі́, іспроси́ у всеми́лостиваго Го́спода і всім нам пода́ти дар коєму́ждо благопотре́бен і вся, я́же к животу́ вре́менному і ві́чному поле́зная, ми́ра умире́ніє, градо́в на́ших утвержде́ніє, землі́ плодоно́сіє, от гла́да і па́губи ізбавле́ніє, от наше́ствія іноплеме́нних сохране́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, па́дшим возстановле́ніє, заблужда́ющим на путь і́стини возвраще́ніє, подвиза́ющимся в ді́ліх благи́х укріпле́ніє, благоде́лающим преспі́яніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, наста́вником ві́дініє і благоче́стіє, неві́дущим вразумле́ніє, си́рим, неіму́щим і убо́гим по́мощ і заступле́ніє, отходя́щим от сего́ вре́меннаго житія́ к ві́чному благо́є уготовле́ніє і напу́тствованіє, отше́дшим блаже́нноє упокоє́ніє. Сих всіх, найпа́че, проси́ нам, свя́тче Ти́хоне, у Щедрода́вця Бо́га, я́ко іми́й ве́ліє к Нему́ дерзнове́ніє: тебі́ бо стяжа́хом при́снаго засту́пника і те́плаго моли́твенника о нас пред Го́сподем, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє. Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["О святи́телю, о́тче наш Ти́хоне! Усли́ши нас і потщи́ся благоприя́тним твої́м хода́тайством умоли́ти Го́спода, да проба́вить Своя́ вели́кия і бога́тия ми́лости на нас, грі́шних і недосто́йних рабі́х Свої́х (імена́), да уврачу́єть Своє́ю благода́тію неісці́льния я́зви і стру́пи растлі́нних душ і тіле́с на́ших, да раствори́ть окамені́лая сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніях на́ших і да ізба́вить ни от ві́чних мук і огня́ геє́нськаго, да да́руєть в ни́нішнем ві́ці мир і тишину́, здра́віє і спасе́ніє, да та́ко сподо́бимся, со А́нгели і со всі́ми святи́ми, сла́вити і воспіва́ти всесвято́є І́м'я Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва п’ята","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче святи́телю о́тче наш Ти́хоне! Со умиле́нієм припа́дающе к іко́ні твоє́й, мо́лим тя: принеси́ моли́тву на́шу к человіколю́бцю Го́споду, да да́руєть же с долгоде́нствієм душе́вноє же і тіле́сноє здра́віє раба́м Бо́жиїм (імена́) і прихожа́нам свята́го хра́ма сего́, да проба́вить Своя́ вели́кия і бога́тия ми́лости на нас, грі́шних і недосто́йних рабі́х Свої́х, да раствори́ть окамене́лия сердця́ на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніях на́ших і да ізба́вить ни от ві́чних мук і огня́ геє́нського, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га, Отця́ і Си́на і Свята́го Ду́ха, і твоє́ оте́чеськоє заступле́ніє, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Іову, ігумену Почаївському","e":"Prayer to St Job, Abbot of Pochaiv","secs":[{"h":"Тропар, глас 4","ps":["Многострада́льнаго пра́отця долготерпі́ніє стяжа́в, / Крести́телеву воздержа́нію уподобля́яся, / Боже́ственния же ре́вности обою́ приобща́яся, / тіх імена́ досто́йно прия́ти сподо́бился єси́ / і і́стинния ві́ри бил єси́ пропові́дник безбоя́знен: / ті́мже мона́хов мно́жества ко Христу́ приве́л єси́ / і вся лю́ди в Правосла́вії утверди́л єси́, / І́ове преподо́бне о́тче наш, // моли́ спасти́ся душа́м на́шим."]},{"h":"Інший тропар на знайдення мощей, глас 4","ps":["Возло́ж на ся і́го Христо́во от ю́ности, / преподо́бне о́тче І́ове, / многолі́тні свя́то подвиза́лся єси́ / на по́прищі благоче́стія во оби́телі Уго́рницстей і на о́строві Ду́бенстем, / і, прише́д ко горі́ Поча́євстій, / зна́менанней цільбоно́сною стопо́ю Пресвяти́я Богоро́диці, / в ті́сній пеще́рі ка́менній / богоми́слія ра́ди і моли́тви многокра́тно заключа́лся єси́, / і, благода́тію Бо́жиєю укріпля́яся, / му́жественно потруди́лся єси́ / на по́льзу Це́ркве Христо́ви і оби́телі твоєя́, / ку́пно же і проти́ву враго́в Правосла́вія і благоче́стія христия́нськаго, / і, наста́вив сицево́му ополче́нію і́ночествующих, / побіди́телі тіх предста́вил єси́ Влади́ці і Бо́гу. // Того́ моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ і́стинния ві́ри столп, / єва́нгельських же за́повідей ревни́тель, / горди́ні обличе́ніє, / смире́нним же предста́тель і науче́ніє: / ті́мже і ублажа́ющим тя гріхо́в отпуще́ніє іспроси́, / і оби́тель твою́ невріди́му сохрани́, // І́ове о́тче наш, многострада́льному подо́бний."]},{"h":"Інший кондак на знайдення мощей, глас 8","ps":["Возсія́ от спу́да земна́го сокро́вище нетлі́нноє моще́й твої́х, / уго́дниче Бо́жий, / я́ко, благоче́стно пожи́во во ві́рі Христа́ Бо́га на́шего, / дости́гл єси́ доброді́телей соверше́нства, / і, оста́вль сла́дость житія́ преходя́щаго, / в пеще́рі гори́ Поча́євськия в поще́ніїх, моли́твах і труді́х свя́то подвиза́лся єси́, / і ті́ми ті́ло твоє́ ув'яди́л єси́. / Ни́ні же, преше́д к Бо́гу в безм'яте́жний і ві́чний поко́й, / мо́лишися о всіх с ві́рою к тебі́ прибіга́ющих. / Ра́дуйся, І́ове, пресла́вний уго́дниче Бо́жий // і оби́телі Поча́євския украше́ніє."]},{"h":"Молитва перша","ps":["О всесвяти́й і пресла́вний уго́дниче Бо́жий, преподо́бне о́тче наш І́ове, при́сний о нас ко Го́споду моли́твенниче і те́плий предста́телю о душа́х на́ших, к тебі́ всеумиле́нно ни́ні притека́єм і, помина́юще по́двиги і чудеса́ твоя́, я́же сотвори́л єси́ і твори́ши на землі́, про́сим і мо́лим твою́ благости́ню: я́коже тве́рдо і неізмі́нно потруди́лся єси́ во ві́рі Христа́ Бо́га на́шего, і, сію́ до конця́ в себі́ і во всіх при́сних твої́х ці́лу і невреди́му сохрани́вий от вся́ких прираже́ній вра́жиїх і єресе́й тлітво́рних, си́це і нас в Правосла́вії і єдиноми́слії укріпи́, отгоня́я моли́твами твої́ми вся́кую тьму неві́рія і неправоми́слія от серде́ць і помишле́ній на́ших; послужи́вий Го́споду і Бо́гу твоєму́ ді́ли благи́ми і неізрече́нним самоотверже́нієм в труді́х, бді́ніїх і поще́ніїх, наста́ви нас на путь вся́кия доброді́телі і благости́ні, ізбавля́я от іскуше́ній і гріхо́в, удаля́ющих нас от Бо́га і поверга́ющих в бе́здну зла все житіє́ на́ше; яви́вийся іногда́ с Пречи́стою Ді́вою Богоро́дицею верху́ гори́ Поча́євськия во спасе́ніє оби́телі твоєя́ от наше́ствія і обложе́нія ага́рянскаго, і ни́ні ускори́ на по́мощ страні́ на́шей проти́ву всіх враго́в на́ших, вні́шніх і вну́тренних, утвержда́я мир і тишину́ в землі́ на́шей, да безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́; і всім к тебі́ притека́ющим і припа́дающим к ра́ці честни́х і многоціле́бних моще́й твої́х і твоєя́ по́мощі і заступле́нія тре́бующим неоску́дния ми́лості незави́стно подава́яй, не оста́ви і нас, си́рих і безпо́мощних, тебі́ моля́щихся, ізбавля́я от вся́кия ско́рби, гні́ва і ну́жди, от гла́да, губи́тельства, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нник і междоусо́бния бра́ні. Єй, уго́дниче Бо́жий, при́зри ми́лостивно от Престо́ла Царя́ Сла́ви, Єму́же ти ни́ні предстої́ши со Арха́нгели і А́нгели і со всі́ми святи́ми, на оби́тель твою́ Поча́євськую, є́юже ти дре́вле му́дро пра́вил єси́, назда́в ю всехва́льним і ди́вним житіє́м твої́м, і сохрани́ ю моли́твами твої́ми і вся́кий град, і страну́ і всіх отовсю́ду, на мо́ре і на су́ші, в пусти́нях і в заключе́ніїх многоразли́чних тебе́ призива́ющих, от всіх зол, ви́димих і неви́димих, да, та́ко твоє́ю по́мощію і хода́тайством спаса́ємі, во ві́ці сем і по сконча́нії живота́ на́шего сподо́бимся ку́пно с тобо́ю сла́вити і воспіва́ти всечестно́є І́м'я Отця́, і Си́на, і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга (для читання в Почаївській Лаврі перед його мощами)","ps":["О всеблаже́нне і Богоно́сне о́тче наш І́ове, і́ночеськаго ангелоподо́бнаго житія́ богому́дрий наста́вниче, ві́ри Правосла́вния Восточнокафоли́чеськия про́тив лжемудрова́ній За́пада непреобори́мий защи́тниче і побо́рниче, богопре́данних уста́вов Це́ркве і преда́ній оте́чеських ві́рний блюсти́телю і стро́гий взиска́телю, свя́тости і чистоти́, цілому́дрія і нестяжа́нія, трудолю́бія і богоми́слія, поста́ і бді́нія вели́кий ревни́телю, долготерпі́нія і злострада́нія неутоми́мий і непобіди́мий ратобо́рче, о́браз кро́тости, зерца́ло смире́нія, примі́р незло́бія, по́стников удобре́ніє, ді́вственников похвало́, мона́хов і схимона́хов ра́досте. По і́мені твоєму́, преподо́бне о́тче, я́коже і дре́вняго о́наго І́ова, многострада́льна і пра́ведна, і житіє́ твоє́ бисть пра́ведно і непоро́чно от младе́нчеських пеле́н, всі́ми ді́ли благи́ми, я́ко многоці́нним би́сером, благоукраше́нно і благоду́шним терпі́нієм чрез мно́га лі́та скорбе́й і болі́зней, па́че зла́та і сребра́, в горни́лі іскуше́нних, просія́вши. Єще́ бо су́щи двана́десяти то́чію літ, восприя́л єси́ на ся і́го Христо́во с вели́ким о́бразом мона́шеським і да́же до ста́рости і престарі́нія вя́щше дев'яти́десяти літ, благоду́шно і неосла́бно, непоползнове́нно і небла́зненно поне́сл єси́, проше́д всяк путь пра́вди і святи́ні в пості́ і моли́тві, в колінопреклоне́ніїх і бді́ніїх і та́ко на висоту́ доброді́телей ізря́дну, вспомоществу́єм благода́тію Бо́жиєю, по степене́м возше́л єси́, я́ко всім диви́тися і ублажа́ти тя за премно́гую доброді́тель і любому́дріє твоє́, не то́чію в преді́ліх оте́чествія твоєго́, но і в страна́х о́крест су́щих, о чесо́м сли́шав боголюби́вий князь Остро́жський і вельми́ возжела́в імі́ти тя руководи́теля себе́ на путі́ спасе́нія, Крестовоздви́женськой оби́телі своє́й, я́же на о́строві Ду́бенстем, предстоя́теля і наста́вника моле́нієм любве́ своєя́ привлече́ тя, отону́дуже і святі́й оби́телі Поча́євськой, я́ко сокро́вище ве́ліє і неоціне́нноє, дарова́лся єси́. Ті́мже і пра́ведний Судія́ і Мздовозда́тель Бог, І́же вість су́щия Своя́, пре́жде да́же не би́ти їм, обіща́вий ві́рним рабо́м Свої́м за труди́ і по́двиги їх во сла́ву Єго́ І́мені возда́ти стори́цею, сви́ше призрі́ на смире́ніє твоє́ і вознесе́ тя, і просла́ви тя на землі́ живи́х, дарова́в духоно́сному тілесі́ твоєму́ дар нетлі́нія і благода́ть врачева́нія неду́гов душе́вних і тіле́сних, для всіх, с ві́рою і любо́вію ко всечестні́й ра́ці твоє́й притека́ющих, а моли́тві твоє́й си́лу і крі́пость непобіди́мую, враго́во ви́димих і неви́димих устраша́ющую і поража́ющую. Єгда́ бо іноплеме́нници о́ни ісмаєли́тстії, ї́хже Госпо́дь Бог єще́ в пра́отці їх от ро́да і до́му Авраа́мля отри́ну, вразі́ креста́ Христо́ва, облего́ша го́ру і оби́тель Поча́євськую, хотя́ще ю до конця́ разори́ти, тогда́ ти, о́тче прехва́льне, бил єси́ хода́тай святи́ми твої́ми моли́твами ко Всемогу́щему і Всеблаго́му Бо́гу і к Преблагослове́нній Ді́ві Марі́ї Богоро́дице, і бла́гостію, тебі́ от Бо́га да́нною, і предста́тельством Пречи́стия Богоро́диці отгна́л єси́ все безу́міє супоста́тов тіх і, всю я́рость їх разруши́в і крі́пость побіди́в, сотвори́л єси́ їх біжа́ти со стра́хом і тре́петом. При́зри у́бо і ни́ні о́ком благоутро́бія твоєго́, прилі́жно мо́лим тя, обстоя́ще святи́я і многоціле́бния мо́щі твоя́ і усе́рдно лобиза́юще я, при́зри на нас, недосто́йних чад і рабо́в твої́х, вступи́вших в стезі́ твої́, но немогу́щих пра́во по ним ше́ствовати, і на мі́сто сіє́, от літ дре́вніх богоізбра́нноє і чудеси́ просла́вленноє, в не́мже і́м'я твоє́ призива́ється і єго́же ти по́ти трудо́в твої́х богоуго́дних ороси́л і возді́лал єси́, і огради́ єго́ і нас моли́твами твої́ми от вся́каго наві́та вра́жия і зла́го обстоя́нія, сохраня́я і соблюда́я всіх і ка́ждаго в ми́рі і тишині́, во ві́рі нелицемі́рній і богоуго́дном жи́тельстві. Пода́ждь же, уго́дниче Бо́жий, і всім, приходя́щим сі́мо і твоєя́ по́мощі і заступле́нія і́щущим, бла́гость і ми́лость от Христа́ Бо́га на́шего і Пречи́стия Єго́ Ма́тере, да нікто́же ізи́деть отсю́ду в ту́гі і ско́рби, в печа́лі і сі́тованії, постижде́н і посра́млен в наді́янії своє́м, но ки́йждо, по мі́рі ві́ри і любве́ своєя́, да восприї́меть себі́ поне́ ні́кую отра́ду і утіше́ніє, облегче́ніє і подкріпле́ніє, защи́ту і по́мощ, во сла́ву Бо́га Трисвята́го, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О преподо́бне о́тче І́ове, і́ноков трудолю́бнаго житія́ богому́дрий наста́вниче, кро́тости і воздержа́нія, чистоти́ і цілому́дрія, братолю́бія і нищелю́бія, терпі́нія і бді́нія от ра́нней ю́ности до по́здней ста́рости неутоми́мий подви́жниче, ві́ри Правосла́вния вели́кий ревни́телю і непреобори́мий побо́рниче, землі́ Воли́нськия і Га́лицькия світи́ло благосве́тлоє і святи́я Поча́євськия оби́телі непобіди́мий защи́тниче! При́зри о́ком благоутро́бія твоєго́ на нас недосто́йних чад твої́х, к тебі́ усе́рдно по вся дні прибіга́ющих і на боголюби́вия лю́ди сія́, пред твої́ми духоно́сними і многоціле́бними моща́ми собра́вшіяся і благогові́йно к тім припа́дающия, і іспроси́ предста́тельством твої́м ко Всеви́шнему Влади́ці їм і нам вся, я́же к животу́ і благоче́стію, поле́зная і благопотре́бная: боля́щия ісціли́, малоду́шния обо́дри, скорб'я́щия уті́ши, оби́димия заступи́, немощни́я подкріпи́ і пове́рженния до́лу возста́ви, всім вся, благода́тію от Бо́га да́нною, да́руй, по коєго́ждо ну́жді і потре́бі, во спасе́ніє душі́ і во здра́віє ті́лу. Вознеси́ уго́дниче Бо́жий всемо́щную моли́тву твою́ о Українськой держа́ві, да бу́деть ви́ну мир і тишина́, благоче́стіє і благоде́нствіє, в суда́х пра́вда і ми́лость, в сове́тах му́дрость і благо́є преспі́яніє, да утвержда́ється же во благи́х челові́ціх ві́рность, в злих же страх і боя́знь, во є́же преста́ти їм от зла і твори́ти до́брая, да та́ко в держа́ві Українській ца́рство Христо́во расте́ть і мно́житься і да просла́виться в нем Бог, ди́вний во святи́х свої́х: Єму́же єди́ному подоба́єть вся́кая сла́ва, честь і поклоне́ніє Отцю́ і Си́ну, і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва князю Олександру Невському, у схимі Олексію","e":"Prayer to Prince Alexander Nevsky, in the schema Alexis","secs":[{"h":"Тропар, глас 4","ps":["Позна́й свою́ бра́тію, український Іо́сифе, / не в Єги́пті, но на Небесі́ ца́рствующий, / благові́рний кня́же Алекса́ндре, / і прийми́ моле́нія їх, / умножа́я жи́та лю́дем плодоно́сієм землі́ твоєя́, / гра́ди влади́чествія твоєго́ огражда́я моле́нієм, // правосла́вним христия́ном на сопроти́вния спобо́рствуя."]},{"h":"Інший тропар, глас 4","ps":["Я́ко благочести́ваго ко́рене / пречестна́я о́трасль бил єси́, блаже́нне Алекса́ндре, / яви́ бо тя Христо́с я́ко ні́коє Боже́ственноє сокро́вище Українській землі́, / но́ваго чудотво́рця пресла́вна і Богоприя́тна. / І днесь соше́дшеся в па́м'ять твою́ ві́рою і любо́вію, / во псалмі́х і пі́ніїх ра́дующеся сла́вим Го́спода, / да́вшаго тебі́ благода́ть ісціле́ній. / Єго́же моли́ спасти́ град сей, / і держа́ві Українській Богоуго́дній би́ти, // і синово́м Українським спасти́ся."]},{"h":"Кондак, глас 8","ps":["Я́ко звізду́ тя пресві́тлу почита́єм, / от восто́ка возсія́вшую, і на за́пад прише́дшую, / всю бо страну́ сію́ чудеси́ і добро́тою обогаща́єши, / і просвіща́єши ві́рою чту́щия па́м'ять твою́, Алекса́ндре блаже́нне. / Сего́ ра́ди днесь пра́зднуєм твоє́ успе́ніє, лю́діє твої́ су́щії, / моли́ спасти́ Оте́чество твоє́, і вся притека́ющия к ра́ці моще́й твої́х, / і ві́рно вопію́щия ті: // ра́дуйся, гра́ду на́шему утвержде́ніє."]},{"h":"Інший кондак, глас 4","ps":["Я́коже сро́дниці твої́, Бори́с і Гліб, / яви́шася тебі́ с Небесе́ в по́мощ, / подвиза́ющемуся на Ве́лгера Сві́йськаго і во́єв єго́, / та́ко і ти ни́ні, / блаже́нне Алекса́ндре, / прийди́ в по́мощ твої́м сро́дником / і побори́ борю́щия ни."]},{"h":"Молитва перша","ps":["Ско́рий помо́щниче всіх усе́рдно к тебі́ прибіга́ющих і те́плий наш пред Го́сподем предста́телю, святи́й благові́рний кня́же Алекса́ндре! При́зри ми́лостивно на ни недосто́йния мно́гими беззако́нії непотре́бни себі́ сотво́ршія, к ра́ці моще́й твої́х (іли́: іко́ні твоє́й) ни́ні притека́ющия і із глубини́ се́рдця тебі́ взива́ющия: ти в житії́ своє́м ревни́тель і защи́тник правосла́вния ві́ри бил єси́, і нас в ней те́плими твої́ми моли́твами непоколеби́ми утверди́. Ти вели́коє, возло́женноє на тя служе́ніє тща́тельно проходи́л єси́, і нас твоє́ю по́мощію пребива́ти коєго́ждо, в не́йже призва́н єсть, наста́ви. Ти, побіди́в полки́ супоста́тов, от преді́лов Українських отгна́л єси́, і на нас ополча́ющихся всіх ви́димих і неви́димих враго́в низложи́. Ти, оста́вив тлі́нний віне́ць ца́рства земна́го, ізбра́л єси́ безмо́лвноє житіє́, і ни́ні пра́ведно вінце́м нетлі́нним увінча́нний, на Небесі́х ца́рствуєши, хода́тайствуй і нам, смире́нно мо́лим тя, житіє́ ти́хоє і безм'яте́жноє і к ві́чному Ца́рствію ше́ствіє неукло́нноє твої́м предста́тельством устро́й нам. Предстоя́ же со всі́ми святи́ми Престо́лу Бо́жию, моли́ся о всіх правосла́вних христия́нах, да сохрани́ть їх Госпо́дь Бог Своє́ю благода́тію в ми́рі, здра́вії, і благоде́нствії, і вся́ком благополу́чії в должа́йшая лі́та, да і при́сно сла́вим і благослови́м Бо́га, в Тро́йці Святі́й сла́вимаго Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́й благові́рний кня́же Алекса́ндре! При́зри ми́лостивно на ни, недосто́йния раби́ Бо́жії (імена́), і ісхода́тайствуй нам житіє́ ти́хоє і безм'яте́жноє, і к ві́чному Ца́рствію ше́ствіє неукло́нноє твої́м предста́тельством устро́й нам, да сохрани́ть нас Госпо́дь Бог Своє́ю благода́тію в ми́рі, здра́вії, долгоде́нствії і вся́ком благополу́чії в должа́йшая лі́та, да при́сно сла́вим і благослови́м Бо́га в Тро́йці Святі́й сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / благові́рний кня́же Алекса́ндре, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]},{"h":"Інше величання на успіння благовірного князя Олександра","ps":["Велича́єм тя, / благові́рний кня́же Алекса́ндре, / і чтим свято́є успе́ніє твоє́, / і ни́ні мо́лиши за нас // Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Молитва преподобному Силуану Афонському","e":"Prayer to St Silouan of Athos","secs":[{"h":"Тропар, глас 4","ps":["Христа́ Учи́теля / в путі́ смире́нні помоли́вся прия́л єси́ / свиді́тельствующу Ду́ху в се́рдці твоє́м спасе́ніє. / Сего́ ра́ди веселя́ться ни́ні лю́діє всі / о па́м'яті твоє́й на упова́ніє зва́нії, / преподо́бне о́тче Силуа́не, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Тропар, глас 2","ps":["Серафи́мськия любве́ ко Го́споду пла́менний ревни́телю, / і Ієремі́ї, о наро́ді пла́чущему, / усе́рдний подража́телю, / всеблаже́нне о́тче Силуа́не, / ти зо́ву Ма́тере Го́спода сил вні́мляй, / змі́я гріхо́внаго мужему́дренно ізригну́л єси́, / і в го́ру Афо́нськую от суєти́ ми́ра удали́лся єси́, / іді́же в труді́х і моли́твах со слеза́ми / благода́ть Свята́го Ду́ха оби́льно стяжа́в, / є́юже сердця́ на́ша воспламени́ / і с тобо́ю уми́льно взива́ти укріпи́: / Го́споди мой, Жи́зне моя́ і Ра́досте Свята́я, // спаси́ мир і нас от вся́ких лю́тих."]},{"h":"Інший тропар, глас 3","ps":["Во вертогра́ді духо́внім Святи́я гори́ Афо́нськия в уді́лі Пречи́стия Ді́ви Богоро́диці, в труді́х, бді́ніїх і моли́твах стяжа́л єси́ благода́ть Го́спода Бо́га, Єго́же моли́, Силуа́не преподо́бне, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Смиренному́дрія іспові́дниче преди́вний, / і человіколю́бія Ду́хом Святи́м согріва́ємая добро́то, / Бо́гу возлю́бленне Силуа́не, / о по́двизі твоє́м Це́рков Українськая ра́дується, / і́ноці же Гори́ Афо́нськия і всі христия́нстії лю́діє, / веселя́щеся, сино́внею любо́вію к Бо́гу устремля́ються. / Єго́же моли́ о нас, равноа́нгельне богові́дче, // во є́же спасти́ся нам, в горі́нії любве́ тебі́ подража́ющим."]},{"h":"Інший кондак, глас 3","ps":["Страстьми́ обурева́ємую ду́шу мою́ всеблаже́нне Силуа́не, прилі́жно очи́сти моли́твами твої́ми, да зову́ ті с весе́лієм, я́ко сла́ву стяжа́вшему у Бо́га, сла́ва просла́вльшему тя Христу́, сла́ва удиви́вшему тя, сла́ва ті кро́тко я́вльшемуся, і ра́дости безконе́чния іспо́лнившему."]},{"h":"Молитва перша","ps":["О преди́вний уго́дниче Бо́жий о́тче Силуа́не! По благода́ті, тебі́ от Бо́га да́нной, сле́зно моли́тися о всей вселе́нній, ме́ртвих, живи́х і гряду́щих, не премолчи́ за нас ко Го́споду, к тебі́ усе́рдно припа́дающих і твоєго́ предста́тельства уми́льно прося́щих. Подви́гни, о всеблаже́нне, на моли́тву Усе́рдную Засту́пницю ро́да христия́нськаго, Преблагослове́нную Богоро́дицю і Присноді́ву Марі́ю, чу́дно призва́вшую тя би́ти ві́рним ді́лателем в Єя́ земно́м вертогра́ді, іді́же ізбра́нници Бо́жії о грісі́х на́ших ми́лостива і долготерпіли́ва би́ти Бо́га умоля́ють, во є́же не пом'яну́ти непра́вд і беззако́ній на́ших, но по неізрече́нной бла́гости Го́спода на́шего Ісу́са Христа́ уще́дрити і спасти́ нас по вели́цій Єго́ ми́лості. Єй, уго́дниче Бо́жий, с Преблагослове́нною Влади́чицею ми́ра — Святе́йшею Ігу́менією Афо́на і святи́ми подви́жниками Єя́ земна́го жре́бія іспроси́ у святи́х Святі́йшаго Сло́ва Святі́й Горі́ Афо́нстій і боголюби́вим пустинножи́телем єя́ от всіх бід і наві́тов вра́жиїх в ми́рі сохрани́тися. Да А́нгели святи́ми от зол ізбавля́ємі і Ду́хом Святи́м во ві́рі і братолю́бії укріпля́єми, до сконча́нія ві́ка о Єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві моли́тви творя́ть і всім спаси́тельний путь указу́ють, да Це́рков земна́я і Небе́сная непреста́нно славосло́вить Творця́ і Отця́ Сві́тов, просвіща́ющи і освяща́ющи мир во ві́чній пра́вді і бла́гости Бо́жієй. Наро́дам землі́ всей іспроси́ благоде́нственноє і ми́рноє житіє́, дух смиренному́дрія і братолю́бія, добронра́вія і спасе́нія, дух стра́ха Бо́жия. Да не зло́ба і беззако́ніє ожесточа́ють сердца́ людські́я, могу́щия істреби́ти любо́в Бо́жию в челові́ціх і низве́ргнуть їх в богопроти́вния вражду́ і братоуби́йства, но в си́лі Боже́ственния любве́ і пра́вди, я́коже на небесі́ і на землі́ да святи́ться і́м'я Бо́жиє, да бу́деть во́ля Єго́ свята́я в челові́ціх, і да воцаря́ться мир і Ца́рствіє Бо́жиє на землі́. Та́кожде і земно́му Оте́честву твоєму́ — землі́ Українській іспроси́, уго́дниче Бо́жий, вожделі́нний мир і небе́сноє благослове́ніє, во є́же, всемо́щним омофо́ром Ма́тере Бо́жия покрива́ємому, ізба́витися єму́ от гла́да, губи́тельства, тру́са, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні і от всіх враг ви́димих і неви́димих, і та́ко святі́йшим до́мом Преблагослове́нния Богоро́диці до сконча́нія ві́ка єму́ преби́ти Креста́ Животворя́щаго си́лою і в любві́ Бо́жієй; неоскудіва́єму утверди́тися. Нам же всім, во тьму гріхо́в погружа́ємим і покая́нія тепла́, ніже́ стра́ха Бо́жия не іму́щим і си́це безмі́рно лю́б'ящаго нас Го́спода непреста́нно оскорбля́ющим, іспроси́, о всеблаже́нне, у Всеще́драго Бо́га на́шего, да Своє́ю всеси́льною благода́тію боже́ственне посіти́ть і оживотвори́ть ду́ші на́ша, і вся́ку зло́бу і го́рдость жите́йськую, уни́ніє і нераді́ніє в сердця́х на́ших да упраздни́ть. Єще́ мо́лимся, о є́же і нам, благода́тію Всесвята́го Ду́ха укріпля́ємим і любо́вію Бо́жиєю согрева́ємим, в человіколю́бії і братолю́бії, смиренному́дрії і моли́твенном сраспина́нії друг за дру́га і за всіх, в пра́вді Бо́жієй утверди́тися і в благода́тній любві́ Бо́жієй благонра́вно укріпи́тися, і синолю́бне Тому́ прибли́житися. Да та́ко, творя́ще Єго́ всесвяту́ю во́лю, во вся́ком благоче́стії і чистоті́ вре́меннаго житія́ путь непости́дно пре́йдем і со всі́ми святи́ми Небе́снаго Ца́рствія і Єго́ А́гнчаго бра́ка сподо́бимся. Єму́ же от всіх земни́х і небе́сних да бу́деть сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, Пресвяти́м і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преди́вний уго́дниче Бо́жий, преподо́бне о́тче Силуа́не, святи́я гори́ Афо́нськия но́вий світи́льниче, Пресвято́ю Богоро́дицею возлю́бленний і би́ти ві́рним ді́лателем в Єя́ земні́м вертогра́ді призва́нний, со умиле́нієм ни́ні преклоня́єм колі́на серде́ць на́ших і взива́єм ті: принеси́ моли́тву на́шу к Всеми́лостивому Бо́гу і іспроси́ вся, я́же на по́льзу душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду несумне́нну, любо́в нелицемі́рну, во іскуше́ніїх му́жество, в злострада́ніїх і болі́зніх терпі́ніє, во благоче́стії преспі́яніє, в моли́твах усе́рдіє; прийми́ смире́нноє моле́ніє на́ше, согрі́й нас диха́нієм любве́ твоєя́, озари́ нас сві́том дарова́нния тебі́ благода́ті і бу́ди о нас хода́тай ко Го́споду, проле́й к Нему́ моли́тву твою́, да ути́шить бу́рю страсте́й на́ших і хла́дная сердця́ на́ша огне́м Боже́ственния любве́ своєя́ да согрі́єть і та́ко сподо́бит нас те́плоє покая́ніє со слеза́ми Єму́ приноси́ти, труди́ же і ско́рби житія́ сего́ терпіли́во, безро́потно і со благодаре́нієм понести́, і в час ісхо́да на́шего от земна́го житія́, бе́здну гріхо́в на́ших в мо́рі милосе́рдія Своєго́ да погрузи́ть і нас поми́луєть ра́ди Своєя́ неізрече́нния любве́ к ро́ду челові́чеському і да сподо́бит в Ца́рствії небе́снім наслажда́тися Єго́ Боже́ственною любо́вію ку́пно с тобо́ю і всі́ми святи́ми, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Димитрію, митрополиту Ростовському","e":"Prayer to St Dimitry, Metropolitan of Rostov","secs":[{"h":"Тропар, глас 8","ps":["Правосла́вія ревни́телю і раско́ла іскорени́телю, / Український ціле́бниче, і но́вий к Бо́гу моли́твенниче, / списа́ньми твої́ми бу́їх уцілому́дрил єси́, / цівни́це духо́вная, Дими́тріє блаже́нне, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Звізду́ Українськую от Ки́єва возсія́вшую, / і чрез Но́вград Сі́верський в Росто́в дости́гшую, / всю же страну́ сію́ уче́ньми і чудеси́ озари́вшую, / ублажи́м златослове́снаго учи́теля Дими́трія, / той бо всім вся написа́, я́же к наставле́нію, / да всіх приобря́щеть, я́коже Па́вел Христу́, // і спасе́ть правові́рієм ду́ші на́ша."]},{"h":"Молитва перша","ps":["О всеблаже́нний святи́телю Дими́тріє, вели́кий уго́дниче Христо́в, Златоу́сте Український, усли́ши нас грі́шних, моля́щихся тебі́, і принеси́ моли́тву на́шу к Ми́лостивому і Человіколю́бцю Бо́гу, Єму́же ти ни́ні в ра́дості святи́х і с ли́ки А́нгели предстої́ши! Умоли́ Єго́ благоутро́біє, да не осу́дить нас по беззако́ніям на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й. Іспроси́ нам у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє, землі́ благопло́діє і во всем вся́коє ізоби́ліє і благоде́нствіє, і да не во зло обрати́м блага́я, да́руємая нам от Ще́дрого Бо́га, но в сла́ву Єго́ і в прославле́ніє твоєго́ заступле́нія. Да́руй нам богоуго́дно прейти́ по́прище вре́менния жи́зні; ізба́ви нас возду́шних мита́рств і наста́ви нас на путь, веду́щий в селе́нія пра́ведних, іді́же пра́зднующих глас непреста́нний, зря́щих Бо́жия лиця́ неізрече́нную добро́ту. Це́рков же Святу́ю от раско́лов і єресе́й сохрани́, ві́рних укріпи́, заблужда́ющих обрати́ і всім да́руй вся, я́же ко спасе́нію і сла́ві Бо́жієй подоба́ющая; Оте́чество твоє́ сохрани́ от враго́в ненаві́тно, но побора́й ору́жіє Крестоно́снаго во́їнства; і пода́ждь нам всім твоє́ архипа́стирськоє і свято́є благослове́ніє, да о́ним осіня́ємі, ізба́вимся от ко́зней лука́ваго і ізбі́гнем от вся́кия біди́ і напа́сти. Усли́ши моле́ніє на́ше, о́тче Дими́тріє, і моли́ непреста́нно о нас Всеси́льнаго Бо́га, сла́вимаго і поклоня́ємаго в Тріє́х Іпоста́сіх, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́телю Дими́тріє, вели́кий уго́дниче Христо́в, Златоу́сте Український! Усли́ши нас грі́шних, моля́щихся тебі́, і принеси́ моли́тву на́шу к Человіколю́бцю Бо́гу о раба́х Бо́жиїх (імена́).Умоли́ Єго́ благосе́рдіє, да не осу́дить нас по беззако́нієм на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й. Іспроси́ нам у Христа́ Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє. Да́руй нам богоуго́дно прейти́ по́прище вре́менния жи́зні: ізба́ви нас от возду́шних мита́рств і наста́ви нас на путь, веду́щий в селе́нія пра́ведних; пода́ждь нам твоє́ архипа́стирськоє і свято́є благослове́ніє, да о́ним осіня́ємі, ізба́вимся от ко́зней лука́ваго і ізбі́гнем от вся́кой біди́ і напа́сти. Усли́ши моле́ніє на́ше, о́тче Дими́тріє, і моли́ непреста́нно о нас Всеси́льнаго Бо́га, сла́вимаго і покланя́ємаго в трех іпоста́сіх, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О преди́вний і пресла́вний чудотво́рче Дими́тріє, ісціля́яй неду́ги челові́чеськія! Ти неуси́пно мо́лиши Го́спода Бо́га на́шего о всіх грі́шних: молю́ у́бо тя, бу́ди мі хода́тай пред Го́сподем і помо́щник на преоборе́ніє страсте́й ненаси́тния пло́ті моєя́ і на одолі́ніє стріл сопроти́вника моєго́ дия́вола, ї́миже уязвля́єть немощно́є се́рдце моє́ і, а́ки гла́дний і лю́тий звір, а́лчеть погуби́ти ду́шу мою́. Ти, святи́телю Христо́в, моя́ огра́да, ти моє́ заступле́ніє і ору́жіє! За твої́м соді́йствієм сокрушу́ вся во мні сопроти́вная во́лі Царя́ ца́рствующих. Ти, вели́кий чудотво́рче, во дні по́двигов твої́х в ми́рі сем ревну́я о Правосла́вной Це́ркве Бо́жієй, я́ко і́стинний і до́брий па́стир, небла́зненно облича́л єси́ гріхи́ і неві́жествія людські́я, і уклони́вшихся от стезі́ пра́вди в є́ресі і раско́ли наставля́л єси́ на путь і́стини. Споспі́шествуй у́бо і мні іспра́вити кратковре́менний путь жи́зні моє́й, да непреткнове́нно пойду́ по стезі́ за́повідей Бо́жиїх і нелі́ностно порабо́таю Го́сподеві моєму́ Ісу́су Христу́, я́ко єди́ному Влади́ці моєму́, Іскупи́телю і пра́ведному Судії́ моєму́. К сим же припа́дая, молю́ся Ті, уго́дниче Бо́жий, єгда́ ізи́ти душі́ моє́й із тілесе́ моєго́, ізба́ви ю от те́мних мита́рств, не і́мам бо до́брих діл ко оправда́нію моєму́, не даждь сатані́ возгорди́тися побі́дою над немощно́ю душе́ю моє́ю. Ізба́ви ю от геє́ни, іді́же плач і скре́жет зубо́в, і святи́ми моли́твами твої́ми сотвори́ м'я прича́стника Небе́снаго Ца́рствія в Тро́йці сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Харитону, сповіднику","e":"Prayer to St Chariton the Confessor","secs":[{"h":"Тропар, глас 8","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, / і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, / і бил єси́ світи́льник вселе́нной, / сія́я чудеси́, Харито́не о́тче наш. // Моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Наслади́вся, Богому́дре, воздержа́нія, / і пло́ті твоєя́ вожделі́нія обузда́в, / яви́лся єси́ ві́рою возраща́єм, / і я́ко жи́зні дре́во посреді́ рая́ процві́л єси́, // Харито́не всеблаже́нне, свяще́ннійший."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Харито́не! Не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до твоє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад твої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти твоя́ духо́вния, я́ко імі́яй дерзнове́ніє к Небе́сному Царю́, не премолчи́ за ни ко Го́споду, і не пре́зри нас, недосто́йних, ві́рою і любо́вію чту́щих тя. Помина́й нас у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу, і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва, а́ще бо ті́лом і преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий. Ві́дуще у́бо тя воі́стину і по сме́рті жива́ су́ща, тебі́ припа́даєм і тебі́ мо́лимся: моли́ся о нас Всеси́льному Бо́гу, о по́льзі душ на́ших і іспроси́ нам вре́м'я на покая́ніє, да невозбра́нно пре́йдем от землі́ на не́бо, от мита́рств же го́рких, бісо́в, возду́шних князе́й і от ві́чния муки́ да ізба́вимся, і Небе́снаго Ца́рствія наслі́дници да бу́дем со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і с Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Амвросію Оптинському","e":"Prayer to St Ambrose of Optina","secs":[{"h":"Тропар, глас 5","ps":["Я́ко к ціле́бному істо́чнику / притека́єм к тебі́, Амвро́сіє, о́тче наш. / Ти бо на путь спасе́нія нас ві́рно наставля́єши, / моли́твами от бід і напа́стей охраня́єши, / в ті́лесних і душе́вних ско́рбіх утіша́єши, / па́че же смире́нію, терпі́нію і любве́ науча́єши. / Моли́ Человіколю́бця Христа́ / і Засту́пницю усе́рдную // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Заві́т Пастиренача́льника іспо́лнив / ста́рчества благода́ть наслі́довал єси́, / болі́знуя се́рдцем о всіх, с ві́рою притека́ющих к тебі́, / ті́мже і ми, ча́да твоя́, с любо́вію вопіє́м ті: / о́тче святи́й Амвро́сіє, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Молитва перша","ps":["О вели́кий ста́рче і уго́дниче Бо́жий, преподо́бне о́тче наш Амвро́сіє, Оптинськая похвало́ і всієї України учи́телю благоче́стія! Сла́вим твоє́ во Христі́ смире́нноє житіє́, і́мже Бог превознесе́ і́м'я твоє́ єще́ на землі́ тебі́ су́ща, найпа́че же увінча́ тя небе́сною че́стію по отше́ствії твоє́м в черто́г сла́ви ві́чния. Прийми́ ни́ні моле́ніє нас, недосто́йних чад твої́х, чту́щих тя і призива́ющих і́м'я твоє́ свято́є. Ізба́ви нас твої́м предста́тельством пред престо́лом Бо́жиїм от всіх ско́рбних обстоя́ній, душе́вних і тіле́сних неду́гов, злих напа́стей, тлітво́рних і лука́вих іскуше́ній. Низпосли́ оте́честву на́шему от Великодарови́таго Бо́га мир, тишину́ і благоде́нствіє. Бу́ди непрело́жний покрови́тель Святи́я оби́телі сія́, в не́йже в преуспі́янії сам подвиза́лся єси́ і угоди́л єси́ всі́ми в Тро́йці сла́вимому Бо́гу на́шему. Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, Отцю́, і Си́ну, і Свято́му Ду́ху ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне і богоно́сне о́тче наш Амвро́сіє! Ти порабо́тати Го́сподеві жела́я, зді всели́лся єси́, і нелі́ностно во труді́х, бде́нієх, моли́твіх і пості́х подвиза́лся єси́, і бил єси́ наста́вник мона́шествующим, всім же лю́дем учи́телю ре́вностний. Ни́ні у́бо, по отше́ствії твоє́м от земни́х, Небе́сному Царю́ предстоя́, моли́ бла́гость Єго́, є́же уще́дрити мі́сто селе́нія твоєго́, святу́ю оби́тель сію́, іді́же ду́хом любве́ твоєя́ неотсту́пно пребива́єши, і всім лю́дем твої́м, с ві́рою к ра́ці моще́й твої́х припа́дающим, во блага́я проше́нія їх іспо́лнити. Іспроси́ у ми́лостиваго Го́спода на́шего, да низпо́слеть нам оби́ліє небе́сних і земни́х благ, па́че же я́же на по́льзу душ на́ших да да́руєть нам, і сконча́ти житіє́ сіє́ привре́менноє в покая́нії да сподо́бит, в день же су́дний десна́го предстоя́нія і наслажде́нія во Ца́рствії Своє́м да удосто́їть во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О всечестни́й ста́рче пресла́вния і ди́вния О́птини пу́стині, преподо́бне і богоно́сне о́тче наш Амвро́сіє, Це́ркве на́шея до́броє украше́ніє і благода́тний світи́льниче, небе́сним сві́том всіх озаря́яй, кра́сний і духо́вний плод України і всея́ подсо́лнечния, ду́ші ві́рних оби́льно услажда́яй і увеселя́яй! Ни́ні с ві́рою і тре́петом припа́даєм пред цільбоно́сною ра́кою святи́х моще́й твої́х, ї́хже на утіше́ніє і по́мощ стра́ждущим ми́лостивно дарова́л єси́, смире́нно мо́лим Тя се́рдцем і усти́, о́тче святи́й, я́ко всеукраїнськаго наста́вника і учи́теля благоче́стія, па́стиря і врача́ душе́вних і тіле́сних неду́гов на́ших: воззри́ на чад твої́х зіло́ согріша́ющих в словесі́х і ді́ліх і посіти́ нас мно́гою і свято́ю своє́ю любо́вію, є́юже сла́вно преуспі́л єси́ єще́ во дні земни́я, а найпа́че по пра́ведній твоє́й кончи́ні, наставля́я в пра́виліх святи́х і богопросвеще́нних отце́в, вразумля́я нас в за́повідіх Христо́вих, в ни́хже до́брі поревнова́л єси́ до послі́дняго часа́ твоєя́ многотру́дния і́ночеськия жи́зні; іспроси́ нам, немощству́ющим душе́ю і бе́дствующим в ско́рбіх, благоприя́тноє і спаси́тельноє вре́м'я на покая́ніє, і́стинноє ісправле́ніє і обновле́ніє на́шего житія́, в не́мже ми, грі́шнії, осуєти́хомся умо́м і се́рдцем, преда́хом себі́ непотре́бним і лю́тим страсте́м, поро́ком і беззако́нієм, і́мже ність числа́; прийми́ у́бо, соблюди́ і покри́й нас кро́вом твоєя́ мно́гія ми́лости, низпосли́ нам благослове́ніє от Го́спода, да понесе́м благо́є і́го Христо́во в долготерпі́нії до конця́ дній на́ших, ча́юще бу́дущаго живота́ і Ца́рствія, іді́же ність печа́ль ні воздиха́ніє, но жизнь і ра́дость безконе́чная, ізоби́льно проістека́ємая от Єди́наго, Всесвята́го і Блаже́ннаго Істо́чника безсме́ртія в Тро́йці поклоня́ємаго Бо́га Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомученику Димитрію Солунському, мироточцю","e":"Prayer to the Great Martyr Demetrius of Thessalonica, the Myrrh-Streamer","secs":[{"h":"Тропар, глас 3","ps":["Вели́ка обрі́те в біда́х / тя побо́рника вселе́нная, страстоте́рпче, / язи́ки побіжда́юща. / Я́коже у́бо Ли́єву низложи́л єси́ горди́ню, / і на по́двиг дерзнове́нна сотвори́в Не́стора, / та́ко, свя́те Дими́тріє, / Христу́ Бо́гу моли́ся // дарова́ти нам ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Крове́й твої́х струя́ми, Дими́тріє, / Це́рков Бог обагри́, / да́вий тебі́ крі́пость непобіди́мую, / і соблюда́я град твой невреди́м: // того́ бо єси́ утвержде́ніє."]},{"h":"Молитва перша","ps":["Святи́й і сла́вний великому́чениче Христо́в Дими́тріє, ско́рий помо́щниче і те́плий засту́пниче с ві́рою притека́ющих к тебі́! Предстоя́ с дерзнове́нієм Небе́сному Царю́, іспроси́ у Него́ проще́ніє согріше́ній на́ших і о є́же ізба́витися нам от всегуби́тельния я́зви, тру́са, пото́па, огня́, меча́ і ві́чния ка́зні. Моли́ бла́гость Єго́, є́же уще́дрити град сей, оби́тель сію́ і вся́кую страну́ христия́нськую. Ісхода́тайствуй у Царя́ ца́рствующих на враги́ побі́ду і одолі́ніє правосла́вним христия́нам, всей держа́ві правосла́вной мир, тишину́, тве́рдость во ві́рі і преспі́яніє во благоче́стії; нам же, чту́щим честну́ю па́м'ять твою́, іспроси́ благода́тноє укріпле́ніє на діла́ блага́я, да благоутро́бноє Влади́ці на́шему Христу́ Бо́гу зді творя́ще, сподо́бимся моли́твами твої́ми наслі́довати Ца́рствіє Небе́сноє для ві́чнаго прославле́нія Єго́ со Отце́м і Святи́м Ду́хом. Амі́нь."]},{"h":"Молитва друга","ps":["Святи́й великому́чениче Христо́в Дими́тріє! Предстоя́ со дерзнове́нієм Небе́сному Царю́, іспроси́ у Него́ проще́ніє согріше́ній на́ших і о є́же ізба́витися нам, окая́нним (імена́) от всегуби́тельния я́зви, огня́ і ві́чния ка́зні. Моли́ бла́гость Єго́, є́же уще́дрити прихо́д (дом) сей і храм наш. Іспроси́ нам благода́тноє укріпле́ніє на діла́ блага́я, да благоуго́дноє Влади́ці на́шему Христу́ Бо́гу зді творя́ще, сподо́бимся моли́твами Твої́ми наслі́довати Ца́рствіє Небе́сноє і та́мо прославля́ти Єго́, со Отце́м і Святи́м Ду́хом, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Іннокентію, єпископу Іркутському","e":"Prayer to St Innocent, Bishop of Irkutsk","secs":[{"h":"Тропар, глас 3","ps":["Світи́льниче Це́ркве пресві́тлий, / озари́вий луча́ми добро́т твої́х страну́ сію́, / і ісціле́ньми мно́гими притека́ющих к тебі́ с ві́рою / Бо́га просла́вивий, / мо́лим тя, святи́телю о́тче Інноке́нтіє, / огражда́й моли́твами твої́ми град сей // от всіх бід і печа́лі."]},{"h":"Кондак, глас 4","ps":["Непоро́чности соіме́ннаго па́стиря, / пропові́дника ві́ри в язи́ціх Монго́льських, / сла́ву і украше́ніє Ірку́тськия па́стви, / любо́вію восхва́лим всі ві́рнії: / той бо єсть храни́тель страни́ Сиби́рськия // і моли́твенник о душа́х на́ших."]},{"h":"Молитва перша","ps":["К тебі́, свя́тче Бо́жий, я́ко к ско́рому помо́щнику і моли́твеннику о спасе́нії моє́м, аз недосто́йний і грі́шний припа́дая молю́ся: не пре́зри мене́ уни́лаго, не́мощнаго, во мно́гая беззако́нія впа́дшаго, і по вся дні і часи́ согріша́ющаго, но воньми́ душі́ моє́й, я́ко скорблю́, і умоли́ Го́спода Бо́га всея́ тва́рі Соді́теля, Єму́же ни́ні предстої́ши в ра́дості святи́х і с ли́ки а́нгелов, поми́ловати м'я і ізвести́ із темни́ці гріхо́вния ду́шу мою́, пре́жде да́же не отиду́ отсю́ду і ктому́ не угото́в явлю́ся на суд Єго́. Єй, о́тче! Не посрами́ мене́, к тебі́ с ві́рою притека́ющаго, а́ще бо і недосто́їн єсьм твоєго́ хода́тайства і заступле́нія, но ти, бив подража́тель человіколю́бія Бо́жия, сотвори́ м'я досто́йна чрез обраще́ніє от злих діл к благо́му житію́, да та́ко душе́ю і ті́лом здрав бив, сла́влю і пою́ ди́внаго во святи́х Свої́х Бо́га на́шего і твоє́ те́плоє заступле́ніє, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Святи́телю, о́тче Інноке́нтіє! При́зри на нас, раб Бо́жиїх (імена́), і на прихо́д (дом) сей; моли́ Христа́ Бо́га, да низпосле́ть нам Ду́ха Своєго́ Свята́го дар, во є́же умудри́ти нас ходи́ти пред Ним во вся́ком благоче́стії і чистоті́. Ми при́сно заблужда́єм от путі́ спасе́нія: руководи́ нас, ми́лостивий наш наста́вниче. Ми не́мощни єсьми́ во ві́рі: утверди́ нас, правові́рія учи́телю. Ми зіло́ убо́зі сотвори́хомся до́брих діл: обогати́ нас, благосе́рдія сокро́вище. Ми при́сно наві́туємі єсьми́ от враг, ви́димих і неви́димих, і озлобля́ємі: помози́ нам, безпо́мощних засту́пниче; да славосло́в'яще і́м'я Бо́жиє во дні і в нощі́, сподо́бимся би́ти наслі́дници і жи́зні ві́чния, і просла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["Свя́тче Бо́жий, па́стирю до́брий, ді́лателю ві́рний виногра́да Христо́ва, святи́телю о́тче Інноке́нтіє! При́зри на град сей і на лю́ди сія́! Моли́ Христа́ Бо́га, да сохрани́ть па́ству твою́ от волко́в, гу́б'ящих ю; да ниспо́слеть Ду́ха Своєго́ Свята́го во є́же умудри́ти нас ходи́ти пред Ним во вся́ком благоче́стії і чистоті́ во вся дні живота́ на́шего, да славосло́в'яще І́м'я Єго́ Всесвято́є во дні і в нощі́, сподо́бимся би́ти наслі́дници жи́зні ві́чния, і просла́вим Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Сави Освяченому","e":"Prayer to St Sabbas the Sanctified","secs":[{"h":"Тропар, глас 8","ps":["Слез твої́х тече́ньми пусти́ні безпло́дноє возді́лал єси́, / і і́же із глубини́ воздиха́ньми во сто трудо́в уплодоноси́л єси́, / і бил єси́ світи́льник вселе́нній, / сія́я чудеси́, Са́вво о́тче наш, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Я́ко от младе́нства Бо́гу же́ртва непоро́чная / прине́слся єси́ доброді́телію, Са́вво блаже́нне, / садоді́латель бив благоче́стія; / ті́мже бил єси́ преподо́бних удобре́ніє, / граждани́н же пусти́нний достохва́лен. Ті́мже зове́м ті: // ра́дуйся, Са́вво пребога́те."]},{"h":"Молитва","ps":["О преди́вний і всехва́льний уго́дниче Бо́жий, преподо́бне о́тче Са́вво! Днесь во святі́м хра́мі твоє́м, благогові́йно предстоя́ще пред свято́ю іко́ною твоє́ю і ра́достно соверша́юще пресві́тлую па́м'ять твою́, ублажа́єм тя засту́пника на́шего. Почита́юще же твоє́ ве́ліє дерзнове́ніє пред Го́сподом, смире́нно мо́лим тя, преблаже́нне прийми́ ми́лостивно от нас хвале́бноє пі́ніє сіє́, от любве́ і усе́рдія тебі́ приноси́моє. І, я́ко імі́яй ве́ліє дерзнове́ніє ко Го́споду, потщи́ся Богоприя́тним твої́м хода́тайством іспроси́ти у Царя́ ца́рствующих і Го́спода госпо́дствующих, я́ко да проба́вить вели́кия і бога́тия ми́лости Своя́ на нас грі́шних, да пода́сть нам дух пра́вия ві́ри, дух ві́дінія і любве́, дух ми́ра і ра́дости о Ду́сі Свя́те, да ізба́вить от бід і напа́стей, да низпосле́ть вся поле́зная ко спасе́нію душ на́ших. Всім же правосла́вним да низпосле́ть мир, тишину́, безм'яте́жіє, усе́рдіє к ісполне́нію за́повідей Єго́, ізоби́ліє плодо́в земни́х; да ізба́вить всю Українськую страну́ от гла́да, тру́са, пото́па, огня́, меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні, смертоно́сния я́зви і от вся́каго зла. Єй, уго́дниче Бо́жий! Не пре́зри моле́ній на́ших, но усли́ши нас моля́щихся тебі́, і под кро́вом заступле́нія твоєго́ сохрани́ нас (і оби́тель сію́) ненаві́тни от враго́во ви́димих і неви́димих, да сподо́бимся сконча́ти житіє́ на́ше в покая́нії і воспри́ймем ві́чная блага́я во ца́рствії Христа́ Бо́га на́шего, іді́же восхва́лим с тобо́ю і всі́ми святи́ми достопокланя́ємоє і́м'я Пресвяти́я Тро́йці, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Агапіту Печерському, лікарю безмездному","e":"Prayer to St Agapetus of the Caves, the Unmercenary Physician","secs":[{"h":"Тропар, глас 5","ps":["Богоно́снаго Анто́нія ревну́я смиренному́дрію, / а́ки ні́киїм врачество́м зе́лієм сні́дним / ісціля́л єси́ боля́щия, преподо́бне Ага́пите, / тім і врача́ неві́рна уві́рив, / наста́вил єси́ на путь спасе́нія. / Уврачу́й і на́ша болі́зні // і моли́ся Го́сподеві о воспіва́ющих тя."]},{"h":"Кондак, глас 6","ps":["Врач сий ізря́ден, чу́дне, / явля́я несумне́нную твою́ ві́ру, / облича́я же армени́ново неві́ріє / і приводя́ єго́ к благоче́стію, / себі́, близ сме́рти би́вшу, / іспроси́л єси́ от Бо́га продолже́ніє живота́ / і, сим чу́дом того́ уві́рив, / приве́л єси́ Христо́ві, / Єму́же во весе́лії предстоя́, // моли́ся о нас, преподо́бне."]},{"h":"Молитва","ps":["О всеблаже́нне Ага́пите, земни́й А́нгеле і Небе́сний челові́че! Припа́даєм к тебі́ с ві́рою і любо́вію і мо́лим ті ся прилі́жно: яви́ нам смире́нним і грі́шним свято́є своє́ заступле́ніє; се бо гріх ра́ди на́ших не і́мами свобо́дни чад Бо́жиїх проси́ти о потре́бах на́ших Го́спода і Влади́ку на́шего, но тебі́, моли́твенника благоприя́тнаго, к Нему́ предлага́єм і про́сим тя со усе́рдієм мно́гим: іспроси́ нам от бла́гости Єго́ благопотре́бная дари́ душа́м і тілесе́м на́шим, ві́ру пра́ву, любо́в ко всім нелицемі́рну, в злострада́ніїх терпі́ніє, тя́жкими болі́знями одержи́мим — от неду́гов ісціле́ніє, под бре́менем скорбе́й і напа́стей неудобоноси́мих падаю́щих і житія́ своєго́ отча́явшихся твої́ми моли́твами получи́ти ско́роє облегче́ніє і ізбавле́ніє. Не забу́ди, блаже́нне о́тче, і оби́тель сію́ святу́ю, при́сно тя чту́щую, но соблюди́ ю і всіх живу́щих і подвиза́ющихся в ней і на поклоне́ніє в ню приходя́щих невреди́мими от іскуше́ній дия́вольських і вся́каго зла. Єгда́ же приспі́єть на́ше от вре́меннаго сего́ житія́ отше́ствіє, і к ві́чності преселе́ніє, не лиши́ нас по́мощі твоєя́ Небе́сния, но моли́твами твої́ми всіх нас приведи́ в приста́нище спасе́нія і наслі́дники яви́ нас би́ти всесві́тлаго Ца́рствія Христо́ва, да поє́м і сла́вим неізрече́нния щедро́ти Человіколю́бця Бо́га Отця́ і Си́на і Свята́го Ду́ха і твоє́ вку́пі с преподо́бними Анто́нієм і Феодо́сієм оте́чеськоє заступле́ніє во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва блаженній Ксенії Петербурзькій, Христа ради юродивій","e":"Prayer to Blessed Xenia of Petersburg, Fool for Christ","secs":[{"h":"Тропар, глас 7","ps":["Нищету́ Христо́ву возлюби́вши, / безсме́ртния трапе́зи ни́ні наслажда́єшися, / безу́мієм мни́мим безу́міє ми́ра обличи́вши, / смире́нієм кре́стним си́лу Бо́жию восприя́ла єси́. / Сего́ ра́ди дар чудоді́йственния по́мощі стяжа́вшая, / Ксе́ніє блаже́нная, моли́ Христа́ Бо́га // ізба́витися нам от вся́каго зла покая́нієм."]},{"h":"Кондак, глас 3","ps":["Днесь сві́тло лику́єть град свята́го Петра́, / я́ко мно́жество скорб'я́щих обріта́ють утіше́ніє, / на твоя́ моли́тви наді́ющеся, / Ксе́ніє всеблаже́нная, // ти бо єси́ гра́ду сему́ похвало́ і утвержде́ніє."]},{"h":"Інший кондак, глас 3","ps":["На землі́ я́ко стра́нна преби́вши, / о небе́снім же оте́чествії воздиха́ющи, / юро́да от бу́їїх і неві́рних, / прему́дра же і свя́та от ві́рних познава́єшися, / і от Бо́га сла́вою і че́стію вінча́єшися, / Ксе́ніє мужеу́мная і богоу́мная, / сего́ ра́ди зове́м ті: // ра́дуйся, я́ко по стра́нствії земні́м в дому́ О́тчем водворя́єшися."]},{"h":"Молитва перша","ps":["О свята́я блаже́нная ма́ти Ксе́ніє! Под кро́вом Всеви́шняго жи́вшая, відо́мая і укрепля́ємая Богома́терію, глад і жа́жду, хлад і зной, поноше́нія і гоне́нія претерпі́вшая, дар прозо́рливости і чудотворе́нія от Бо́га получи́вшая і под се́нью Всемогу́щего упоко́ївшаяся, днесь же, от сла́внаго тисящеле́тія Креще́нія Русі́, Це́рков Українськая, прославля́єть тя, я́ко благоуха́нний цвіт. Предстоя́ще на мі́сті твоєго́ погребе́нія, пред о́бразом твої́м святи́м, я́ко живі́й ті, су́щей с на́ми, мо́лимся ті: прийми́ проше́нія на́ша і принеси́ я ко Престо́лу милосе́рднаго Отця́ Небе́снаго, я́ко дерзнове́ніє к Нему́ іму́щая; іспроси́ притека́ющим к тебі́ ві́чноє спасе́ніє, на блага́я діла́ і начина́нія на́ша ще́дроє благослове́ніє, от вся́ких бід і скорбе́й ізбавле́ніє. Предста́ни святи́ми твої́ми моли́твами пред Всеми́лостивим Спаси́телем на́шим о нас, недосто́йних і грі́шних. Помози́, свята́я блаже́нная ма́ти Ксе́ніє, младе́нці сві́том свята́го Креще́нія озари́ти і печа́тію да́ра Ду́ха Свята́го запечатлі́ти, ю́ния во ві́рі, че́стности, богобоя́зненности і цілому́дрії воспита́ти і успе́хи в уче́нії їм стяжа́ти. Боля́щия і неду́гующия ісціли́, супру́гом любо́в і согла́сіє ниспосли́, мона́шествующих по́двигом до́брим подвиза́тися помози́ і от поноше́нія огради́, па́стирі в крі́пості ду́ха утверди́, Це́рков і страну́ на́шу сохрани́, і всіх боголюби́вих чад в предсме́ртний час причаще́нія Святи́х Христо́вих Та́їн сподо́би, ти бо єси́ на́ше ско́роє усли́шаніє і ізбавле́ніє, тебі́ благодаре́ніє воссила́єм і с тобо́ю сла́вим Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О пресла́вная свята́я блаже́нная ма́ти на́ша Ксе́ніє, те́плая о нас пред Бо́гом моли́твеннице! Я́коже пре́жде к надгро́бію твоєму́ припа́давшії, си́це ни́ні і ми по прославле́нії твоє́м к моще́м твої́м прибіга́юще, про́сим: помоли́ся Го́споду, да освяти́ть на́ші ду́ші і тілеса́, да просвіти́ть ум, очи́стить со́вість от вся́кия скве́рни, нечи́стих помисло́в, лука́вих і ху́льних умишле́ній і от вся́каго превозноше́нія, го́рдості же і киче́нія, високоу́мія же і де́рзости, от вся́каго фарисе́йськаго лицемі́рія, і от вся́каго сту́днаго і лука́ваго оби́чія на́шего; да да́руєть нам і́скреннєє покая́ніє, сокруше́ніє серде́ць на́ших, смиренному́дріє, кро́тость же і ти́хость, благогові́ніє, ра́зум же духо́вний со вся́ким благоразу́мієм і благодаре́нієм. Утаї́вшая себе́ от му́дрих ві́ка сего́, но Бо́гу зна́ємая, іспроси́ же страні́ на́шей Українській от бід лю́тих ізбавле́ніє, всего́ на́шего житія́ обновле́ніє і ісправле́ніє, соблюди́ нас во вся́ком благочести́вом правосла́вном іспові́данії ві́ри христия́нськия, я́ко да ублажа́юще тя сподо́бимся во вся дні воспіва́ти, благодари́ти і сла́вити Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную, Животворя́щую і Неразді́льную во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О свята́я уго́дниця Бо́жия блаже́нная Ксе́нія! При́зри ми́лостиво твої́м о́ком на нас, раб Бо́жиїх (імена́), честно́й твоє́й іко́ні уми́льно моля́щієся і прося́щиє у тебе́ по́мощі і заступле́нія. Простри́ ко Го́споду Бо́гу на́шему те́плия твоя́ моли́тви і іспроси́ душа́м на́шим оставле́ніє прегріше́ній. Се бо ми се́рдцем сокруше́нним, і ду́хом смире́нним тебі́ хода́таїцю ми́лостивую ко Влади́ці і моли́твенницю за ни, грі́шния, призива́єм, я́ко ти прия́ла єси́ от Него́ благода́ть моли́тися за ни і от бід ізбавля́ти. Тебе́ у́бо про́сим, не пре́зри нас недосто́йних, моля́щихся тебі́ і твоє́й по́мощі тре́бующих, і ісхода́тайствуй всім вся ко спасе́нію поле́зная, я́ко да твої́ми ко Го́споду Бо́гу моли́твами получи́вши благода́ть і ми́лость просла́вим всіх благи́х Істо́чника і Даропода́теля і Бо́га Єди́наго, в Тро́йці Святі́й сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я блаже́нная ма́ти Ксе́ніє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Молитва святителю Луці (Войно-Ясенецькому) Кримському","e":"Prayer to St Luke (Voyno-Yasenetsky) of Crimea","secs":[{"h":"Тропар, глас 1","ps":["Возвісти́телю путі́ спаси́тельнаго, / іспові́дниче непоколеби́мий, / і́стинний храни́телю оте́чеських преда́ній, / Правосла́вія наста́вниче, / Кри́мськия землі́ архіпа́стирю, / врачу́ богому́дрий, святи́телю Луко́, / Христа́ Спа́са непреста́нно моли́, / дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 1","ps":["Я́коже звізда́ всесві́тлая, доброді́тельми сія́ющи, / бил єси́, святи́телю, / ду́шу же равноа́нгельну сотвори́, / сего́ ра́ди святи́тельства са́ном поче́ться, / во ізгна́нії же от безбо́жних мно́го пострада́, / і непоколеби́м ві́рою преби́в, / враче́бною му́дростію мно́гія ісціли́л єси́. / Ті́мже ни́ні честно́є ті́ло твоє́ от землени́х нідр обрі́тенноє ди́вно Госпо́дь просла́ви, / да всі ві́рнії вопіє́м ті: / ра́дуйся, о́тче святи́телю Луко́, // землі́ Кри́мськия похвало́ і утвержде́ніє."]},{"h":"Молитва","ps":["О, всеблаже́нний іспові́дниче, святи́телю о́тче наш Луко́, припа́дая к тебі́, я́коже ча́да отця́ мо́лим тя: усли́ши нас грі́шних і принеси́ моли́тву на́шу к ми́лостивому і человіколюби́вому Го́споду, Єму́ же ти ни́ні в ра́дості святи́х і с ли́ки а́нгел предстої́ши. Іспроси́ у Христа́ Бо́га на́шего да утверди́ть чад Свої́х в ду́хі пра́вия ві́ри і благоче́стія. Всім нам пода́й дар коєму́ждо благопотре́бен, і вся я́же к жи́зні вре́менній і к ві́чному спасе́нію поле́зная. Скорб'я́щим утіше́ніє, недугующим ісціле́ніє, заблудшим на путь і́стини возвраще́ніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, си́рим і убо́гим по́мощ і заступле́ніє. Пода́ждь нам твоє́ благослове́ніє, да ізба́вимся от ко́зней лука́ваго і ізбі́гнем вся́кия вражди́ і нестроє́ній, єресе́й і раско́лов. Наста́ви нас на путь спасе́нія і моли́ о нас Бо́га, во ві́чній жи́зні да сподо́бимся с тобо́ю непреста́нно сла́вити Єдиносу́щную і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха. Єму́ же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["О всеблаже́нний іспові́дниче, святи́телю о́тче наш Луко́, вели́кий уго́дниче Христо́в. Со умиле́нієм прикло́ньше колі́на серде́ць на́ших, і припа́дая к ра́ці честни́х і многоціле́бних моще́й твої́х, я́коже ча́да отця́ мо́лим тя всеусе́рдно: усли́ши нас грі́шних і принеси́ моли́тву на́шу к ми́лостивому і человіколюби́вому Бо́гу, Єму́же ти ни́ні в ра́дості святи́х і с ли́ки а́нгел предстої́ши. Ві́руєм бо, я́ко ти лю́биши ни то́ю же любо́вію є́юже вся бли́жнія возлюби́л єси́, пребива́я на землі́. Іспроси́ у Христа́ Бо́га на́шего да утверди́ть чад Свої́х в ду́хі пра́вия ві́ри і благоче́стія: па́стирям да дасть святу́ю ре́вность і попече́ніє о спасе́нії вві́ренних їм люде́й: пра́во верующия соблюда́ти, слабиє і немощни́я во ві́рі укріпля́ти, неведущия наставля́ти, проти́вния облича́ти. Всім нам пода́й дар коєму́ждо благопотре́бен, і вся я́же к жи́зні вре́менній і к ві́чному спасе́нію поле́зная. Градо́в на́ших утвержде́ніє, землі́ плодоно́сіє, от гла́да і па́губи ізбавле́ніє. Скорб'я́щим утіше́ніє, недугующим ісціле́ніє, заблудшим на путь і́стини возвраще́ніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, си́рим і убо́гим по́мощ і заступле́ніє. Пода́ждь нам всім твоє́ архипа́стирськоє благослове́ніє, да таково́є моли́твенноє хода́тайство іму́щи, ізба́вимся от ко́зней лука́ваго і ізбі́гнем вся́кия вражди́ і нестроє́ній, єресе́й і раско́лов. Наста́ви нас на путь веду́щий в селе́нія пра́ведних і моли́ о нас всеси́льнаго Бо́га, во ві́чній жи́зні сподо́бимся с тобо́ю непреста́нно сла́вити Єдиносу́щную і Неразді́льную Тро́йцю, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва святителю Питириму, єпископу Тамбовському","e":"Prayer to St Pitirim, Bishop of Tambov","secs":[{"h":"Тропар, глас 4","ps":["Ві́ри і благоче́стія наста́вниче, / Це́ркве світи́льниче, мона́шествующих о́бразе, / святи́телю Питири́ме прему́дре, / ста́до твоє́ благоче́стно упа́сл єси́ / і ко Христу́ приве́л єси́; / ті́мже во ви́шніх вінце́м сла́ви украше́н, / с на́ми на землі́ ду́хом пребива́єши, сія́я чудеси́. / Моли́ Христа́ Бо́га, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Мона́хов наста́вника ізря́дна / і святи́теля всім лю́дем ми́лостива, / чудотво́рця преди́вна і моли́твенника о нас неуси́пна, / соше́дшеся воспої́м Питири́ма, // Тамбо́вськия землі́ похвалу́."]},{"h":"Молитва перша","ps":["Благослове́н і препросла́влен Госпо́дь Бог, призва́вий тя, святи́телю о́тче наш Питири́ме, от пе́рваго часа́ ді́лателя во виногра́д Свой, яви́вий в тебі́ послуша́ніє во́лі Єго́ неукло́нноє, ре́вность Предте́чеву і любо́в Па́влову, та́же і на сві́щник Це́ркве Тамбо́вськия тя поста́вивий і архієре́я вели́ка тя показа́вий. Благода́тію святи́тельства укріпля́єм і огне́м любве́ Христо́ви распаля́єм, не дал єси́, па́стирю наш до́брий, сна очи́ма твої́ма, ніже́ ві́ждома дрема́нія, на всяк день тружда́яся, моля́ся і благовіству́я, неві́рния просвіща́я, заблу́дшия вразумля́я, па́дшия восставля́я, немощни́я укріпля́я, пла́чущия утіша́я, всім бив вся, я́ко же святи́й Па́вел, да вся́ко ні́кия спасе́ши. Єгда́ же вре́м'я ді́ланія твоєго́ во вертогра́ді во́лю Влади́ки Христа́ іспо́лнися і отше́л єси́ от земни́х в селе́нія го́рняя прия́ти мзду трудо́в твої́х, даде́ся ті, уго́дниче Бо́жий, Престо́лу Царя́ сла́ви с ли́ки святи́х предстоя́ти і отту́ду па́ству твою́ назира́ти, за ни грі́шния моли́тися, не́мощі немощни́х носи́ти, неду́ги ціли́ти, ско́рби утоля́ти. Сего́ ра́ди от дне блаже́ннаго успе́нія твоєго́ ві́рнії не преста́ша притека́ти к тебі́ в ско́рбіх і болі́зніх, і о́нії прикоснове́ннем ри́зи твоя́, о́нії от води́ із кла́дезя твоєго́ ізбавле́ніє улуча́ху. Ті́мже і ни́ні, к цільбоно́сному гро́бу твоєму́ соше́дшеся, сла́вим Бо́га, ди́внаго во святи́х Свої́х, і тебі́, о́тче свяще́ннійший, велича́єм і мо́лим: не отступа́й от нас любо́вію твоє́ю, сохраня́й моли́твами твої́ми Це́рков Правосла́вную нези́блему от неві́рія і раско́ла, страну́ же Українськую от бід і напа́стей защити́, мир і безм'яте́жіє той да́руя, от вся́ких враго́в огради́, па́стирем Це́ркве Святи́я благопоспіши́, діла́ рук їх іспра́ви і ре́вностію о спасе́нії вруче́ннаго їм слове́снаго ста́да сердця́ їх распали́, вся же ни в послуша́нії спаси́тельному благові́стію Христо́ву соблюди́ і ді́ло спасе́нія, я́ко єди́но на потре́бу вміня́ти помози́, да ку́пно с тобо́ю єди́ними усти́ і єди́ним се́рдцем вся на всяк день і час поє́м і сла́вим Спа́са Христа́ со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче, святи́телю Питири́ме! К тебі́ смире́нно припа́даєм і усе́рдно мо́лимся: яви́ нам, грі́шним, любо́в твою́ оте́чеськую і многомо́щноє твоє́ заступле́ніє. Ві́руєм бо, я́ко ве́ліє дерзнове́ніє і́маши ко Го́споду і я́ко мно́го мо́жеть предста́тельство твоє́ пред Престо́лом бла́гости Єго́. Сохрани́ моли́твами твої́ми Це́рков Святу́ю от єресе́й і раско́лов, от суєві́рія і неві́рія, іспроси́ нам ві́ру пра́ву, наде́жду несомні́нну, любо́в нелицемі́рну, в до́брих ді́ліх преспі́яніє, во іскуше́ніїх му́жество, в злострада́ніїх терпі́ніє, в моли́твах постоя́нство, мир і благоустроє́ніє страні́ на́шей, здра́віє же і спасе́ніє лю́дем єя́. При́зри ми́лостиво на предстоя́щия і моля́щіяся пред свято́ю іко́ною твоє́ю, і вся проше́нія їх во бла́го іспо́лни, і всім вся в жи́зні вре́менній і ві́чній потре́бная да́руй, во сла́ву ди́внаго во святи́х свої́х Бо́га, в Тро́йці сла́вимаго і покланя́ємаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Нилу Селигерському, Столобенському чудотворцю","e":"Prayer to St Nilus of Stolobny, the Wonderworker of Seliger","secs":[{"h":"Тропар, глас 4","ps":["Я́ко світи́льник всесві́тел, / яви́лся єси́ во о́строві Селиге́ра є́зера, / преподо́бне о́тче Ни́ле, / ти бо крест Христо́в от ю́ности своєя́ на ра́мо взем, / усе́рдно Тому́ послі́довал єси́, / чистото́ю Бо́гові прибли́жився, / отону́дуже і чуде́с дарова́нієм обогати́лся єси́. / Тім і ми, притека́юще к ра́ці моще́й твої́х, уми́льно глаго́лем: / о́тче преподо́бне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Оте́чества, преподо́бне, удали́вся, / в пусти́ню всели́лся єси́, / і на о́стров Селиге́ра є́зера возше́д, / жесто́ко житіє́ показа́л єси́, / і, мно́гих доброді́тельми удиви́в, / дарова́нія чуде́с от Христа́ прия́л єси́. / Помина́й нас, чту́щих па́м'ять твою́, да зове́м ті: // ра́дуйся, Ни́ле о́тче наш."]},{"h":"Молитва перша","ps":["О вели́кий уго́дниче, пресла́вний чудотво́рче, собра́нного зді о тебі́ ста́да Христо́ва бо́дрий па́стирю і оби́телі сея́ Бо́гом да́нний нача́льниче, Ни́ле всеблаже́нне! Душе́ю на небесі́ Престо́лу Бо́жию предстоя́й і Тро́їчния сла́ви наслажда́яйся, ті́лом же на землі́ в Боже́ственном хра́мі сем почива́яй і от него́ да́нною ті сви́ше благода́тію разли́чная істоча́яй чудеса́, при́зри ми́лостивим о́ком на предстоя́щия честні́й твоє́й ра́ці лю́ди і прося́щия си́льния твоєя́ по́мощі. Се бо ми в безмі́рних согріше́ніях оскверни́вшіїся і в ти́ні страсте́й при́сно валя́ющіїся, пра́ведний гнів Бо́жий на себі́ наведо́хом і вся́кия ми́лости недосто́йни сотвори́хомся; ті́мже і не смі́юще возвісти́ оче́с на́ших к висоті́ небе́сній, ніже́ вознести́ моле́бний глас, се́рдцем сокруше́нним і ду́хом смире́нним тебі́ в хода́тайство і посо́біє призива́єм. Ти у́бо, я́ко стяжа́вий дерзнове́ніє, воздви́гни го́ре преподо́бния твоя́ ру́ці, я́коже іногда́ чу́дний о́ний Мойсе́й Богови́дець Амали́ка побіжда́яй, і просте́р ко Го́споду Творцю́ всіх і Бо́гу те́плую свою́ моли́тву, іспроси́ Це́ркві благостоя́ніє, возду́ха благорастворе́ніє, землі́ плодоно́сіє. Ізба́ви же всіх, ві́рою несумні́нною к Бо́гу приходя́щих і многоціле́бния мо́щі твоя́ благогові́йно почита́ющих, от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і прило́гов дия́вольських. Бу́ди печа́льним уті́шитель, неду́гующим врач, напа́ствуємим помо́щник, наги́м покрови́тель, вдови́цям засту́пник, си́рим защи́тник, младе́нцем пита́тель, ста́рим укріпи́тель, стра́нствующим путево́ждь, пла́вающим ко́рмчий і ісхода́тайствуй всім, крі́пкия по́мощі твоєя́ усе́рдні тре́бующим, вся я́же ко спасе́нію поле́зная. Я́ко да твої́ми моли́твами наставля́ємі, путь на землі́ маловре́меннаго житія́ на́шего безбі́дні соверши́м, улучи́м же на небесі́ несконча́ємий поко́й і просла́вим ку́пно с тобо́ю всіх благи́х Да́теля, єди́наго в Тро́йці сла́вимаго Бо́га Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга (перед гробницею преподобного)","ps":["О преподо́бне і богоблаже́нне, па́стирю і нача́льниче, о́тче Ни́ле! Ти у́бо, я́ко імі́я ко Влади́ці Христу́ дерзнове́ніє і ко Пречи́стій Єго́ Ма́тері, Пресвято́й Богоро́дице, бу́ди моли́твенник і помо́щник і хода́тай о нас, недосто́йних рабі́х твої́х, живу́щих во святі́й оби́телі сей, є́йже ти нача́льник богоізбра́нной дружи́ні бра́тству сему́, і о приходя́щих с ві́рою к цільбоно́сним моще́м твої́м. Бу́ди помога́я і заступа́я от зла́го на́шего сопроти́вника, я́ко, да твої́ми моли́твами пребива́ющії на мі́сті сем і приходя́щії с ві́рою к ра́ці моще́й твої́х і на вся́ком мі́сті призива́ющії тя на по́мощ невреди́ми бу́дем от бісо́в і злих челові́к, сла́ву і благодаре́ніє возсила́юще Отцю́, Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомучениці Варварі Іліопольській","e":"Prayer to the Great Martyr Barbara of Heliopolis","secs":[{"h":"Тропар, глас 8","ps":["Варва́ру святу́ю почті́м: / вра́жія бо сі́ті сокруши́, / і я́ко пти́ця ізба́вися от них, // по́мощію і ору́жієм Креста́, всечестна́я."]},{"h":"Інший тропар, глас 4","ps":["А́гнице всеблаже́нная Варва́ро, / Боже́ственні озари́вшися Сві́том Святи́я Тро́йці Трисо́лнечним / і в купі́лі утверди́вшися, / в побіжде́ніє ле́сти оте́чеськия / ві́ру іспові́дала єси́ Христо́ву. / Тім, всечестна́я, сви́ше благода́ть тебі́ дарова́ Бог / ісціля́ти неду́ги і болі́зні вся. / Єго́же моли́, великому́ченице, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["В Тро́йці благоче́стно піва́ємому, / послі́довавши Бо́гу, страстоте́рпице, / і́дольськая притупи́ла єси́ чти́лища; / посреді́ же по́двига страда́льчествующи, Варва́ро, / мучи́телей преще́нія не устраши́лася єси́, мужему́дренная, / велегла́сно пою́щи при́сно: // Тро́йцю чту, Єди́но Божество́."]},{"h":"Молитва перша","ps":["Свята́я сла́вная і всехва́льная великому́ченице Варва́ро! Со́браннії днесь в хра́мі твоє́м Боже́ственном лю́ди, ра́ці моще́й твої́х поклоня́ющіїся і любо́вію цілу́ющії, страда́нія же твоя́ му́ченичеськая, і в них само́го Страстополо́жника Христа́, да́вшаго тебі́ не то́чію є́же в Него́ ві́ровати, но і є́же по Нем страда́ти, похвала́ми ублажа́юще, мо́лим тя, ізві́стная жела́нія на́шего хода́тайце: моли́ с на́ми і о нас, умоля́ємаго от Своєго́ благоутро́бія Бо́га, да ми́лостивно усли́шить нас, прося́щих Єго́ благости́ню, і не отста́вить от нас вся ко спасе́нію і житію́ ну́жная проше́нія, і да́руєть христия́нськую кончи́ну животу́ на́шему — безболі́зненну, непости́дну, ми́рну, Боже́ственних Тайн прича́стну, і всім, на вся́ком мі́сті, во вся́кой ско́рби і обстоя́нії тре́бующим Єго́ человіколю́бія і по́мощі, вели́кую Свою́ пода́сть ми́лость, да благода́тію Бо́жиєю і твої́м те́плим предста́тельством, душе́ю і ті́лом всегда́ здра́ві пребива́юще, сла́вим ди́внаго во святи́х Свої́х Бо́га Ізра́їлева, не удаля́ющаго по́мощі Своєя́ от нас всегда́, ни́ні і при́сно, і во ві́ки віко́в, амі́нь."]},{"h":"Молитва друга","ps":["Прему́драя і всекра́сная свята́я великому́ченице Христо́ва Варва́ро! Блаже́нна єси́, я́ко Преми́рная му́дрость Бо́жия плоть і кров не яви́ тебі́, но Сам Бог Оте́ць Небе́сний, І́же тебе́, ві́ри ра́ди от неві́рнаго отця́ оста́вленную, ізгна́нную і умерщвле́нную, в дщер Себі́ возлю́бленную прия́т; за тлі́нноє земна́го імі́нія наслі́діє пло́ті нетлі́ніє дарова́; труди́ му́ченичеськія упокоє́нієм Небе́снаго ізміни́ Ца́рствія; вре́менноє твоє́ житіє́, сме́ртію Єго́ ра́ди пресіче́нноє, сицево́ю воспросла́ви по́честію, я́ко ду́шу с ли́ки Небе́сних вчини́ духо́в, ті́ло же, на землі́ в хра́мі їх а́нгельськом положе́нноє, а́нгелом запові́да сохрани́ти ці́ло, че́стно і многочуде́сно. Блаже́нна єси́, Христу́ Си́ну Бо́жию, Жениху́ Небе́сному, уневе́щанная Ді́во, Єго́же добро́ти твоєя́ Рачи́теля імі́ти жела́ющи, всю себе́ страда́нієм, ра́нами, удо́в рі́занієм і са́мия глави́ усіче́нієм, а́ки тва́рми дража́йшими, потща́лася єси́ украси́ти: да та́ко, я́ко жена́, ві́рна главі́ своє́й — му́жу, Христу́ ду́хом і ті́лом соєдини́шися неразлу́чно, глаго́лющи: обріто́х, Єго́же возлюби́ душа́ моя́, удіржа́х Єго́ і не оста́вих Єго́. Блаже́нна єси́, я́ко Святи́й Дух на тебі́ почи́л єсть, і́мже духо́вними духо́вная разсужда́ти нау́чена, вся ду́хи лука́вствія во і́доліх я́ко па́губния отри́нула єси́ і Єди́наго Бо́га Ду́ха позна́вши, я́ко і́стинная покло́нниця, ду́хом і і́стиною кла́нятися ізво́лила єси́, пропові́дничеськи глаго́лющи: “Тро́йцю чту, Єди́но Божество́”. Сію́ Святу́ю Тро́йцю, Ю́же в животі́ і сме́рті іспові́данієм і страда́нієм свої́м просла́вила єси́, умоли́ о мні, предста́тельнице моя́, я́ко да і аз всегда́ тро́йственною ві́ри, любве́ і наде́жди доброді́телію Ту́южде Святу́ю Тро́йцю почита́ю. І́мам світи́льник ві́ри, но пра́зден благи́х діл єле́я: ти, му́драя ді́во, страда́льчеськую плоть твою́, кро́ве іспо́лненную і ра́нами пролива́ющуюся, а́ки світи́льник іму́щая, даждь от єле́я твоєго́, да тім душе́вную мою́ свіщу́ украси́вши, сподо́блюся по тебі́ в Черто́г Небе́сний. Пресе́льник аз єсьм на землі́ і пришле́ць, я́коже всі отці́ мої́; благ ві́чних наслі́днице і блаже́нная ве́чері в Ца́рствії Небе́снім прича́стнице, я́ко в стра́нствії житія́, Трапе́зи Боже́ственния угоще́нія, си́це і во ісхо́ді от ми́ра жела́ємаго сподо́би м'я напу́тствованія; і єгда́ в коне́ць сном сме́рти начну́ усипа́ти, косни́ся тогда́ ізнемога́ющия пло́ті моєя́, я́ко іногда́ А́нгел Ілії́, глаго́лющи: воста́ни, яждь і пий: я́ко да благода́тію Боже́ственних Ті́ла і Кро́ве Тайн укріпле́н прейду́ в крі́пості я́ді тоя́ дале́кий путь сме́рти, да́же до Гори́ Небе́сния: і та́мо, Єго́же ти чрез три окна́ ба́нния пре́жде ві́рою Бо́га Тро́йцю узрі́ла єси́, Сего́ ку́пно с тобо́ю лице́м к лицю́ да удосто́юся ви́діти і сла́вити Єго́ в неконча́ємия ві́ки. Амі́нь."]},{"h":"Молитва третя","ps":["Свята́я великому́ченице Христо́ва Варва́ро! Моли́ с на́ми і о нас, раба́х Бо́жиїх (імена́), умоля́ємаго от Своєго́ милосе́рдія Бо́га, да ми́лостивно усли́шить нас, прося́щих Єго́ благости́ню, і не отста́вить от нас вся ко спасе́нію і житію́ ну́жная проше́нія, христия́нськую же кончи́ну житія́ на́шего безболі́зненну, непости́дну, ми́рну і Боже́ственних Тайн прича́стну да да́руєть, да благода́тію Бо́жиєю і твої́м те́плим предста́тельством, душе́ю і ті́лом всегда́ здра́ві пребива́юще, сла́вим ди́внаго во святи́х Свої́х Бо́га Ізра́їлева, не удаля́ющаго по́мощі Своєя́ от нас, всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученику Трифону Апамейському","e":"Prayer to the Martyr Tryphon of Apamea","secs":[{"h":"Тропар, глас 4","ps":["Му́ченик Твой, Го́споди, Три́фон / во страда́нії своє́м віне́ць прия́т нетлі́нний от Тебе́, Бо́га на́шего: / імі́яй бо крі́пость Твою́, / мучи́телей низложи́, / сокруши́ і де́монов немощни́я де́рзости. / Того́ моли́твами / спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 4","ps":["Пи́щі Боже́ственния, треблаже́нне, / наслажда́яся на Небесі́х неоску́дно, / сла́в'ящих пі́сньми па́м'ять твою́ покри́й / і сохрани́ от вся́кия ну́жди, / отжени́ вредя́щих ни́вам живо́тних, / да тебі́ от любве́ вопіє́м всегда́: / ра́дуйся, Три́фоне, му́чеников укріпле́ніє."]},{"h":"Кондак, глас 8","ps":["Тро́йчеською тве́рдостію / многобо́жіє разруши́л єси́ от коне́ць, всесла́вне, / че́стен во Христі́ бив, і, побіди́в мучи́телі во Христі́ Спаси́телі, / віне́ць прия́л єси́ му́ченичества твоєго́ / і дарова́нія Боже́ственних ісціле́ній, / я́ко непобіди́мь."]},{"h":"Молитва перша","ps":["О святи́й му́чениче Христо́в Три́фоне, ско́рий помо́щниче і всім к тебі́ прибега́ющим і моля́щимся пред святи́м твої́м о́бразом скоропослу́шний предста́телю! Усли́ши ни́ні і на вся́кий час моле́ніє нас, недосто́йних рабо́в твої́х, почита́ющих святу́ю па́м'ять твою́ (во всечестні́м хра́мі сем), і предста́тельствуй о нас пред Го́сподем на вся́ком мі́сті. Ти бо, уго́дниче Христо́в, во вели́ких чудесі́х возсія́вий, істоча́яй цільби́ притека́ющим к тебі́ с ві́рою і су́щия в ско́рбіх челові́ки заступа́яй, сам обіща́лся єси́ пре́жде ісхо́да твоєго́ от житія́ сего́ тлі́ннаго моли́тися за ни ко Го́споду і іспроси́л єси́ у Него́ дар сей: а́ще кто в како́й-ли́бо ну́жді, печа́лі і болі́зні душе́вній іли́ тіле́сній призива́ти на́чнеть свято́є і́м'я твоє́, той да ізба́влен бу́деть от вся́каго прило́га зла́го. І я́коже ти іногда́ дщер царе́ву, в Ри́мі гра́де от дия́вола му́чиму, ісціли́л єси́, си́це і нас от лю́тих єго́ ко́зней сохрани́ во вся дні живота́ на́шего, найпа́че же в день послі́дняго на́шего іздиха́нія предста́тельствуй о нас. Бу́ди нам тогда́ помо́щник і ско́рий прогони́тель лука́вих духо́в, і к Ца́рствію Небе́сному предводи́тель. І іді́же ти ни́ні предстої́ши с ли́ки святи́х у Престо́ла Бо́жия, моли́ Го́спода, да сподо́бит і нас прича́стники би́ти присносу́щнаго весе́лія і ра́дости, да с тобо́ю ку́пно прославля́єм Отця́ і Си́на і Свята́го Уті́шителя Ду́ха во ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́й му́чениче Христо́в Три́фоне, усли́ши ни́ні і на вся́кий час моле́ніє нас, раб Бо́жиїх (імена), і предста́тельствуй о нас пред Го́сподем. Ти ні́когда дщер царе́ву, во гра́ді Ри́мі от дия́вола му́чиму, ісціли́л єси́: си́це і нас от лю́тих єго́ ко́зней сохрани́ во вся дні житія́ на́шего, найпа́че же в день послі́дняго на́шего іздиха́нія предста́тельствуй о нас. Моли́ Го́спода, да сподо́бит і нас прича́стники би́ти присносу́щнаго весе́лія і ра́дости, да с тобо́ю ку́пно удосто́їмся сла́вити Отця́ і Си́на і Свята́го Уті́шителя Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпче святи́й Три́фоне, і чтим честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́."]}],"notes":[]},{"u":"Молитва святителю Спиридону Трімифунтському","e":"Prayer to St Spyridon of Trimythous","secs":[{"h":"Тропар, глас 1","ps":["Собо́ра Пе́рваго показа́лся єси́ побо́рник і чудотво́рець, / Богоно́се Спиридо́не, о́тче наш. / Ті́мже ме́ртву ти во гро́бі возгласи́в, / і змію́ в зла́то претвори́л єси́, / і внегда́ пі́ти тебі́ святи́я моли́тви, / А́нгели, сослужа́щия тебі́, імі́л єси́, свяще́ннійший. / Сла́ва Да́вшему тебі́ крі́пость, / сла́ва Вінча́вшему тя, // сла́ва Ді́йствующему тобо́ю всім ісціле́нія."]},{"h":"Кондак, глас 2","ps":["Любо́вію Христо́вою уязви́вся, свяще́ннійший, / ум впери́в заре́ю ду́ха, / ді́тельним виді́нієм твої́м дія́ніє обрі́л єси́, Богоприя́тне, / же́ртвенник Боже́ственний бив, // прося́ всім Боже́ственнаго сія́нія."]},{"h":"Молитва перша","ps":["О вели́кий і пречу́дний святи́телю Христо́в і чудотво́рче Спиридо́не, Керки́рськая похвало́, всея́ вселе́нния світи́льниче пресві́тлий, те́плий к Бо́гу моли́твенниче і всім к тебі́ прибега́ющим і с ві́рою моля́щимся скоропредста́тельний засту́пниче! Ти ві́ру правосла́вную на Нике́йстім Собо́ре посреді́ отце́в пресла́вно із'ясни́л єси́, ти єди́нство Святи́я Тро́йці чуде́сною си́лою показа́л єси́ і єретико́в до конця́ посрами́л єси́. Усли́ши нас, грі́шних, святи́телю Христо́в, моля́щихся тебі́ і си́льним твої́м предста́тельством у Го́спода ізбави́ нас от вся́каго зла́го обстоя́нія: от гла́да, пото́па, огня́ і смертоно́сния я́зви. Ти бо во вре́менній жи́зні своє́й от всіх сих бі́дствій ізбавля́л єси́ люде́й твої́х: от наше́ствія ага́рян і от гла́да страну́ твою́ сохрани́л єси́, царя́ от неісці́льнаго неду́га ізба́вил і мно́гія грі́шники к покая́нію приве́л єси́, ме́ртвих пресла́вно воскреша́л єси́, за свя́тость же житія́ твоєго́ а́нгели неви́димо в це́ркві пою́щия і сослужа́щия тебі́ імі́л єси́. Си́це у́бо просла́ви тебе́, ві́рнаго Своєго́ раба́, Влади́ка Христо́с, я́ко вся та́йная челові́чеськая дія́нія дарова́ тебі́ разумі́ти і облича́ти непра́ведно живу́щия. Мно́гим в ску́дости і недоста́точестві живу́щим ти усе́рдно помога́л єси́, лю́ди убо́гія ізоби́льно во вре́м'я гла́да напита́л єси́ і і́на мно́га зна́менія си́лою в тебі́ живу́щаго Ду́ха Бо́жия сотвори́л єси́. Си́це і нас не оста́ви, святи́телю Христо́в, помина́й нас, чад свої́х, у Престо́ла Вседержи́теля і умоли́ Го́спода, да пода́сть мно́гих на́ших гріхо́в проще́ніє, безбі́дноє і ми́рноє житіє́ да да́руєть нам, кончи́ни же живота́ непости́дния і ми́рния і блаже́нства ві́чнаго в бу́дущем ві́ці сподо́бит нас, да ви́ну возсила́єм сла́ву і благодаре́ніє Отцю́ і Си́ну і Ду́ху Свято́му, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О всеблаже́нний святи́телю Спиридо́не, вели́кий уго́дниче Христо́в і пресла́вний чудотво́рче! Предстоя́й на Небесі́ Престо́лу Бо́жию с ли́ки а́нгел, при́зри ми́лостивим о́ком на предстоя́щия зді лю́ди і прося́щії си́льния твоєя́ по́мощі. Умоли́ благоутро́біє Человіколю́бця Бо́га, да не осу́дить нас по беззако́ніїм на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й! Іспроси́ нам у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє, землі́ благопло́діє і во всем вся́коє ізоби́ліє і благоде́нствіє, і да не во зло обрати́м блага́я, да́руємая нам от ще́драго Бо́га, но во сла́ву Єго́ і в прославле́ніє твоєго́ заступле́нія! Ізба́ви всіх ві́рою несумні́нною к Бо́гу приходя́щих от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і дия́вольських наві́тов! Бу́ди печа́льним уті́шитель, неду́гующим врач, в напа́стіх помо́щник, наги́м покрови́тель, вдови́цям засту́пник, си́рим защи́тник, младе́нцям пита́тель, ста́рим укріпи́тель, стра́нствующим путево́ждь, пла́вающим ко́рмчий і ісхода́тайствуй всім крі́пкия по́мощі твоєя́ тре́бующим вся, я́же ко спасе́нію поле́зная! Я́ко да, твої́ми моли́твами наставля́ємі і соблюда́єми, дости́гнем во ві́чний поко́й і ку́пно с тобо́ю просла́вим Бо́га, в Тро́йці Святі́й сла́вимаго, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О преблаже́нне святи́телю Спиридо́не! Умоли́ благосе́рдіє Человіколю́бця Бо́га, да не осу́дить нас по беззако́нієм на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й. Іспроси́ нам, раба́м Бо́жиїм (ім’я), у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє. Ізба́ви нас от вся́ких бід душе́вних і тіле́сних, от всіх томле́ній і дия́вольських наві́тов. Помина́й нас у престо́ла Вседержи́теля і умоли́ Го́спода, да пода́сть мно́гих на́ших гріхо́в проще́ніє, безбі́дноє і ми́рноє житіє́, да да́руєть нам, кончи́ни же живота́ непости́дния і ми́рния і блаже́нства ві́чнаго в бу́дущем ві́ці сподо́бит нас, да непреста́нно возсила́єм сла́ву і благодаре́ніє Отцю́ і Си́ну і Ду́ху Свято́му, ни́ні і при́сно і во ві́ки віко́в."]}],"notes":[]},{"u":"Молитва святій мучениці Тетяні","e":"Prayer to the Holy Martyr Tatiana","secs":[{"h":"Тропар, глас 4","ps":["А́гнцю Пречи́стому і Па́стирю послі́дуя, / а́гнице слове́сная Татіа́но / ми́сленних звіре́й не убоя́лася єси́, / но зна́менієм кре́стним вооружи́вшися, / до конця́ тіх низложи́ла єси́, / і вошла́ єси́ в Небе́сную огра́ду, // іді́же пом'яни́ і нас, му́ченице Христо́ва многому́драя."]},{"h":"Інший тропар, глас 4","ps":["Всечестна́я благоче́стія учреди́тельнице, / прехва́льная і всеблаже́нная му́ченице Татіа́но, / сосу́дом ді́вства і чистоти́ яви́вшаяся / і неве́стой Христо́вой наре́кшаяся, / страда́ній кровми́ украси́вшеся, / возлеті́ла єси́ в не́бі в Небе́сний черто́г, // ті́мже чту́щия тя помина́й."]},{"h":"Кондак, глас 4","ps":["Сві́тло во страда́нії твоє́м возсія́ла єси́, страстоте́рпице, / от крове́й твої́х преіспещре́на, / і, я́ко кра́сная голуби́ця, к Небесі́ возлеті́ла єси́, Татіа́но: // ті́мже моли́ при́сно за чту́щия тя."]},{"h":"Молитва перша","ps":["О свята́я му́ченице Татіа́но, прийми́ ни́ні нас, моля́щихся і припа́дающих к свято́й іко́ні твоє́й. Моли́ся о нас, рабі́х Бо́жиїх (імена), да ізба́вимся вся́ких скорбе́й і болі́зней душе́вних і тіле́сних і благоче́стне поживе́м в настоя́щем житії́, і в бу́дущем ві́кі сподо́би нас со всі́ми святи́ми поклоня́тися в Тро́йці сла́вимому Бо́гу, Отцю́ і Си́ну і Свято́му Ду́ху, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О свята́я му́ченице Татіа́но! Неві́сто Сладча́йшаго Жениха́ твоєго́ Христа́, а́гнице А́гнця Боже́ственнаго, голуби́це цілому́дрія! Страда́ньми, я́ко оде́ждами ца́рськими оді́янная, к лико́м небе́сним сопричте́нная, лику́ющая ни́ні во сла́ві ві́чній! От дній млади́х Бо́гу обеща́вшаяся свята́я служи́тельнице Це́ркве, целому́дріє соблю́дшая і па́че всіх благ Го́спода возлюби́вшая! Тебі́ ми мо́лимся і тебі́ ми про́сим: внемли́ проше́нієм на́шим серде́чним, і не отверга́й моле́ній на́ших! Да́руй чистоту́ ті́ла і душі́, вдохни́ любо́в к Боже́ственним і́стинам, на путь доброді́телей веди́ нас, А́нгельськоє охране́ніє іспроси́ у Бо́га нам. На́ші ра́ни і язви́ тіле́сния сотвори́ безболі́зненни, в злострада́нії терпі́ніє да́руй. Гріхо́вния я́зви уврачу́й. Ю́ность на́шу огради́, ста́рость безболі́зненну і безбе́дну да́руй, в сме́ртнім ча́сі помози́! Помина́й на́ші ско́рби, і отраду́ да́руй! Посіти́ нас, су́щих в темни́ці гріха́: на покая́ніє наста́ви ско́ро, возжжи́ пла́мень моли́тви! Не оста́в нас си́рих! Да сла́в'яще страда́нія твоя́, возсила́єм хвалу́ Го́споду сил, всегда́, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святим благовірним князю Петру і княгині Февронії, Муромським","e":"Prayer to Sts Peter and Fevronia, Prince and Princess of Murom","secs":[{"h":"Тропар, глас 8","ps":["Я́ко благочести́ваго ко́рене пречестна́я о́трасль бил єси́, / до́брі во благоче́стії пожи́в, блаже́нне Пе́тре, / та́ко і с супру́жницею твоє́ю прему́дрою Февро́нією, / в ми́рі Бо́гу угоди́вше, і преподо́бних житію́ сподо́бистеся: / с ни́миже молі́теся Го́сподеві, / сохрани́ти без вреда́ Оте́чество ва́ше, // да вас непреста́нно почита́єм."]},{"h":"Кондак, глас 8","ps":["Ми́ра сего́ княже́ніє і сла́ву вре́менну помишля́я, / сего́ ра́ди благоче́стно в ми́рі пожи́л єси́, Пе́тре, / ку́пно і с супру́жницею твоє́ю прему́дрою Февро́нією, / ми́лостинею і моли́твами Бо́гу угоди́вше. / Ті́мже і по сме́рті неразлу́чно во гро́бі лежа́ще, / ісціле́ніє неви́димо подава́єте. / І ни́ні Христу́ молі́теся // сохрани́ти град же і лю́ди, і́же вас сла́в'ящих."]},{"h":"Молитва перша","ps":["О вели́ції уго́дниці Бо́жії і преди́внії чудотво́рці благові́рнії кня́же Пе́тре і княги́не Февро́ніє, гра́да Му́рома предста́телі і храни́тели, і о всіх нас усе́рднії ко Го́споду моли́твенниці! К вам прибіга́єм і вам мо́лимся с упова́нієм крі́пким: принесі́те за нас грі́шних святи́я моли́тви ва́ша ко Го́споду Бо́гу і іспросі́те нам у бла́гости Єго́ вся благопотре́бная душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду бла́гу, любо́в нелицемі́рну, благоче́стіє непоколеби́моє, в до́брих ді́ліх преуспі́яніє, ми́ра умире́ніє, землі́ плодоно́сіє, возду́ха благорастворе́ніє, душа́м і тілесе́м здра́віє і ві́чноє спасе́ніє. Ісхода́тайствуйте у Царя́ Небе́снаго: ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш. Іспросі́те Це́ркві святі́й і всей держа́ві Українській мир, тишину́ і благоустроє́ніє, і всім нам житіє́ благополу́чноє і до́брую христия́нськую кончи́ну. Огради́те оте́чество ва́ше, град Му́ром, і вся гра́ди Українськия от вся́каго зла і вся правові́рния лю́ди, к вам приходя́щия і моще́м покланя́ющіяся, осіні́те благода́тним ді́йством благоприя́тних моли́тв ва́ших, і вся проше́нія їх во бла́го іспо́лніте. Єй, чудотво́рці святі́ї! Не пре́зріте моли́тв на́ших, со умиле́нієм вам возноси́мих, но бу́діте о нас при́снії предста́телі ко Го́споду і сподо́біте нас по́мощію ва́шею свято́ю спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати; да славосло́вим неізрече́нноє человіколю́біє Отця́, і Си́на, і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О уго́дниці Бо́жії, благові́рнії кня́же Пе́тре і княги́не Февро́ніє, к вам прибіга́єм і к вам со упова́нієм крі́пким мо́лимся: вознесі́те о нас, грі́шних (імена), святи́я моли́тви ва́ші ко Го́споду Бо́гу і іспросі́те у бла́гости Єго́ вся благопотре́бная душа́м і тілесе́м на́шим: ві́ру пра́ву, наде́жду бла́гу, любо́в нелицемі́рну, благоче́стіє непоколеби́мо, в до́брих ді́ліх преуспі́яніє. І хода́тайствуйте нам у Царя́ Небе́снаго житіє́ благополу́чноє і до́брую христия́нськую кончи́ну. Єй, чудотво́рці святі́ї! Не пре́зріте моли́тв на́ших, но бу́діте о нас при́снії предста́теліє ко Го́споду, і сподо́біте нас по́мощію ва́шею спасе́ніє ві́чноє получи́ти і Ца́рствіє Небе́сноє унаслі́довати, да славосло́вим неізрече́нноє человіколю́біє Отця́ і Си́на і Свята́го Ду́ха, в Тро́йці покланя́ємаго Бо́га во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомученику Іоанну Новому, Сочавському","e":"Prayer to the Great Martyr John the New of Suceava","secs":[{"h":"Тропар, глас 4","ps":["Житіє́ на землі́ до́брі окормля́я, страда́льче, / ми́лостинями і ча́стими моли́твами і слеза́ми, / па́ки же ко страда́нію му́жеськи устреми́вся, / пе́рськоє обличи́л єси́ нече́стіє. / Ті́мже Це́ркве бил єси́ утвержде́ніє / і христия́н похвало́, // Іоа́нне приснопа́м'ятне."]},{"h":"Кондак, глас 4","ps":["Морську́ю пла́вая пучи́ну ку́плею, / от восто́ка тща́лся єси́ к сі́веру, / но Бо́гу призва́вшу тя, / я́коже Матфе́й ми́тницю, ти же ку́плю оста́вль / і Тому́ послі́довал єси́ кро́вію му́ченія, / вре́менними іскупи́в непроходи́мая, // і віне́ць прия́л єси́ непобіди́мий."]},{"h":"Молитва","ps":["О святи́й уго́дниче Бо́жий, Іоа́нне! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на Небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всеми́лостивому Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і по́мощі нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́кого зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Олександру Свірському","e":"Prayer to St Alexander of Svir","secs":[{"h":"Тропар, глас 4","ps":["От ю́ности, Богому́дре, жела́нієм духо́вним в пусти́ню всели́вся, / єди́наго Христа́ возжела́л єси́ усе́рдно стопа́м в слід ходи́ти, / ті́мже і а́нгельстії чи́ни, зря́ще тя, удиви́шася, / ка́ко, с пло́тію к неви́димим ко́знем подвиза́вся, прему́дре, / побіди́л єси́ полки́ страсте́й воздержа́нієм / і яви́лся єси́ равноа́нгелен на землі́, / Алекса́ндре, преподо́бне, / моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Я́ко многосві́тлая звізда́ днесь в страна́х українських возсія́л єси́, о́тче, / всели́вся в пусти́ню, Христо́вим стопа́м послі́довати усе́рдно возжелі́л єси́ / і, Того́ свято́є і́го на ра́мо твоє́ взем - честни́й крест, / умертви́л єси́ труди́ по́двиг твої́х тіле́сная взигра́нія, / ті́мже вопіє́м ті: / спаси́ ста́до твоє́, є́же собра́л єси́, му́дре, да зове́м ті: // ра́дуйся, преподо́бне Алекса́ндре, о́тче наш."]},{"h":"Молитва перша","ps":["О свяще́нная главо́, а́нгеле земні́й і челові́че Небе́сний, преподо́бне і богоно́сне о́тче наш Алекса́ндре, ізря́дний уго́дниче Пресвяти́я і Єдиносу́щния Тро́йці, явля́й мно́гія ми́лости живу́щим во святі́й оби́телі твоє́й і всім, с ві́рою і любо́вію притека́ющим к тебі́! Іспроси́ нам вся благопотре́бная к житію́ сему́ вре́менному, і ну́жная к ві́чному спасе́нію на́шему. Посо́бствуй предста́тельством твої́м, уго́дниче Бо́жий, пред Го́сподем на враги́ ви́димия і неви́димия. Ві́рних рабо́в Єго́, в ско́рбі і печа́лі день і нощ вопію́щих к Нему́, многоболі́зненний вопль да усли́шить і да ізведе́ть от поги́белі живо́т наш. Да в ми́рі глубо́ці пребу́деть свята́я Правосла́вная Це́рков Христо́ва, і в благостроє́нії зи́ждеться оте́чество на́ше, во вся́ком благоче́стії неруши́мо. Бу́ди всім нам, чудотво́рче святи́й, помо́щник ско́рий во вся́кой ско́рби і обстоя́нії. Найпа́че же в час кончи́ни на́шея яви́ся нам засту́пник благосе́рдий, да не пре́дани бу́дем на мита́рствіх возду́шних вла́сті зло́бнаго мироде́ржця, но да сподо́бимся непреткнове́ннаго восхо́да в Ца́рствіє Небе́сноє. Єй, о́тче, моли́твенниче наш при́сний! Не посрами́ упова́нія на́шего, не пре́зри смире́нная моле́нія на́ша, і предста́тельствуй за нас пред Престо́лом Живонача́льния Тро́йці, да сподо́бимся вку́пі с тобо́ю і со всі́ми святи́ми, ми недосто́йнії, в селе́ніїх ра́йських сла́вити вели́чіє, благода́ть і ми́лость Єди́наго в Тро́йці Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О преподо́бне і богоно́сне о́тче наш Алекса́ндре! Іспроси́ нам вся к житію́ сему́ вре́менному благопотре́бная, па́че же к ві́чному спасе́нію на́шему ну́жная. Бу́ди нам, раба́м Бо́жиїм (імена), чудотво́рче святи́й, во вся́кой ско́рби і обстоя́нії ско́рий помо́щник. Найпа́че же в час кончи́ни на́шея яви́ся нам засту́пник благосе́рдий, да не пре́дани бу́дем на мита́рствах возду́шних вла́сті зло́бнаго мироде́ржця, но да сподо́бимся непреткнове́ннаго восхо́да во Ца́рствіє Небе́сноє. Єй, о́тче, моли́твенниче наш при́сний! Не посрами́ упова́нія на́шего, не пре́зри смире́нних моле́ній на́ших, но при́сно о нас пред Престо́лом Живонача́льния Тро́йці предста́тельствуй, да сподо́бимся вку́пі с тобо́ю і со всі́ми святи́ми, а́ще і недосто́йни єсьми́, в селе́ніїх ра́йських сла́вити вели́чіє, благода́ть і ми́лость Єди́наго в Тро́йці Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва мученицям Вірі, Надії, Любові та матері їхній Софії","e":"Prayer to the Martyrs Faith, Hope, Love and their mother Sophia","secs":[{"h":"Тропар, глас 4","ps":["Торжеству́єть Це́рков перворо́дних, / і свесели́ться приє́мля ма́тер о ча́діх веселя́щуюся, / я́же я́ко му́дрости тезоімени́тая / тро́йственним богосло́вським доброді́телем равночи́сленния породи́. / Ти́я с му́дрими ді́вами зрить уневе́стившіяся Жениху́ Бо́гу Сло́ву, / с не́ю і ми духо́вні в па́м'яті їх свеселі́мся, глаго́люще: / Тро́йці побо́рници, / Ві́ро, Любве́ і Наде́ждо, // во ві́рі, любві́ і наде́жде утвержда́йте нас."]},{"h":"Кондак, глас 1","ps":["Софі́ї честни́я свяще́ннейшия ві́тві, / Ві́ра і Наде́жда і Любо́в, показа́вшеся, / му́дрость обуї́ша є́ллинськую благода́тію, / і пострада́вше, і побідоно́сиці яви́вшеся, // вінце́м нетлі́нним от всіх Влади́ки Христа́ ув'язо́шася."]},{"h":"Молитва перша","ps":["О святи́я і достохва́льния му́ченици Ві́ро, Наде́ждо і Люби́, і до́блестних дще́рей му́драя ма́ти Софі́є, к вам ни́ні притеце́м со усе́рдною моли́твою; что бо па́че возмо́жеть предста́тельствовати за ни пред Го́сподем, а́ще не ві́ра, наде́жда і люби́, три сія́ краєуго́льния доброді́телі, в ни́хже о́браз нарече́нния, са́мою ве́щію ти́я яви́сте! Умолі́те Го́спода, да в ско́рбіх і напа́стіх неізрече́нною благода́тію Своє́ю покри́єть ни, спасе́ть і сохрани́ть, я́ко благ єсть і Человіколю́бець. Того́ сла́ву, я́ко со́лнце незаходи́моє, ни́ні зря́ще светоле́пну, споспішеству́йте нам во смире́нних моле́ніїх на́ших, да прости́ть Госпо́дь Бог гріхи́ і беззако́нія на́ша, і да поми́луєть нас грі́шних і недосто́йних щедро́т Єго́. Молі́те у́бо о нас, святи́я му́ченици, Го́спода на́шего Ісу́са Христа́, Єму́же сла́ву возсила́єм со Безнача́льним Єго́ Отце́м і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О святи́я му́ченици Ві́ро, Наде́ждо і Люби́, і му́драя ма́ти Софі́є! К вам ни́ні со усе́рдною моли́твою притека́єм. Умолі́те у́бо Го́спода, да в ско́рбіх і напа́стіх неізрече́нною благода́тію Своє́ю покри́єть ни, раб Свої́х (імена), і сохрани́ть, і Того́ сла́ву, я́ко со́лнце незаходи́моє, зрі́ти да сподо́бит. Споспішеству́йте нам во смире́нних моле́ніїх на́ших, да прости́ть Госпо́дь Бог гріхи́ і беззако́нія на́ша, і да поми́луєть нас, грі́шних, і щедро́т Свої́х да сподо́бит нас Христо́с Бог, Єму́же сла́ву возсила́єм, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["Вас, святи́я му́ченици, Ві́ро, Наде́ждо і Люби́, сла́вим, велича́єм і ублажа́єм, ку́пно с му́дрою ма́терію Софі́єю, є́йже покланя́ємся, я́ко о́браз богому́драго попече́нія явля́ющей. Умоли́, свята́я Ві́ро, Творця́ ви́димих і неви́димих, да ві́ру крі́пку, небла́зненну і неруши́му пода́сть нам. Хода́тайствуй, свята́я Наде́ждо, пред Го́сподом Ісу́сом за нас грі́шних, да упова́ніє на блага́я Своя́ не отжене́ть от нас, і от вся́кия ско́рби і ну́жди да ізба́вить ни. Іспові́ждь, свята́я Люби́, Ду́ху і́стини, Уті́шителю, напа́сти і печа́лі на́ша, да Той сви́ше сла́дость Небе́сную низпосле́ть душа́м на́шим. Помозі́те у́бо в біда́х на́ших, святи́я му́ченици, і, ку́пно с му́дрою ма́терію ва́шею Софі́єю, молі́те Го́спода Бо́га, да сохрани́ть под покро́вом Свої́м Це́рков Свою́ Святу́ю. Та́кожде і о всіх нас ва́шего те́плаго предста́тельства пред Бо́гом усе́рдно мо́лим, да ку́пно с ва́ми і со всі́ми святи́ми превознесе́м і препосла́вим пресвято́є і вели́коє І́м'я Отця́ і Си́на і Свята́го Ду́ха Бо́га, предві́чнаго Влади́ки і благи́х Соді́теля, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобній Софії Суздальській","e":"Prayer to St Sophia of Suzdal","secs":[{"h":"Тропар, глас 4","ps":["Ви́шняго красото́ю я́вственно украша́яся, / по́стничеськими бо труди́ подвиза́ся преподо́бная Софі́я, / і бисть наслі́дниця Небе́сному Ца́рствію, / і вни́де в Небе́сний Черто́г наслади́тися Христо́ви красоти́, / Єго́ же моли́ спасти́ся гра́ду Су́ждалю / от пога́них нахожде́ній і междоусо́бния бра́ні // і пода́ждь душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 1","ps":["Но́щі стра́стния ізбі́гши, Богому́драя Софі́є преподо́бная, / к Незаходи́мому же Со́лнцю, Христу́, прише́дши, / умертви́ла єси́ плотсько́є мудрова́ніє посто́м же, воздержа́нієм і моли́твами, / показа́ся равна́ а́нгелом, / на землі́ бо поживе́ і ду́хи нечи́стия от челові́к отгна́ла єси́, / і разли́чная ісціле́нія подава́єши, от мно́гих бід і зол ізбавля́єши, / Софі́є преподо́бная, / моли́ спасти́ся душа́м на́шим."]},{"h":"Молитва","ps":["О, прехва́льная і пра́ведная ма́ти Софі́є, Суздальськия страни́ досточу́дная подви́жнице! Сла́вим твоє́ богоуго́дноє житіє́, чтим твоя́ вели́кия доброді́телі, поклоня́ємся честни́м моще́м твої́м, с любо́вію лобиза́єм твой святи́й о́браз і с ві́рою прино́сим тебі́ прилі́жния на́ша моли́тви. Помози́ нам, я́ко странним і прише́льцем в ми́рі сем, ста́ти на і́стинний путь христия́нськаго житія́, не отврати́ лиця́ своєго́ от всіх прибіга́ющих к твоєму́ покровительству, духо́вні умудри́ подвиза́ющихся в і́ночестві позна́ти коєму́ждо о́браз спасе́нія своєя́ душі́, наста́ви в по́двизіх смире́нія, терпі́нія і покая́нія, поспі́шествуй стяжа́ти нам целому́дріє, послуша́ніє і любо́в Бо́жию. Бу́ди щит і огражде́ніє оби́телі сія́ от вся́каго зла, в ней же сама́ ре́вностно подвиза́лася єси́. Обрати́ і вразуми́ заблудшия лю́ди на путь пра́вий. Умоли́ Го́спода сил пощади́ти душі́ на́ша і дарова́ти нам вре́м'я на покая́ніє, да твої́м предста́тельством сподо́бимся безпагубне прейти́ по́прище многоско́рбнаго на́шего земна́го житія́ і би́ти прича́стники ві́чнаго блаже́нства в небе́сних оби́теліх Бо́га і Спа́са на́шего, Єму́ же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва святій преподобномучениці великій княгині Єлисаветі","e":"Prayer to the Holy Venerable Martyr Grand Duchess Elizabeth","secs":[{"h":"Тропар, глас 1","ps":["Смире́нієм досто́їнство княжеськоє сокри́вши, богому́драя Єлисаве́то, сугу́бим служе́нієм Ма́рфи і Марі́ї Христа́ почти́ла єси́. Милосе́рдієм, терпі́нієм і любо́вію себі́ предочи́стивши, я́ко же́ртва пра́ведная Бо́гу принесла́ся єси́. Ми же, чту́ще доброді́тельноє житіє́ і страда́нія твоя́, я́ко і́стинную наста́вницю усе́рдно про́сим тя: свята́я му́ченице Вели́кая княги́не Єлисаве́то, моли́ Христа́ Бо́га спасти́ і просвіти́ти душі́ на́ша."]},{"h":"Кондак, глас 2","ps":["Вели́чіє по́двига ві́ри кто по́вість: во глубині́ землі́, я́ко в раї́ сві́тлости, страстоте́рпиця Вели́кая княги́ня Єлисаве́та со А́нгели во псалмі́х і пі́ніїх ра́довашеся і, убіє́ніє претерпіва́ющи, о безбо́жних мучителіх взива́ше: Го́споди, прости́ їм гріх сей, не ві́дять бо, что творя́ть. Тоя́ моли́твами, Христе́ Бо́же, поми́луй і спаси́ душі́ на́ша."]},{"h":"Молитва","ps":["О святи́я новому́ченици Українськия, Вели́кая Княги́не Єлисаве́то і сестро́ єя́ крестовая пречестна́я іноки́не Варва́ро, ку́пно путь свой во мно́зіх му́ках скончавшия, єва́нгельськия за́повіді ді́лом во оби́телі Милосе́рдія совершившия, ві́ри ра́ди правосла́вния подвиза́ющися до сме́рти в послі́дняя времена́ сія́, і до́брий плод в терпі́нії страсте́й Христу́ принесшия! Молі́теся Єму́, я́ко Побіди́телю сме́рти, да утверди́ть Це́рков Українськую Правосла́вную і Оте́чество на́ше, кро́вію і страда́ньми новому́чеников іскупле́нния, і не дасть в расхище́ніє враго́м України достоя́нія на́шего. Се бо лука́вий враг вооружи́ся на ни, хотя́ нас погуби́ти в междоусо́бних бра́ніх, ско́рбіх, нестерпи́мих печа́ліх, болі́зніх, ну́ждах і біда́х лю́тих. Умолі́те Го́спода низложи́ти вся немощни́я де́рзости їх; ві́ру в сердця́х люде́й українських укріпі́те, да єгда́ на́йдеть на ни іспита́нія час, му́жества дар воспри́ймем ва́шими моли́твами, отве́ргшеся себе́ і взе́мше крест свой, послі́дуєм Христу́, распина́юще плоть свою́ со страстьми́ і похотьми́. Сохрані́те нас от вся́каго зла, освяті́те путі́ жи́зні на́шея, да́руйте покая́ніє нелицемі́рноє, тишину́ і мир душа́м на́шим, іспросі́те у Го́спода всім нам мита́рств го́рких і ві́чния муки́ ізба́витися і Небе́сному Ца́рствію наслі́дники би́ти со всі́ми святи́ми, от ві́ка угоди́вшими Бо́гу, да ра́дующеся воздади́м хвалу́, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва благовірній княгині Анні Кашинській","e":"Prayer to the Right-believing Princess Anna of Kashin","secs":[{"h":"Тропар, глас 3","ps":["Днесь восхваля́єм тя, преподо́бная ма́ти, / вели́кая княги́не і́нокине А́нно: / я́ко бо лоза́ плодови́та посреді́ те́рнія, / процвіла́ єси́ во гра́ді Ка́шині твої́ми доброді́тельми, / і всіх удиви́ла єси́ чу́дним твої́м житіє́м, / ті́мже Христу́ Бо́гу угоди́ла єси́, / і ни́ні, ра́дующися і веселя́щися, / пребива́єши с ли́ки преподо́бних жен, / наслажда́ющися ра́йськия красоти́ і весе́лія. / Мо́лим у́бо тя: / моли́ о нас Человіколю́бця Христа́, Бо́га на́шего // дарова́ти нам мир і ве́лію ми́лость."]},{"h":"Кондак, глас 4","ps":["Я́ко пресві́тлая звізда́, / яви́лася єси́ в Українській землі́, во гра́ді Ка́шині, / преподо́бная ма́ти А́нно, / во всіх благочести́вих і ві́рних жена́х / а́ки крин процві́ла єси́ чи́стим і непоро́чним твої́м житіє́м, / во і́нокинях же соверше́нними твої́ми труди́ і по́двиги, / і возшла́ єси́ к Ви́шнему гра́ду, ра́дующися і веселя́щися, / я́ко до́брі соверши́вши твоє́ тече́ніє, / і ни́ні честни́я твоя́ мо́щі, / а́ки би́серіє драго́є, яви́шася, / на ісціле́ніє всім, приходя́щим с ві́рою. / Тім і вопіє́м ті: / ра́дуйся, всекра́сная душе́ю, / і моли́ Христа́ Бо́га // о спасе́нії душ на́ших."]},{"h":"Молитва","ps":["О преподо́бная і преблаже́нная ма́ти А́нно! Смире́нно припа́дающе к честни́м моще́м твої́м, мо́лимся со слеза́ми прилі́жно: не забу́ди убо́гих твої́х до конця́, но помина́й нас всегда́ во святи́х твої́х і благоприя́тних моли́твах к Бо́гу. О преблаже́нная вели́кая княги́не А́нно! Не забу́ди присіща́ти чад твої́х, а́ще бо ті́лом і преста́вилася єси́ от нас, но і по сме́рті жива́ пребива́єши і не отступа́єши от нас ду́хом, сохраня́ющи нас от стріл вра́жиїх, вся́кия пре́лести бісо́вськия і ко́зней дия́вольських. Моли́твеннице на́ша усе́рдная! Не преста́й моля́щися за ни ко Христу́, Бо́гу на́шему, а́ще бо моще́й твої́х ра́ка пред очи́ма на́шима ви́ну ви́дима єсть, но свята́я душа́ твоя́, со А́нгельськими во́їнстви у Престо́ла Вседержи́теля предстоя́щи, досто́йно весели́ться. К тебі́ у́бо припа́даєм, тебі́ мо́лимся, тебі́ ми́лі ся ді́єм: моли́ся, преблаже́нная А́нно, Всеми́лостивому Бо́гу на́шему о спасе́нії душ на́ших, є́же іспроси́ти нам вре́м'я на покая́ніє і невозбра́нно прейти́ от землі́ на Не́бо, мита́рств го́рких і ві́чния му́ки ізба́витися і Небе́сному Ца́рствію наслі́дником би́ти со всі́ми преподо́бними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́, Єму́же сла́ва, со Безнача́льним Єго́ Отце́м, і с Пресвяти́м, і Благи́м, і Животворя́щим Єго́ Ду́хом, ни́ні, і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бная ма́ти, вели́кая княги́не А́нно, / і чтим святу́ю па́м'ять твою́, / наста́внице іноки́ням / і собесі́днице А́нгелом."]}],"notes":[]},{"u":"Молитва преподобному Макарію, ігумену Калязинському","e":"Prayer to St Macarius, Abbot of Kalyazin","secs":[{"h":"Тропар, глас 8","ps":["Плотська́я мудрова́нія, о́тче Мака́ріє, / воздержа́нієм і бді́нієм умертви́л єси́, / мі́сто бо, на не́мже по́ти твоя́ ізлія́л єси́, / я́ко труба́ вопіє́ть к Бо́гу, / пові́дающи твоя́ ісправле́нія, / і по сме́рті честни́я твоя́ мо́щі істоча́ють ісціле́нія. / Ті́мже вопіє́м ті: / моли́ Христа́ Бо́га, да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Ви́шніх жела́я, воздержа́нієм, і труди́, і по́ти наслади́вся, / жела́ніє пло́ті твоєя́ обузда́в, / чуде́с дар приє́м от Христа́ Бо́га, / світи́льник яви́лся єси́ пресві́тлий. / Ті́мже Христо́ва Це́рков пі́сньми сла́вить тя, / преподо́бне Мака́ріє, о́тче наш."]},{"h":"Молитва","ps":["О свяще́нная главо́, преподо́бне о́тче, преблаже́нне а́вво Мака́ріє! Не забу́ди убо́гих свої́х до конця́, но помина́й нас во святи́х свої́х і благоприя́тних моли́твах к Бо́гу. Пом'яни́ ста́до своє́, є́же сам упа́сл єси́, і не забу́ди посіща́ти чад свої́х. Моли́ за ни, о́тче свяще́нний, за ді́ти своя́ духо́вния, я́ко імі́я дерзнове́ніє к Небе́сному Царю́. Не промолчи́ за ни ко Го́споду, і не пре́зри нас, ві́рою і любо́вію чту́щих тя. Помина́й нас, недосто́йних, у Престо́ла Вседержи́телева, і не преста́й моля́ся о нас ко Христу́ Бо́гу: і́бо дана́ тебі́ бисть благода́ть за ни моли́тися. Не мним бо тя су́ща ме́ртва: а́ще бо і ті́лом преста́вился єси́ от нас, но і по сме́рті жив сий пребива́єши. Не отступа́й от нас ду́хом, сохраня́я нас от стріл вра́жиїх, і вся́кия пре́лести бісо́вськия, і ко́зней дия́вольських, па́стирю наш до́брий. А́ще бо і моще́й твої́х ра́ка пред очи́ма на́шима ви́дима єсть всегда́, но свята́я твоя́ душа́ с а́нгельськими во́їнстви, с безпло́тними ли́ки, с Небе́сними Си́лами у Престо́ла Вседержи́телева предстоя́щи, досто́йно весели́ться. Ві́дуще бо тя воі́стину і по сме́рті жи́ва су́ща, тебі́ припа́даєм і тебі́ мо́лимся: є́же моли́тися о нас Всеси́льному Бо́гу о по́льзі душ на́ших і іспроси́ти вре́м'я на покая́ніє, і о невозбра́нном преі́тії от землі́ на Не́бо, мита́рств же го́рких, бісо́во возду́шних князе́й і ві́чния му́ки ізба́витися, і Небе́сному Ца́рствію наслі́дником би́ти со всі́ми пра́ведними, от ві́ка угоди́вшими Го́споду на́шему Ісу́су Христу́: Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отцо́м, і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва великомучениці Катерині","e":"Prayer to the Great Martyr Catherine","secs":[{"h":"Тропар, глас 4","ps":["Доброді́тельми, я́ко луча́ми со́лнечними, / просвіти́ла єси́ неві́рния мудреці́. / І, я́коже пресві́тлая луна́ ходя́щим в нощі́ / неві́рія тьму отгна́ла єси́, / і цари́цю уві́рила єси́, / вку́пі же і мучи́теля обличи́ла єси́, / Богозва́нная неві́сто блаже́нная Єкатери́но, / жела́нієм востекла́ єси́ в Небе́сний черто́г / к прекра́сному Жениху́ Христу́, / і от Него́ ца́рським вінце́м вінча́лася єси́: / Єму́же, со А́нгели предстоя́щи, / за ни моли́ся, // творя́щия пречестну́ю па́м'ять твою́."]},{"h":"Кондак, глас 2","ps":["Лик честни́й Боже́ственні мучениколю́бці, / воздви́гніте ни́ні, почита́юще всему́друю Єкатери́ну, / сія́ бо в три́знищі Христа́ пропові́да, // і змі́я попра́, ри́торов ра́зуми укроти́вши."]},{"h":"Молитва перша","ps":["О свята́я Єкатери́но, ді́во і му́ченице і́стинная Христо́ва неві́сто! Мо́лим тя чрез особли́вую благода́ть, є́юже предвари́ тя Жени́х твой, Сладча́йший Ісу́с: я́коже посрами́вши пре́лести мучи́теля, му́дростію твоє́ю п'ятдеся́т віті́й побіди́ла єси́ і, напоі́вши їх Небе́сним уче́нієм, к сві́ту і́стинния ві́ри наста́вила єси́, та́ко іспроси́ і нам о́ную Бо́жию му́дрость, да і ми, расто́ргнувше вся ко́зні а́дськаго мучи́теля і презрі́в ми́ра і пло́ті собла́зни, досто́йни яви́мся Боже́ственния сла́ви і к разшире́нію святи́я на́шея правосла́вния ві́ри сосу́ди досто́йни соді́лаємся, і с тобо́ю в Небе́сній ски́нії Го́спода і Влади́ку на́шего Ісу́са Христа́ хва́лим і прославля́єм во вся ві́ки. Амі́нь."]},{"h":"Молитва друга","ps":["О свята́я ді́во і му́ченице Єкатери́ні! Мо́лим тя: при́зри на бі́дствія нас, грі́шних раб Бо́жиїх (імена), сотвори́ нас го́рняя му́дрствовати, а не земна́я. Поспіши́ нам моли́твами твої́ми побіжда́ти плотська́я похоті́нія, к ми́ру пристра́стіє і ко́зні злих духо́в, на нас зло́бно вою́ющих; да твої́м предста́тельством во дні житія́ сего́ свобо́дні яви́мся от вражде́бних їх нападе́ній і по ісхо́ді от возду́шних їх істяза́ній. О прему́драя ді́во! Да́руй нам вся я́же к по́льзі проше́нія, мо́жеши бо мно́гая іспроси́ти у Возлю́бленнаго Жениха́ твоєго́, Христа́ Бо́га на́шего. Ми ві́ми, я́ко мно́го мо́жеть моли́тва пра́веднаго, поспішеству́ємая бла́гостію Милосе́рдаго Бо́га, Єму́же сла́ва, честь і благодаре́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О, свята́я великому́ченице Єкатери́но, ізбра́нний чистоти́ сосу́де, сто́лпе правосла́вія, наде́жная предста́тельнице на́ша, яви́вшая нам сама́ вину́ умоля́ти тя, подви́жнице зако́нная, свята́я на святі́й горі́ свя́то почива́ющая! Мо́лим тя: прини́кши сви́ше, воньми́ гла́су моле́нія на́шего, при́зри на бі́дствіє рабо́в твої́х, просвіти́ омраче́ніє ума́ на́шего, сотвори́ нас го́рняя му́дрствовати, а не земна́я. Поспіши́ нам моли́твами твої́ми побіжда́ти плотська́я похоті́нія, пристра́стія к ми́ру і ко́зні злих духо́в, на нас зло́бно вою́ющих: да твої́м предста́тельством во дні житія́ сего́ свобо́дні бу́дем от вражде́бних їх нападе́ній і по ісхо́ді от возду́шних їх істяза́ній. О, прему́драя ді́во! Да́руй нам вся, я́же к по́льзі проше́нія: мо́жеши бо мно́гая іспроси́ти у возлю́бленнаго Жениха́, Христа́ Бо́га на́шего. Ми ві́ми, я́ко мно́го мо́жеть моли́тва пра́веднаго, поспішеству́ємая благоутро́бієм милосе́рдаго Бо́га, Єму́же сла́ва, честь і благодаре́ніє всегда́, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Феодору Томському","e":"Prayer to the Righteous Theodore of Tomsk","secs":[{"h":"Тропар, глас 4","ps":["Жи́зні светськия пра́ведне Фео́доре удали́вся, в зе́млю сиби́рськую во́льно прийти́ ізво́лив, чудеси́ і зна́меньми Бо́жиїми наро́д Томський удиви́л єси́, і по сме́рті своє́й ві́ру чту́щих тя укріпля́єши. Помина́й нас, чту́щих па́м'ять Твою́, о́тче наш Фео́доре!"]},{"h":"Кондак, глас 4","ps":["Ізбра́нний чудотво́рче і преди́вний уго́дниче Христо́в, ско́рий помо́щниче і моли́твенниче наш, пра́ведне о́тче Фео́доре! Велича́юще прославльшего тя Го́спода, похва́льная воспису́єм ті, к ра́ці моще́й твої́х притека́юще. Ти же, я́ко імі́яй дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́, зову́щих: Ра́дуйся, пра́ведне о́тче наш Фео́доре, те́плий о нас к Бо́гу моли́твенниче."]},{"h":"Молитва","ps":["О пра́ведні о́тче наш Фео́доре! Прийми́ сію́ похва́льную піснь, тебі́ с любо́вію і ві́рою приноси́мую, і ми́лостивно приклони́ся с Небе́сних висо́т, я́ко оте́ць чадолюби́вий, хода́тайствуй ві́рою і любо́вію тя почита́ющим гріхо́в проще́ніє, житія́ ісправле́ніє, кончи́ну христия́нськую ми́рну і ненаві́тну от духо́в зло́би. І предста́ни тогда́, о о́тче, прогоня́я страх сме́ртний от ві́рних твої́х рабо́в і чти́телей твоєя́ священнейшия па́м'яті, безбі́дно творя́ разлуче́ніє душі́ от ті́ла і лю́тих мита́рств прехожде́ніє си́льних твої́м ко Го́споду моле́нієм і предста́тельством, благода́тію, щедро́тами і человіколю́бієм Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́ і Єго́ Пресвятейшия Ма́тері, і твої́м ми́лостивним о нас хода́тайством. Наді́ємся вся сія́ проще́нія получи́ти і в день Страшного Суда́ десного стоя́нія получи́ти со всі́ми угоди́вшими Бо́гу. Амі́нь."]}],"notes":[]},{"u":"Молитва праведному Артемію Веркольському, чудотворцю","e":"Prayer to the Righteous Artemius of Verkola, the Wonderworker","secs":[{"h":"Тропар, глас 2","ps":["Ви́шняго повелі́нієм, / тучено́сним облако́м не́бо помрачи́вшим, / і мо́лніям блиста́ющим, / гро́му же возшумі́вшу с преще́нієм, / іспусти́л єси́ ду́шу твою́ в ру́ці Го́сподеві, / прему́дре Арте́міє, / і ни́ні предстої́ши Престо́лу Влади́ки всіх, / і́же ві́рою і любо́вію приходя́щим к тебі́, / подая́ ісціле́ніє всім неотло́жно, / і моля́ся Христу́ Бо́гу, // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Возсія́ днесь пресві́тлая па́м'ять прему́драго Арте́мія; / Богода́нная благода́ть я́ко рі́ки ізлива́єть от ціле́бних моще́й єго́ ди́вная ісціле́нія, / і́миже от многоразли́чних неду́г ізбавля́ємся, / с ві́рою приє́млюще я, і взива́юще: // ра́дуйся, Арте́міє Богому́дре."]},{"h":"Молитва перша","ps":["Святи́й уго́дниче Бо́жий, пра́ведний Арте́міє, при́сний храни́телю святи́я ві́ри Правосла́вния і бли́зький защи́тниче всего́ сі́вернаго кра́я Українськия страни́! При́зри ми́лостивно на усе́рдную моли́тву нас грі́шних і твої́м благомо́щним предста́тельством іспроси́ нам у Го́спода проще́ніє согріше́ній на́ших, преспі́яніє во ві́рі і благоче́стії і огражде́ніє от ко́зней дия́вольських. Моли́ Го́спода, да храни́ть во здра́вії і непреміня́ємім благополу́чії ві́рних люде́й Свої́х, да пода́сть страні́ на́шей мир і тишину́, а нам нелицемі́рноє послуша́ніє, да сподо́бит всіх нас получи́ти, по христия́нстій кончи́ні, Небе́сноє Ца́рствіє, іді́же всі пра́веднії вмі́сті с тобо́ю, ві́чно сла́в'ять Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий уго́дниче Бо́жий, святи́й пра́ведний Арте́міє, покрови́телю святи́я оби́телі, твої́м і́менем красу́ющіяся, си́льний хода́таю о нас ко Го́споду, вели́кий благоді́телю і живу́щих зді і́ноков твоєя́ оби́телі і всіх с ві́рою і любо́вію притека́ющих к ра́ці чудотво́рних моще́й твої́х! При́зри ми́лостивно на убо́гую моли́тву нас, грі́шних і непотре́бних рабо́в, і твої́м всемо́щним предста́тельством іспроси́ нам у Го́спода проще́ніє гріхо́в, преспі́яніє во ві́рі і благоче́стії і огражде́ніє от ко́зней супоста́та, і́щущаго нас погуби́ти. Да́руй бра́тству твоєя́ оби́телі, от ста́рших до послі́дніх, смире́ніє і кро́тость, любо́в і послуша́ніє вседу́шноє, служе́ніє і житіє́ благогові́йноє, свято́є і во всем ві́рноє і благоду́шноє ісполне́ніє і́ночеськаго общежи́тія, да, рабо́тающе Го́сподеві непости́дно і ду́хом горя́ще в непреста́нній моли́тві за благотвори́телей на́ших живи́х і усо́пших, яви́мся ві́рними раба́ми Го́спода, да Це́рков Правосла́вная всея́ України, я́ко вертогра́д благонасажде́нний, цвіте́ть і плодотвори́ть бога́то плода́ми ві́ри і благоче́стія! Моли́ Го́спода, да храни́ть во здра́вії, душе́внім спасе́нії і благопоспіше́нії во всем правосла́вний наро́д наш. Моли́ Го́спода о ми́лості і благода́тних щедро́тах Святі́йшему Патріа́рху на́шему (ім’я) і Святі́йшему Сино́ду на́шему. Моли́ Го́спода, да хода́тайством і заступле́нієм преблагослове́нния Влади́чиці на́шея Богоро́диці все ми і зді ми́рноє і богоуго́дноє житіє́ поживе́м і по ми́рній христия́нстій кончи́ні сподо́бимся в пресла́внім Ца́рствії ми́лости Царя́ Не́ба і землі́. Отця́ і Си́на і Свята́го Ду́ха, сла́в'яще Єго́ ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О великосла́вний уго́дниче Бо́жий, о вели́кий чудотво́рче, святи́й і пра́ведний Арте́міє, херуви́ме земни́й, челові́че небе́сний, а́нгелов собесі́дниче, небе́сний жи́телю! При́зри с висоти́ небе́сния сві́тлим о́ком твої́м, і ниспосли́ нам лучи́ Бо́жия благода́ті. Світи́льниче Боговозжже́нний, твої́ми святи́ми моли́твами разжени́ мрак гріхо́в на́ших, упроси́ у Отця́ сві́тов світ благода́ті душа́м на́шим, всіх правові́рних ско́рий бив помо́щник і засту́пник. Всяк бо, с ві́рою под кров защище́нія твоєго́ моли́твенно притека́яй і заступле́нія Твоєго́ у Го́спода прося́й, а́біє посо́бствуєм бива́єть, Бо́жию же ми́лость обріта́єть і жела́нія се́рдця своєго́ не лиша́ється, но про́сить благода́ті і приє́млеть дар на по́льзу проше́нія. Ти єси́, пра́ведний Арте́міє, вертогра́д Бо́гом насажде́нний, в не́мже цвіт здравотво́рний, процвіте́, є́же ісціли́тися мно́гим от зі́льнаго трясави́чнаго неду́га. О коль мно́зі твоє́ю чуде́сною по́мощію сліпі́ї прозрі́ша, глусі́ї слух прия́ша, хромі́ї возскочи́ша і ходя́ша, немощні́ї ді́йство рук прия́ша, безу́мнії воуми́шася, разсла́бленії в жи́лах укріпи́шася, сля́ченнії іспра́вишася і іму́щії вре́ди ісцілі́ша! Єще́ же і скве́рнії де́мони моли́твою твоє́ю отгна́шася, і іні́ї неісці́льнії неду́зі разріши́шася. Та́ко, святи́й і пра́ведний Арте́міє, всім всегда́ ми́лостив явля́єшися. У́бо і о нас неісповіди́мую Бо́жию бла́гость умоли́, да оста́вить нам Госпо́дь до́лги на́ша, і да храни́ть госуда́рство Українськоє в ми́рі і благоде́нствії, в крі́пості і оби́лії, і ві́ру правосла́вную да укріпи́ть, церко́вния же раско́ли да утоли́ть, і вся правосла́вния христия́ни да спасе́ть. Ми же твою́ па́м'ять святу́ю от ро́да в род че́стно пра́здновати бу́дем, сла́в'яще просла́вльшаго тя Христа́ Го́спода, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м і со Пресвяти́м і Благи́м і Животворя́щим Ду́хом, ни́ні і при́сно, і в безконе́чния ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта","ps":["Святи́й уго́дниче Бо́жий, Арте́міє пра́ведний! При́зри ми́лостивно на усе́рдную моли́тву нас, грі́шних (імена), і твої́м благомо́щним предста́тельством проще́ніє согріше́ній на́ших у Го́спода іспроси́, преспі́яніє же во ві́рі і благоче́стії і от ко́зней дия́вольських огражде́ніє ісхода́тствуй нам. Найпа́че же моли́ Го́спода, да сподо́бит всіх нас по христия́нстій кончи́ні Небе́сноє Ца́рство получи́ти, іді́же всі пра́веднії ку́пно с тобо́ю сла́в'ять Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобному Гавриїлу Ургебадзе","e":"Prayer to St Gabriel Urgebadze","secs":[{"h":"Тропар, глас 1","ps":["Я́коже Влади́ка Христо́с сла́ву Свою́ неізглаго́ланную / сокри́, пло́тію оді́явся, / та́коже і ти юро́дства вре́тищем покри́л єси́ / світ Фаво́рский і́мже Тя Госпо́дь осі́я / я́ко іспові́дника і страда́льця, / і па́стир душ яви́лся єси́, / о́тче преподо́бне Гавриї́ле, // моли́ Христа́ Бо́га поми́ловати ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Непости́жима єсть ми́лость Бо́жия, / Єго́же благода́тію созда́ніє обоже́но лицезрі́єм всі, / ти бо, преподо́бне о́тче, / о́браз Творця́ в себі́ утверди́л єси́, / возне́сши єстество́ своє́ в подо́біє Бо́жиє, / ті́мже сла́вим тя, о́тче Гавриї́ле, досто́йні похвали́, / я́ко бил єси́ на землі́ гла́сом пра́вди і го́лубем чистоти́, / жи́тельствовавши же в чу́дном смире́нії, / звені́л єси́ ли́рою му́дрості і любві́ орга́ном, / ни́ні же на небесі́х предста́тельствуєши о спасе́нії на́шем, // хода́таю Бо́жия благода́ті."]},{"h":"Молитва","ps":["О блаже́нне Гавриї́ле, дре́внім отце́м подо́бниче і тве́рдий ві́ри іспові́дниче, от младе́нства Го́спода всім се́рдцем возлюби́вий і ре́вностно Єму́ послі́довавий! Ми же, я́ко раби́ недосто́йнії, благоче́стія і смире́нія не іму́щії, оба́че себе́ на всяк день в душі́ велича́ющії, бли́жніх осужда́ющії, не і́мами пред Бо́гом, чим оправда́тися! Сего́ ра́ди мо́лим тя: моли́ за нас Го́спода, да пода́сть нам ум, сло́во Єго́ разумі́ти, да бу́дем не то́кмо сли́шателіє, но і ре́вностнії єго́ творці́, і да разумі́єм, я́ко нічесо́же мо́жем, кромі́ по́мощі Бо́жия. Єй, свя́тче Бо́жий! Помози́ нам Го́спода возлюби́ти і Тому́ приліпи́тися все́ю душе́ю своє́ю, всім се́рдцем і помишле́нієм, да пода́сть нам ра́дость, мир, долготерпі́ніє і утіше́ніє в ско́рбіх по неізрече́нній Своє́й ми́лості, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва старця Гавриїла","ps":["Господи, благаю Тебе, з небес почуй нас, поглянь на нас, подай милість Свою, з миром відпусти нас, щоб ми ходили Твоїм шляхом, виконували заповіді Твої й зрікалися зла. Навчи нас, Господи, молитися перед Тобою й виконувати Твій святий закон, щоб серце наше стало віддане Тобі й усім нам жити за святим законом Твоїм."]}],"notes":[]},{"u":"Молитва святому апостолу Андрію Первозваному","e":"Prayer to the Holy Apostle Andrew the First-Called","secs":[{"h":"Тропар, глас 4","ps":["Я́ко апо́столов первозва́нний / і верхо́внаго су́щий брат, / Влади́ці всіх, Андре́є, моли́ся / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Му́жества тезоімени́таго Богоглаго́льника / і Це́ркве возслі́дователя верхо́внаго, / Петро́ва сро́дника восхва́лим, / зане́ я́коже дре́вле сему́, і ни́ні нам воззва́: // прийді́те, обріто́хом жела́ємаго."]},{"h":"Молитва","ps":["Первозва́нне апо́столе Бо́га і Спа́са на́шего Ісу́са Христа́, Це́ркве послі́дователю верхо́вний, всехва́льне Андре́є, сла́вим і велича́єм апо́стольськія труди́ твоя́, сла́дці помина́єм твоє́ благослове́нноє к нам прише́ствіє, ублажа́єм честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́, лобиза́єм свяще́нния мо́щі твоя́, чтим святу́ю па́м'ять твою́ і ві́руєм, я́ко жив Госпо́дь, жива́ же і душа́ твоя́ і с Ним во ві́ки пребива́єши на Небесі́, іді́же і лю́биши ни то́южде любо́вію, є́юже возлюби́л єси́ нас, єгда́ Ду́хом Святи́м прозрі́л єси́ на́ше є́же ко Христу́ обраще́ніє, і не то́чію лю́биши, но і мо́лиши о нас Бо́га, зря во Сві́ті Єго́ вся ну́жди на́ша. Та́ко ві́руєм і та́ко сію́ ві́ру на́шу іспові́дуєм во хра́мі, і́же во і́м'я твоє́, святи́й Андре́є, пресла́вно созда́ся, іді́же святи́я мо́щі твоя́ почива́ють; ві́рующе же, про́сим і мо́лим Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́, да моли́твами твої́ми, я́же при́сно послу́шаєть і приє́млеть, пода́сть нам вся потре́бная ко спасе́нію нас грі́шних; да я́коже ти а́біє по гла́су Го́спода, оста́вль мре́жі своя́, неукло́нно Єму́ послі́довал єси́, си́це і ки́йждо от нас да і́щеть не свої́х сих, но є́же к созида́нію бли́жняго і о го́рнем зва́нії да помишля́єть. Іму́ще же тя предста́теля і моли́твенника о нас, упова́єм, я́ко моли́тва твоя́ мно́го мо́жеть пред Го́сподем і Спаси́телем на́шим Ісу́сом Христо́м, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]}],"notes":[]}];
export default D;
